var e=JSON.parse(`{"1009":{"meaning":"탑승 수속, 체크인","example":"Check-in opens two hours before your flight departs.","exampleTranslation":"체크인은 비행기 출발 두 시간 전에 시작해요."},"1011":{"meaning":"도착","example":"Our arrival was delayed by an hour because of the storm.","exampleTranslation":"폭풍 때문에 도착이 한 시간 지연됐어요."},"2024":{"meaning":"후속 조치를 하다","example":"I will follow up with you next week.","exampleTranslation":"다음 주에 다시 연락드릴게요."},"2048":{"meaning":"원격의","example":"Our team is fully remote, so we rarely meet in person.","exampleTranslation":"우리 팀은 전원 원격 근무라서 직접 만날 일이 거의 없어요."},"3049":{"meaning":"처리량","example":"The new cache doubled our throughput during peak hours.","exampleTranslation":"새 캐시 덕분에 피크 시간대 처리량이 두 배가 됐어요."},"3050":{"meaning":"가동 시간","example":"Our uptime stayed above 99.9 percent last month.","exampleTranslation":"지난달 저희 가동 시간은 99.9% 이상을 유지했어요."},"4011":{"meaning":"시도; 시도하다","example":"This is our second attempt to reach an agreement.","exampleTranslation":"이번이 합의에 이르기 위한 두 번째 시도예요."},"4034":{"meaning":"비용, 경비","example":"Please submit your travel expense report by the end of the month.","exampleTranslation":"월말까지 출장 경비 보고서를 제출해 주세요."},"4040":{"meaning":"문의","example":"Please direct your inquiry to our customer support team.","exampleTranslation":"문의는 저희 고객 지원팀으로 보내 주세요."},"5002":{"meaning":"점심","example":"Let's have lunch together tomorrow if you're free.","exampleTranslation":"시간 되면 내일 점심 같이 먹어요."},"5015":{"meaning":"구이; 굽다 (직화)","example":"Let's grill some chicken in the backyard tonight.","exampleTranslation":"오늘 저녁에 뒷마당에서 닭고기 좀 구워 먹어요."},"5020":{"meaning":"맛있는","example":"That was the most delicious soup I've ever had.","exampleTranslation":"지금까지 먹어 본 수프 중에 제일 맛있었어요."},"5022":{"meaning":"채소","example":"Try to eat at least one vegetable with every meal.","exampleTranslation":"끼니마다 채소를 적어도 한 가지는 먹도록 하세요."},"6005":{"meaning":"걷다; 산책","example":"Let's go for a walk after dinner tonight.","exampleTranslation":"오늘 저녁 먹고 산책하러 가요."},"6009":{"meaning":"근육","example":"I pulled a muscle in my back while lifting weights.","exampleTranslation":"웨이트를 들다가 등 근육이 결렸어요."},"6029":{"meaning":"건강 검진","example":"I get a full checkup at the hospital every January.","exampleTranslation":"저는 매년 1월에 병원에서 종합 건강 검진을 받아요."},"7006":{"meaning":"외국인","example":"As a foreigner, you must carry your passport with you here.","exampleTranslation":"외국인은 이곳에서 여권을 늘 지니고 다녀야 해요."},"7022":{"meaning":"계좌","example":"There is very little money left in my account.","exampleTranslation":"제 계좌에 돈이 거의 남아 있지 않아요."},"7026":{"meaning":"송금하다; 이체","example":"Please transfer the rent to my bank account by Friday.","exampleTranslation":"금요일까지 제 은행 계좌로 집세를 송금해 주세요."},"7033":{"meaning":"역, 정류장","example":"I will meet my friend at the station at six.","exampleTranslation":"6시에 역에서 친구를 만날 거예요."},"7045":{"meaning":"해외 거주자, 외국인 거주자","example":"As an expat, I had to learn how to pay bills here.","exampleTranslation":"해외 거주자로서 저는 이곳에서 요금 내는 법을 배워야 했어요."},"8014":{"meaning":"대량 구매","example":"We did a bulk buy of paper towels at Costco to save money.","exampleTranslation":"돈을 아끼려고 코스트코에서 키친타월을 대량으로 샀어요."},"8046":{"meaning":"한정판","example":"These sneakers are a limited edition, so only five hundred pairs were made.","exampleTranslation":"이 운동화는 한정판이라 500켤레만 만들어졌어요."},"8048":{"meaning":"나눠서 결제하다; 각자 내다","example":"There are three of us, so can we split the bill three ways?","exampleTranslation":"저희 세 명인데 셋이 나눠서 계산해도 될까요?"},"8052":{"meaning":"증상","example":"Which symptom bothers you the most right now?","exampleTranslation":"지금 어떤 증상이 가장 불편하세요?"},"8057":{"meaning":"구역질; 메스꺼움","example":"I've had nausea every morning this week.","exampleTranslation":"이번 주 내내 아침마다 속이 메스꺼웠어요."},"8070":{"meaning":"염좌; 삠","example":"The X-ray showed no fracture, so it's just a sprain.","exampleTranslation":"엑스레이상 골절은 없어서 그냥 염좌예요."},"8071":{"meaning":"봉합 실밥; 꿰맴","example":"It was only a small cut, but it still needed one stitch.","exampleTranslation":"작은 상처였지만 그래도 한 바늘 꿰매야 했어요."},"8085":{"meaning":"퇴원시키다; 퇴원","example":"The doctor will discharge the patient from the hospital today.","exampleTranslation":"의사가 오늘 환자를 퇴원시킬 거예요."},"8091":{"meaning":"복제약의; 제네릭의","example":"Is there a generic version of this drug available?","exampleTranslation":"이 약의 복제 의약품이 있나요?"},"8099":{"meaning":"식후에 복용하다","example":"Which pills do I take after meals, and which ones before?","exampleTranslation":"어떤 약을 식후에 먹고, 어떤 약을 식전에 먹어야 하나요?"},"8107":{"meaning":"번아웃된; 극도로 지쳐 의욕을 잃은","example":"She feels burned out after months of overtime work.","exampleTranslation":"몇 달간 야근을 하고 나서 그녀는 완전히 번아웃된 상태예요."},"8123":{"meaning":"(감정적으로) 무너지다; 울음을 터뜨리다","example":"He started to break down when he heard the eulogy.","exampleTranslation":"추도사를 듣자 그는 울음을 터뜨리기 시작했어요."},"8129":{"meaning":"잔뜩 긴장한; 신경이 팽팽한","example":"I was totally wound up before the presentation.","exampleTranslation":"발표 전에 완전히 긴장해 있었어요."},"8133":{"meaning":"어쩔 줄 모르는; 갈피를 못 잡는","example":"I was at a loss for words when I heard the news.","exampleTranslation":"그 소식을 듣고 무슨 말을 해야 할지 몰랐어요."},"8139":{"meaning":"후회하는; 유감스러운","example":"She sounded regretful when she talked about leaving her old job.","exampleTranslation":"그녀는 예전 직장을 그만둔 이야기를 할 때 후회하는 듯했어요."},"8141":{"meaning":"기뻐서 들뜬; 의기양양한","example":"He was elated when he received the scholarship offer.","exampleTranslation":"장학금 제안을 받고 그는 뛸 듯이 기뻐했어요."},"8153":{"meaning":"(전화를) 연결해주다","example":"Please hold while I put through your call to the manager.","exampleTranslation":"매니저에게 전화를 연결해 드릴 테니 잠시만 기다려 주세요."},"8157":{"meaning":"전화를 걸다; 번호를 누르다","example":"Please dial 9 first to get an outside line.","exampleTranslation":"외부로 전화하시려면 먼저 9번을 눌러 주세요."},"8159":{"meaning":"전화를 받다","example":"Nobody is going to pick up this late. Let me try again tomorrow.","exampleTranslation":"이렇게 늦으면 아무도 안 받을 거예요. 내일 다시 해 볼게요."},"8160":{"meaning":"(전화가) 연결되다; 통화가 이뤄지다","example":"I've been trying to get through all morning, but the line is still busy.","exampleTranslation":"아침 내내 연결하려고 했는데 아직도 통화 중이에요."},"8164":{"meaning":"짧은 메시지를 남기다; 연락하다","example":"Remember to drop a line to Grandma while you're traveling.","exampleTranslation":"여행하는 동안 할머니께 잊지 말고 짧게 연락드려."},"8181":{"meaning":"잘못 걸린 번호; 전화를 잘못 걸다","example":"Sorry, you have the wrong number. There's no one here by that name.","exampleTranslation":"죄송하지만 잘못 거셨어요. 여기 그런 이름을 가진 분은 없어요."},"8182":{"meaning":"통화 대기로 돌리다; 잠시 기다리게 하다","example":"I was put on hold for twenty minutes before anyone answered.","exampleTranslation":"누가 받기까지 20분 동안 대기 상태로 기다렸어요."},"8185":{"meaning":"통신망; 네트워크","example":"The network signal here is too weak for a video call.","exampleTranslation":"여기는 통신 신호가 너무 약해서 영상통화가 안 돼요."},"8190":{"meaning":"부재중인; 놓친","example":"I have three missed calls from my mom, so I should call her back.","exampleTranslation":"엄마한테서 부재중 전화가 세 통 와 있어서 다시 전화해 봐야겠어요."},"8194":{"meaning":"읽음 확인","example":"I turned off the read receipt feature so people can't see when I've read their messages.","exampleTranslation":"내가 메시지를 언제 읽었는지 사람들이 모르게 읽음 확인 기능을 꺼 뒀어요."},"8226":{"meaning":"자격 요건; 자격증","example":"A teaching qualification is required for this position.","exampleTranslation":"이 직무에는 교원 자격이 필요해요."},"8240":{"meaning":"압박 상황에서 일하다","example":"I am able to work under pressure and meet tight deadlines.","exampleTranslation":"저는 압박 상황에서도 일하며 촉박한 마감을 맞출 수 있어요."},"8248":{"meaning":"성장 기회; 발전 가능성","example":"For me, this role is a real growth opportunity.","exampleTranslation":"저에게 이 직무는 진정한 성장 기회예요."},"8254":{"meaning":"무슨 일을 하세요?; 직업이 뭐예요?","example":"So, what do you do for a living?","exampleTranslation":"그래서, 무슨 일을 하세요?"},"8264":{"meaning":"넷플릭스 보며 쉬다; (연인·데이트 맥락) 성적인 의미의 완곡 표현","example":"Be careful: when someone invites you to Netflix and chill, it usually means more than TV.","exampleTranslation":"조심하세요. 누가 넷플릭스 보며 쉬자고 하면 보통 TV만 보자는 뜻이 아니에요."},"8266":{"meaning":"별일 없어요?; 요즘 어때요?","example":"Hey, what's new with you these days?","exampleTranslation":"안녕, 요즘 어떻게 지내요?"},"8274":{"meaning":"어떻게 지내요?; 잘 돼 가요?","example":"Hey, how's it going? I haven't seen you in ages.","exampleTranslation":"안녕, 잘 지내요? 진짜 오랜만이에요."},"8278":{"meaning":"저도 할게요; 좋아요, 낄게요","example":"A beach trip this weekend? I'm in!","exampleTranslation":"이번 주말에 해변 여행이요? 저도 갈래요!"},"8289":{"meaning":"처음부터 잘 통하다; 죽이 잘 맞다","example":"We hit it off right away at the party.","exampleTranslation":"우리는 파티에서 처음부터 죽이 잘 맞았어요."},"8300":{"meaning":"즐겁게 지내다; 재미있게 놀다","example":"Have fun at the party tonight!","exampleTranslation":"오늘 밤 파티에서 재미있게 놀아요!"},"8303":{"meaning":"대로; 큰 거리","example":"Walk along Fifth Avenue until you reach the park.","exampleTranslation":"공원에 닿을 때까지 5번 대로를 따라 걸으세요."},"8304":{"meaning":"(버스·지하철 등에) 타다","example":"Get on the green line and ride it for three stops.","exampleTranslation":"초록색 노선을 타고 세 정거장 가세요."},"8310":{"meaning":"보행자","example":"Wait for the pedestrian signal before you cross the street.","exampleTranslation":"길을 건너기 전에 보행자 신호를 기다리세요."},"8316":{"meaning":"(차량에서) 내려주다","example":"Could you drop off my sister at the station on your way?","exampleTranslation":"가시는 길에 제 여동생을 역에 내려 주실 수 있어요?"},"8320":{"meaning":"(택시) 요금 미터기","example":"Could you please turn on the meter before we go?","exampleTranslation":"출발하기 전에 미터기 좀 켜 주시겠어요?"},"8350":{"meaning":"되돌아오는 지점; 회차 장소","example":"There is a turnaround at the end of this road if you miss the hotel.","exampleTranslation":"호텔을 지나치면 이 길 끝에 차를 돌릴 수 있는 곳이 있어요."},"8367":{"meaning":"공증하다","example":"The bank can notarize this document for you for free.","exampleTranslation":"은행에서 이 서류를 무료로 공증해 줄 수 있어요."},"8376":{"meaning":"분실 신고하다","example":"You can report lost cards by phone 24 hours a day.","exampleTranslation":"카드 분실 신고는 24시간 전화로 할 수 있어요."},"8429":{"meaning":"논의를 위해서; 가정하여 말하자면","example":"For the sake of argument, let's say the budget doubles next year.","exampleTranslation":"논의를 위해서, 내년에 예산이 두 배가 된다고 가정해 봐요."},"8435":{"meaning":"장단점; 찬반 의견","example":"Let's weigh the pros and cons before deciding.","exampleTranslation":"결정하기 전에 장단점을 따져 봐요."},"8439":{"meaning":"~라는 의견이다; ~라고 생각하다","example":"Most board members seem to be of the opinion that we should wait.","exampleTranslation":"이사 대부분은 기다려야 한다는 의견인 것 같아요."},"8444":{"meaning":"~을 지지하다; ~을 옹호하다","example":"Our union will continue to advocate for more flexible schedules.","exampleTranslation":"우리 노조는 앞으로도 더 유연한 근무 일정을 지지하고 요구할 거예요."},"8447":{"meaning":"잘못 전달하다; 왜곡하다","example":"Please don't misrepresent my position when you talk to the board.","exampleTranslation":"이사회에 이야기할 때 제 입장을 왜곡하지 말아 주세요."},"8448":{"meaning":"섣불리 결론 내리다; 속단하다","example":"Let's not jump to conclusions before we check the facts.","exampleTranslation":"사실을 확인하기 전에 속단하지 말아요."},"8458":{"meaning":"보상하다; 만회하다","example":"Sorry I missed the meeting; I'll make up for it tomorrow.","exampleTranslation":"회의에 빠져서 죄송해요. 내일 만회할게요."},"8462":{"meaning":"귀찮게 하다; 번거롭게 하다","example":"I hate to bother you, but could you check this for me?","exampleTranslation":"번거롭게 해서 죄송한데, 이것 좀 확인해 주실 수 있어요?"},"8471":{"meaning":"(부탁을 들어) 도와주다; 은혜를 베풀다","example":"I asked the waiter for a quieter table, and he was happy to oblige.","exampleTranslation":"웨이터에게 더 조용한 자리를 부탁했더니 기꺼이 들어줬어요."},"8472":{"meaning":"대단히 감사합니다","example":"Thank you for holding the door for me; I'm much obliged.","exampleTranslation":"문을 잡아 주셔서 정말 감사합니다."},"8520":{"meaning":"(스피커·전구 등이) 나간; 터진","example":"The left speaker is blown out, so the music sounds terrible.","exampleTranslation":"왼쪽 스피커가 나가서 음악 소리가 엉망이에요."},"8544":{"meaning":"가전제품; 전자기기","example":"Every appliance in the apartment, including the washer, is brand new.","exampleTranslation":"세탁기를 포함해 이 아파트의 모든 가전제품이 새것이에요."},"8569":{"meaning":"몹시 뜨거운, 타는 듯이 더운","example":"It was scorching hot at the beach, so we stayed in the shade all day.","exampleTranslation":"해변이 타는 듯이 더워서 온종일 그늘에만 있었어요."},"8570":{"meaning":"얼어붙을 듯이 추운","example":"I had no idea it would be freezing outside, so I only wore a light jacket.","exampleTranslation":"밖이 얼어붙을 듯이 추울 줄 모르고 얇은 재킷만 입고 나왔어요."},"8579":{"meaning":"구름 덮임, 운량","example":"Heavy cloud cover kept temperatures cooler than usual for this time of year.","exampleTranslation":"구름이 두껍게 덮여서 이맘때치고는 기온이 평소보다 낮았어요."},"8588":{"meaning":"식다, 기온이 내려가다; 몸을 식히다","example":"It will cool down significantly once the sun sets.","exampleTranslation":"해가 지면 기온이 꽤 많이 내려갈 거예요."},"8596":{"meaning":"계절적인, 계절에 따른","example":"Cooler nights are a sure sign of the seasonal change from summer to fall.","exampleTranslation":"밤이 선선해지는 건 여름에서 가을로 넘어가는 계절 변화의 확실한 신호예요."},"8598":{"meaning":"몸이 좀 안 좋은, 컨디션이 나쁜","example":"I've been feeling under the weather ever since the temperature dropped last week.","exampleTranslation":"지난주에 기온이 뚝 떨어진 이후로 몸이 계속 좋지 않아요."},"8611":{"meaning":"모닝콜","example":"Could I get a wake-up call at six thirty, please?","exampleTranslation":"여섯 시 반에 모닝콜 해 주실 수 있나요?"},"8612":{"meaning":"퇴실 시간","example":"Is checkout time at eleven or at noon?","exampleTranslation":"퇴실 시간이 11시인가요, 12시인가요?"},"8642":{"meaning":"객실 요금으로 달아 두다","example":"Guests can charge to the room at any of the hotel restaurants.","exampleTranslation":"투숙객은 호텔 내 어느 식당에서든 객실 요금으로 달아 둘 수 있어요."},"8645":{"meaning":"건네주다; 넘겨주다","example":"Please hand over your keycard at the front desk when you check out.","exampleTranslation":"퇴실하실 때 프런트에 카드키를 건네주세요."},"8647":{"meaning":"열쇠를 안에 두고 방에 못 들어가다","example":"I always double-check so I don't lock myself out of my room.","exampleTranslation":"카드키를 안에 두고 나와서 방에 못 들어가는 일이 없도록 항상 다시 확인해요."},"8650":{"meaning":"(잠자리를 위해) 이불을 젖혀 두다","example":"Housekeeping will turn down the bed while we're at dinner.","exampleTranslation":"저희가 저녁 식사하는 동안 객실 담당 직원이 잠자리를 준비해 줄 거예요."},"8652":{"meaning":"대기 명단","example":"They put our name on the waiting list and said it would be twenty minutes.","exampleTranslation":"대기 명단에 저희 이름을 올리고 20분 정도 걸린다고 했어요."},"8655":{"meaning":"오늘의 특선 요리","example":"Could you tell me what the daily special is?","exampleTranslation":"오늘의 특선 요리가 뭔지 알려 주시겠어요?"},"8658":{"meaning":"식이 제한","example":"Do you have a dietary restriction we should know about?","exampleTranslation":"저희가 알아야 할 식이 제한이 있으신가요?"},"8677":{"meaning":"(음식이) 신선하지 않은; 오래되어 딱딱해진","example":"The bread tasted a little stale.","exampleTranslation":"빵이 좀 오래돼서 딱딱했어요."},"8694":{"meaning":"손짓해 부르다","example":"I tried to flag down a server to ask for more water.","exampleTranslation":"물을 더 달라고 하려고 직원을 손짓해 불러 보려 했어요."},"8732":{"meaning":"결항된 항공편","example":"Passengers from the canceled flight were moved to the next one.","exampleTranslation":"결항된 항공편 승객들은 다음 항공편으로 옮겨졌어요."},"8740":{"meaning":"게이트 변경","example":"There was a last-minute gate change for our flight.","exampleTranslation":"저희 항공편 게이트가 막판에 바뀌었어요."},"8755":{"meaning":"대여 계약서","example":"Please sign the rental agreement here.","exampleTranslation":"여기 대여 계약서에 서명해 주세요."},"8772":{"meaning":"주차 위반 딱지","example":"I got a parking ticket for staying past the two-hour limit.","exampleTranslation":"2시간 제한을 넘겨 주차해서 주차 위반 딱지를 받았어요."},"8794":{"meaning":"견인차를 부르다","example":"Our car broke down, so we had to call a tow truck.","exampleTranslation":"차가 고장 나서 견인차를 불러야 했어요."},"8813":{"meaning":"(전기·수도·가스 등을) 개통하다; 신청하다","example":"We need to set up utilities before we move in.","exampleTranslation":"입주하기 전에 전기·수도·가스를 개통해야 해요."},"8831":{"meaning":"(주택·자동차 구입 시) 계약금; 선금","example":"We made a down payment of ten percent when we bought the house.","exampleTranslation":"집을 살 때 계약금으로 10퍼센트를 냈어요."},"8853":{"meaning":"참석자","example":"Each attendee will get a name tag at the front desk.","exampleTranslation":"참석자는 각자 안내 데스크에서 이름표를 받게 돼요."},"8893":{"meaning":"업무를 위임하다","example":"When you're overloaded, delegate a task or two instead of doing everything yourself.","exampleTranslation":"일이 너무 많을 때는 모든 걸 혼자 하지 말고 업무를 한두 개 위임하세요."},"8914":{"meaning":"읽지 않은 메시지","example":"I still have an unread message from this morning.","exampleTranslation":"오늘 아침에 온 메시지를 아직 안 읽었어요."},"8926":{"meaning":"워드 문서","example":"Please send the contract as a Word document, not a PDF.","exampleTranslation":"계약서는 PDF 말고 워드 문서로 보내주세요."},"8927":{"meaning":"PDF 파일","example":"I converted the presentation into a PDF file.","exampleTranslation":"발표 자료를 PDF 파일로 변환했어요."},"8932":{"meaning":"이메일을 전달하다","example":"How do I forward an email to someone outside the company?","exampleTranslation":"회사 외부 사람에게 이메일을 전달하려면 어떻게 해요?"},"8955":{"meaning":"옆으로 스쳐 충돌하다; 측면 충돌","example":"Be careful not to sideswipe the parked cars on this narrow street.","exampleTranslation":"이 좁은 길에서는 주차된 차들을 옆으로 긁지 않게 조심하세요."},"8957":{"meaning":"(차량을) 뒤에서 들이받다","example":"Keep a safe distance so you don't rear-end the car in front of you.","exampleTranslation":"앞차를 뒤에서 들이받지 않도록 안전거리를 유지하세요."},"8958":{"meaning":"~와 충돌하다","example":"Slow down, or you might collide with the car in front of you.","exampleTranslation":"속도를 줄이세요, 안 그러면 앞차와 충돌할 수도 있어요."},"8959":{"meaning":"교통사고","example":"There was a traffic accident on the bridge this morning.","exampleTranslation":"오늘 아침 다리 위에서 교통사고가 났어요."},"8976":{"meaning":"도움을 요청하다","example":"If you see smoke, call for help right away.","exampleTranslation":"연기가 보이면 즉시 도움을 요청하세요."},"8977":{"meaning":"기절하다; 의식을 잃다","example":"I felt like I was going to pass out from the heat.","exampleTranslation":"더위 때문에 기절할 것 같았어요."},"8987":{"meaning":"발목을 삐다","example":"Be careful on these stairs, or you could twist an ankle.","exampleTranslation":"이 계단 조심하세요, 안 그러면 발목을 삘 수도 있어요."},"8992":{"meaning":"자연재해","example":"The region was hit by a major natural disaster this year.","exampleTranslation":"그 지역은 올해 큰 자연재해를 입었어요."},"9038":{"meaning":"텐트를 치다","example":"Have you ever tried to set up a tent in the rain?","exampleTranslation":"비 오는 날 텐트를 쳐 본 적 있어요?"},"9060":{"meaning":"후기를 작성하다","example":"Please take a moment to write a review once your order arrives.","exampleTranslation":"주문하신 상품을 받으시면 잠시 시간을 내어 후기를 작성해 주세요."},"9070":{"meaning":"배송 실패","example":"I got a missed delivery notice because nobody was home to sign.","exampleTranslation":"서명할 사람이 집에 없어서 배송 실패 안내문을 받았어요."},"9083":{"meaning":"할부 결제; 할부금","example":"The store let me make an installment payment every month for a year.","exampleTranslation":"그 가게에서 1년 동안 매달 할부금을 나눠 낼 수 있게 해 줬어요."},"9087":{"meaning":"고객센터 채팅","example":"I asked about my missing order through the customer support chat.","exampleTranslation":"도착하지 않은 주문 건을 고객센터 채팅으로 문의했어요."},"9090":{"meaning":"이메일 수신을 해지하다","example":"You can unsubscribe from emails by clicking the link at the bottom of any message.","exampleTranslation":"메시지 하단의 링크를 누르면 이메일 수신을 해지하실 수 있어요."},"9100":{"meaning":"비대면 배송","example":"We chose contactless delivery, so the driver left the box at the door.","exampleTranslation":"비대면 배송을 선택해서 기사님이 상자를 문 앞에 두고 갔어요."},"9104":{"meaning":"입다; 착용하다; 바르다","example":"You should put on a jacket. It's cold outside.","exampleTranslation":"재킷을 입는 게 좋겠어요. 밖이 추워요."},"9107":{"meaning":"계속하다; 진행되다","example":"Please go on with your presentation. We're all listening.","exampleTranslation":"발표를 계속해 주세요. 다들 듣고 있어요."},"9123":{"meaning":"우연히 만나다; 부딪히다","example":"If you go downtown, you might run into some old friends.","exampleTranslation":"시내에 가면 옛 친구들을 우연히 만날지도 몰라요."},"9126":{"meaning":"유지하다; (수준을) 계속하다","example":"Your grades are great this term. Keep up the good work!","exampleTranslation":"이번 학기 성적이 아주 좋네요. 계속 잘해 봐요!"},"9128":{"meaning":"억누르다; 저지하다; 주저하다","example":"Don't hold back. Just tell her how you really feel.","exampleTranslation":"망설이지 마. 그냥 그녀에게 진짜 마음을 말해."},"9130":{"meaning":"세상을 떠나다; 사망하다","example":"It's sad to watch the hero's mentor pass away in the final chapter.","exampleTranslation":"마지막 장에서 주인공의 스승이 세상을 떠나는 걸 보니 슬퍼요."},"9139":{"meaning":"버리다","example":"Don't throw away that box. I still need it.","exampleTranslation":"그 상자 버리지 마세요. 아직 필요해요."},"9154":{"meaning":"우연히 발견하다; 마주치다","example":"You might come across some old photos of us in that box.","exampleTranslation":"그 상자에서 우리 옛날 사진을 발견할지도 몰라요."},"9161":{"meaning":"기대하다; 고대하다","example":"I look forward to hearing from you soon.","exampleTranslation":"곧 연락 주시기를 기다리겠습니다."},"9178":{"meaning":"계속하다","example":"Don't mind me. Please carry on with your work.","exampleTranslation":"저는 신경 쓰지 말고 하던 일 계속하세요."},"9192":{"meaning":"괴롭히다; 트집 잡다","example":"Don't pick on your little brother just because he's smaller.","exampleTranslation":"동생이 작다고 괴롭히지 마."},"9212":{"meaning":"돌이켜보다; 회상하다","example":"I often look back on my college years with a smile.","exampleTranslation":"저는 대학 시절을 미소 지으며 돌이켜보곤 해요."},"9220":{"meaning":"요구하다; 필요로 하다","example":"Recipes like this usually call for fresh garlic.","exampleTranslation":"이런 요리법에는 보통 신선한 마늘이 들어가야 해요."},"9223":{"meaning":"벗어나다; 이탈하다","example":"The runner managed to break away from the pack.","exampleTranslation":"그 육상 선수는 무리에서 치고 나가는 데 성공했어요."},"9226":{"meaning":"잠깐 들르다; (의견을 들으려고) ~에게 말해 보다","example":"I'll run by the pharmacy on my way home.","exampleTranslation":"집에 가는 길에 약국에 잠깐 들를게요."},"9242":{"meaning":"이해하다; 유행하다","example":"I think this new dance trend will catch on with teenagers quickly.","exampleTranslation":"이 새로운 댄스 유행은 십 대들 사이에서 금방 퍼질 것 같아요."},"9244":{"meaning":"뒤처지다; 밀리다","example":"Try not to fall behind in your studies during the holidays.","exampleTranslation":"방학 동안 공부가 뒤처지지 않도록 하세요."},"9269":{"meaning":"우연히 발견하다","example":"If you hike that trail, you might stumble upon a hidden waterfall.","exampleTranslation":"그 등산로를 걷다 보면 숨겨진 폭포를 우연히 발견할지도 몰라요."},"9278":{"meaning":"(참여 등을) 빠지다; 거부하다","example":"Employees can opt out of the company newsletter at any time.","exampleTranslation":"직원들은 언제든지 회사 소식지 수신을 거부할 수 있어요."},"9279":{"meaning":"(결과가) 잘 풀리다","example":"I really hope this new marketing strategy will pan out.","exampleTranslation":"이번 새 마케팅 전략이 잘 풀렸으면 정말 좋겠어요."},"9395":{"meaning":"정가; 고정 가격","example":"Sorry, everything here is sold at a fixed price.","exampleTranslation":"죄송하지만, 여기는 전부 정찰제예요."},"9495":{"meaning":"(바짓단 등을) 줄이다; 단","example":"Can you hem these pants so they're two centimeters shorter?","exampleTranslation":"이 바지 단을 2센티 줄여 주실 수 있어요?"},"9519":{"meaning":"끊긴 통화","example":"I had another dropped call in the elevator this morning.","exampleTranslation":"오늘 아침 엘리베이터에서 또 통화가 끊겼어요."},"9608":{"meaning":"개인 레슨; 1:1 수업","example":"A private lesson costs more, but you get the teacher's full attention.","exampleTranslation":"개인 레슨은 더 비싸지만 선생님이 저한테만 집중해 줘요."},"9632":{"meaning":"단어를 찾아보다","example":"I always look up a word in the dictionary when I'm not sure what it means.","exampleTranslation":"뜻이 확실하지 않으면 항상 사전에서 단어를 찾아봐요."},"9637":{"meaning":"언어 교환","example":"I started a language exchange with a Thai student.","exampleTranslation":"태국 학생이랑 언어 교환을 시작했어요."},"9688":{"meaning":"털이 빠지다","example":"Huskies shed a lot every spring, so brush them often.","exampleTranslation":"허스키는 봄마다 털이 많이 빠지니까 자주 빗겨 주세요."},"9711":{"meaning":"취급 주의; 조심해서 다루다","example":"Could you put a \\"Handle with care\\" sticker on the box?","exampleTranslation":"상자에 '취급 주의' 스티커를 붙여 주실 수 있나요?"},"9749":{"meaning":"우편 주소; 받는 주소","example":"Please change my mailing address to my new office address.","exampleTranslation":"제 우편 주소를 새 사무실 주소로 변경해 주세요."},"10051":{"meaning":"끝; 끝나다","example":"The bathroom is at the end of the hall on the left.","exampleTranslation":"화장실은 복도 끝 왼쪽에 있어요."},"10066":{"meaning":"유지하다; 계속하다; 보관하다","example":"Please keep the door closed.","exampleTranslation":"문을 닫아 두세요."},"10100":{"meaning":"늘리다, 증가하다; 증가","example":"The company plans to increase our salaries next year.","exampleTranslation":"회사는 내년에 우리 월급을 올릴 계획이에요."},"10123":{"meaning":"수준, 단계; 높이","example":"What level is your English at right now?","exampleTranslation":"지금 영어 실력이 어느 단계예요?"},"10135":{"meaning":"꽤, 상당히","example":"I didn't expect much, but the movie was actually quite good.","exampleTranslation":"기대를 별로 안 했는데 그 영화는 사실 꽤 좋았어요."},"10139":{"meaning":"나이; 시대","example":"At what age did you start going to school?","exampleTranslation":"몇 살 때 학교에 들어갔어요?"},"10144":{"meaning":"공공의, 대중의; 대중","example":"We took public transportation to get downtown from the airport.","exampleTranslation":"우리는 공항에서 대중교통을 타고 시내로 갔어요."},"10164":{"meaning":"비율; 요금","example":"The hotel is offering a good rate this week.","exampleTranslation":"그 호텔은 이번 주에 요금이 괜찮아."},"10176":{"meaning":"기반, 토대; 거점, 본거지","example":"The hotel was a good base for exploring the city.","exampleTranslation":"그 호텔은 도시를 돌아보기에 좋은 거점이었어."},"10180":{"meaning":"힘; 전력","example":"The storm knocked out our power last night.","exampleTranslation":"어젯밤 폭풍 때문에 우리 집 전기가 끊겼어."},"10182":{"meaning":"중심; 센터","example":"Let's meet at the city center.","exampleTranslation":"시내 중심가에서 만나자."},"10189":{"meaning":"가치; 소중히 여기다","example":"This old watch has great sentimental value to me.","exampleTranslation":"이 낡은 시계는 나에게 정말 소중한 물건이야."},"10203":{"meaning":"수치, 숫자; 인물","example":"The final figure was much higher than we expected.","exampleTranslation":"최종 수치는 우리가 예상한 것보다 훨씬 높았어요."},"10209":{"meaning":"발전, 개발","example":"The city has seen rapid development in recent years.","exampleTranslation":"그 도시는 최근 몇 년간 빠르게 발전했어요."},"10212":{"meaning":"분; 잠깐","example":"Can you wait a minute for me? I'm almost ready.","exampleTranslation":"잠깐만 기다려 줄래요? 거의 다 준비됐어요."},"10218":{"meaning":"남다; 계속 ~인 채로 있다","example":"Please remain calm and walk to the nearest exit.","exampleTranslation":"침착하게 가장 가까운 출구로 걸어가 주세요."},"10226":{"meaning":"기간; 시기","example":"We had a long period of dry weather last summer.","exampleTranslation":"지난여름에는 건조한 날씨가 오래 이어졌어요."},"10249":{"meaning":"개인; 개별의","example":"Every individual in the class learns at a different pace.","exampleTranslation":"반 학생들은 한 명 한 명 배우는 속도가 달라요."},"10255":{"meaning":"규칙, 규정","example":"The most important rule is to have fun.","exampleTranslation":"가장 중요한 규칙은 즐기는 거예요."},"10257":{"meaning":"생산하다, 만들어 내다","example":"These local farms produce fresh milk and cheese for the whole region.","exampleTranslation":"이 지역 농장들은 지역 전체에 신선한 우유와 치즈를 생산해요."},"10258":{"meaning":"짧은; 키가 작은","example":"Let's take a short break now.","exampleTranslation":"지금 잠깐 쉬어요."},"10282":{"meaning":"아버지","example":"My father cooks dinner every Sunday.","exampleTranslation":"우리 아버지는 일요일마다 저녁을 차려 주셔."},"10296":{"meaning":"특정한; 특별한","example":"Is there a particular movie you want to see?","exampleTranslation":"특별히 보고 싶은 영화가 있어?"},"10307":{"meaning":"날짜; 데이트","example":"What date is your birthday party this year?","exampleTranslation":"올해 네 생일 파티는 며칠이야?"},"10316":{"meaning":"경제의; 경제적인","example":"The country is facing serious economic problems this year.","exampleTranslation":"그 나라는 올해 심각한 경제 문제에 직면해 있어."},"10336":{"meaning":"행동하다; 행동, 행위","example":"We need to act quickly before it's too late.","exampleTranslation":"너무 늦기 전에 빨리 행동해야 해요."},"10343":{"meaning":"목록, 명단","example":"I made a shopping list before going to the store.","exampleTranslation":"가게에 가기 전에 장보기 목록을 만들었어요."},"10346":{"meaning":"기금, 자금; 자금을 대다","example":"They set up a fund to help the school.","exampleTranslation":"그들은 학교를 돕기 위해 기금을 마련했어요."},"10350":{"meaning":"죽이다","example":"This spray can kill harmful insects in the garden.","exampleTranslation":"이 스프레이는 정원의 해로운 벌레를 죽일 수 있어요."},"10358":{"meaning":"공기; 공중","example":"Let's open the window and let in some fresh air.","exampleTranslation":"창문을 열고 신선한 공기 좀 들어오게 해요."},"10359":{"meaning":"이익, 혜택; 이득이 되다","example":"Regular exercise is of great benefit to your health.","exampleTranslation":"규칙적인 운동은 건강에 큰 도움이 돼요."},"10390":{"meaning":"노력, 수고","example":"Thank you for all your effort on this project.","exampleTranslation":"이 프로젝트에 애써 주셔서 감사합니다."},"10394":{"meaning":"거짓말; 거짓말하다","example":"He told a lie about where he was last night.","exampleTranslation":"그는 어젯밤 어디 있었는지에 대해 거짓말을 했어."},"10403":{"meaning":"100년; 세기","example":"This little church in our town is over a century old.","exampleTranslation":"우리 동네의 이 작은 교회는 지어진 지 100년이 넘었어요."},"10411":{"meaning":"이전의; 예전의","example":"My former teacher now runs a small bookstore.","exampleTranslation":"제 예전 선생님은 지금 작은 서점을 운영하세요."},"10427":{"meaning":"지식; 앎","example":"She has a deep knowledge of Korean history.","exampleTranslation":"그녀는 한국 역사에 대해 깊은 지식을 가지고 있어요."},"10434":{"meaning":"단순히; 그냥","example":"Simply press this button to start the machine.","exampleTranslation":"기계를 켜려면 그냥 이 버튼을 누르세요."},"10436":{"meaning":"세포; 작은 방","example":"Every living thing is made up of at least one cell.","exampleTranslation":"모든 생물은 적어도 하나의 세포로 이루어져 있어요."},"10453":{"meaning":"사적인; 개인의","example":"Can we talk in a private room?","exampleTranslation":"우리 따로 조용한 방에서 얘기할 수 있을까?"},"10465":{"meaning":"국제적인","example":"She works for an international company.","exampleTranslation":"그녀는 국제 기업에서 일해."},"10470":{"meaning":"구조; 구조물","example":"The old wooden structure was damaged in the storm.","exampleTranslation":"그 오래된 목조 구조물이 폭풍에 손상됐어."},"10484":{"meaning":"따라서; 그러므로","example":"Prices went up sharply; thus, sales fell last quarter.","exampleTranslation":"가격이 크게 올랐다. 따라서 지난 분기 매출이 떨어졌다."},"10485":{"meaning":"기술; 솜씨","example":"Cooking well takes a lot of skill.","exampleTranslation":"요리를 잘하려면 상당한 기술이 필요해."},"10512":{"meaning":"일어나다; 발생하다","example":"Mistakes like this can occur at any time.","exampleTranslation":"이런 실수는 언제든지 일어날 수 있다."},"10515":{"meaning":"약; 약물","example":"The doctor prescribed a new drug for my headaches.","exampleTranslation":"의사가 내 두통에 새 약을 처방해 주었다."},"10525":{"meaning":"알아보다; 인정하다","example":"I didn't recognize you with your new haircut.","exampleTranslation":"머리 스타일이 바뀌어서 못 알아봤어요."},"10529":{"meaning":"얻다; 늘리다","example":"You can gain a lot of experience from this job.","exampleTranslation":"이 일에서 많은 경험을 쌓을 수 있어요."},"10539":{"meaning":"물건; 항목","example":"Each item on the menu looks delicious.","exampleTranslation":"메뉴에 있는 음식 하나하나가 다 맛있어 보여요."},"10543":{"meaning":"물건; 것들","example":"Can you move your stuff off my desk?","exampleTranslation":"당신 물건 좀 제 책상에서 치워 줄래요?"},"10546":{"meaning":"방법; 방식","example":"This is the best method for learning new words.","exampleTranslation":"이게 새 단어를 배우는 가장 좋은 방법이에요."},"10547":{"meaning":"분석","example":"The lab sent us a detailed analysis of the water samples.","exampleTranslation":"연구소가 물 샘플에 대한 자세한 분석 결과를 보내 줬어요."},"10554":{"meaning":"국가; 나라","example":"The whole nation watched the final game on TV.","exampleTranslation":"온 국민이 TV로 결승전을 봤어요."},"10559":{"meaning":"소개하다; 도입하다","example":"Let me introduce you to my friend.","exampleTranslation":"제 친구한테 당신을 소개해 줄게요."},"10562":{"meaning":"결혼하다","example":"He asked her to marry him on the beach.","exampleTranslation":"그는 해변에서 그녀에게 결혼해 달라고 청혼했어요."},"10581":{"meaning":"정도; (온도·각도의) 도; 학위","example":"She has a degree in computer science from a good university.","exampleTranslation":"그녀는 좋은 대학에서 컴퓨터 공학 학위를 받았어요."},"10583":{"meaning":"남편","example":"My husband cooks dinner every Friday.","exampleTranslation":"제 남편은 매주 금요일에 저녁을 해요."},"10588":{"meaning":"손실, 잃음; 패배","example":"The company suffered a huge loss last year.","exampleTranslation":"그 회사는 작년에 큰 손실을 입었어요."},"10595":{"meaning":"자연의; 자연스러운","example":"This juice contains only natural ingredients and no added sugar.","exampleTranslation":"이 주스에는 천연 재료만 들어 있고 설탕은 넣지 않았어요."},"10621":{"meaning":"연결망; 인맥","example":"The Wi-Fi network in our office is down again.","exampleTranslation":"사무실 와이파이가 또 끊겼어요."},"10633":{"meaning":"선택지; 선택권","example":"If the bus is too slow, another option is to take the train.","exampleTranslation":"버스가 너무 느리면 기차를 타는 것도 방법이에요."},"10645":{"meaning":"의심; 의심하다","example":"I doubt he'll come to the party.","exampleTranslation":"그가 파티에 올 것 같지 않아요."},"10665":{"meaning":"내내; 곳곳에","example":"It rained throughout the weekend, so we stayed inside.","exampleTranslation":"주말 내내 비가 와서 우리는 집 안에 있었어요."},"10667":{"meaning":"원피스; 옷을 입다","example":"She is wearing a beautiful red dress tonight.","exampleTranslation":"그녀는 오늘 밤 아름다운 빨간 원피스를 입고 있어요."},"10675":{"meaning":"균형; 잔액","example":"It's hard to keep a good balance between work and family.","exampleTranslation":"일과 가정 사이에서 균형을 잘 유지하기는 어려워요."},"10684":{"meaning":"반사하다; 곰곰이 생각하다","example":"Take some time to reflect on what you learned today.","exampleTranslation":"오늘 배운 것을 곰곰이 되돌아보는 시간을 가지세요."},"10694":{"meaning":"게시하다; 우편물","example":"I'll post the photos online later tonight.","exampleTranslation":"이따 밤에 사진을 온라인에 올릴게요."},"10701":{"meaning":"전문적인; 전문가","example":"You should get professional advice before you sign anything.","exampleTranslation":"무엇이든 서명하기 전에 전문가의 조언을 받아야 해요."},"10712":{"meaning":"더 좋아하다; 선호하다","example":"I prefer coffee to tea in the morning.","exampleTranslation":"저는 아침에 차보다 커피를 더 좋아해요."},"10714":{"meaning":"가능성; 있을 법한 일","example":"There's a possibility of rain tomorrow, so bring an umbrella.","exampleTranslation":"내일 비가 올 가능성이 있으니 우산을 챙기세요."},"10718":{"meaning":"추적하다; 길·트랙","example":"I use an app to track my spending.","exampleTranslation":"저는 앱을 써서 제 지출을 기록해요."},"10721":{"meaning":"여성; 여성의","example":"Female students now outnumber male students at our school.","exampleTranslation":"우리 학교는 이제 여학생이 남학생보다 많다."},"10730":{"meaning":"달러","example":"The bus fare is only one dollar per ride.","exampleTranslation":"버스 요금은 한 번 타는 데 1달러밖에 안 해."},"10740":{"meaning":"모양; 형태","example":"The table is round in shape and fits nicely in the corner.","exampleTranslation":"그 테이블은 둥근 모양이라 구석에 딱 맞는다."},"10758":{"meaning":"붙이다; 달라붙다; (stick to) 고수하다; 막대기","example":"Just stick to the plan and everything will work out.","exampleTranslation":"그냥 계획대로 밀고 나가면 다 잘 될 거야."},"10760":{"meaning":"바람; 감다","example":"The wind blew my umbrella inside out on the way home.","exampleTranslation":"집에 오는 길에 바람 때문에 우산이 뒤집혔어요."},"10778":{"meaning":"의학의; 의료의","example":"She brought her medical records to her first appointment at the new clinic.","exampleTranslation":"그녀는 새 병원 첫 진료 때 진료 기록을 가지고 갔어요."},"10789":{"meaning":"라디오","example":"I like listening to the radio on my morning commute.","exampleTranslation":"나는 아침 출근길에 라디오 듣는 걸 좋아해요."},"10812":{"meaning":"매력; 호소하다","example":"For many young people, the appeal of living abroad is hard to resist.","exampleTranslation":"많은 젊은이들에게 해외 생활의 매력은 거부하기 어려워요."},"10818":{"meaning":"흐르다; 흐름","example":"The flow of the river was much stronger after the heavy rain.","exampleTranslation":"폭우가 내린 후 강물의 흐름이 훨씬 세졌어요."},"10827":{"meaning":"친척; 상대적인","example":"I'm meeting a relative I haven't seen in years.","exampleTranslation":"몇 년 동안 못 본 친척을 만날 거예요."},"10851":{"meaning":"규칙적인; 정기적인","example":"Regular walks after dinner help him sleep better at night.","exampleTranslation":"저녁 식사 후 규칙적으로 산책하는 것이 그가 밤에 더 잘 자는 데 도움이 돼요."},"10857":{"meaning":"비율; 퍼센트","example":"A large percentage of the students passed the exam this year.","exampleTranslation":"올해는 학생 중 상당수가 시험에 합격했어요."},"10858":{"meaning":"평화; 평온","example":"I just need some peace and quiet after such a long day.","exampleTranslation":"이렇게 긴 하루를 보낸 뒤에는 그냥 좀 조용히 쉬고 싶어요."},"10873":{"meaning":"흥분시키다; 설레게 하다","example":"Nothing seems to excite my kids more than a trip to the beach.","exampleTranslation":"우리 아이들을 바닷가 여행보다 더 설레게 하는 건 없는 것 같아요."},"10874":{"meaning":"독자; 읽는 사람","example":"Every reader of this blog gets a free e-book after signing up.","exampleTranslation":"이 블로그의 모든 독자는 가입하면 무료 전자책을 받아요."},"10882":{"meaning":"최고 책임자; 주된","example":"She talked to the police chief about the new safety policy.","exampleTranslation":"그녀는 새 안전 정책에 대해 경찰서장과 이야기했어."},"10903":{"meaning":"대조; 차이","example":"There is a sharp contrast between the busy city and the quiet countryside.","exampleTranslation":"붐비는 도시와 조용한 시골 사이에는 뚜렷한 대조가 있어."},"10912":{"meaning":"가스; 휘발유","example":"We stopped to get gas at a station just off the highway.","exampleTranslation":"우리는 고속도로 바로 옆 주유소에 들러 기름을 넣었어."},"10943":{"meaning":"상황; 환경","example":"Due to an unexpected circumstance, the concert has been postponed.","exampleTranslation":"예상치 못한 사정으로 콘서트가 연기되었다."},"10948":{"meaning":"대량의; 덩어리","example":"A huge mass of people gathered in the square to watch the fireworks.","exampleTranslation":"불꽃놀이를 보려고 엄청난 인파가 광장에 모였다."},"10965":{"meaning":"더하기; 게다가","example":"The room rate is $80 plus tax.","exampleTranslation":"객실 요금은 80달러에 세금이 별도로 붙어."},"10973":{"meaning":"문화적인; 문화의","example":"Visiting the old temples was a great cultural experience for me.","exampleTranslation":"오래된 절들을 방문한 건 나에게 멋진 문화 체험이었어."},"10991":{"meaning":"제안; 추천","example":"Thanks for the suggestion, the restaurant you mentioned was great.","exampleTranslation":"제안해 줘서 고마워, 네가 말한 식당 정말 좋았어."},"11002":{"meaning":"주제, 화제","example":"Climate change was the main topic of the discussion last night.","exampleTranslation":"어젯밤 토론의 주요 주제는 기후 변화였어요."},"11019":{"meaning":"길이; (시간의) 길이","example":"Please measure the length of the table before we buy a tablecloth.","exampleTranslation":"식탁보를 사기 전에 탁자의 길이를 재 주세요."},"11071":{"meaning":"돌; 돌멩이","example":"He picked up a flat stone and skipped it across the lake.","exampleTranslation":"그는 납작한 돌을 주워 호수 위로 물수제비를 떴어요."},"11088":{"meaning":"순환; 주기","example":"The washing machine is in the middle of its cycle.","exampleTranslation":"세탁기가 아직 한창 돌아가는 중이야."},"11091":{"meaning":"자유","example":"Living alone gives you a lot of freedom.","exampleTranslation":"혼자 살면 자유롭게 할 수 있는 게 많아."},"11092":{"meaning":"공사; 건설","example":"The road is closed because of construction nearby.","exampleTranslation":"근처 공사 때문에 도로가 통제됐어."},"11132":{"meaning":"경우; 특별한 행사","example":"We are saving this bottle of wine for a special occasion.","exampleTranslation":"우리는 이 와인을 특별한 날을 위해 아껴 두고 있어요."},"11137":{"meaning":"시민의; 민간의; 예의 바른","example":"They settled the dispute in civil court after months of arguing.","exampleTranslation":"그들은 몇 달간 다툰 끝에 민사 법원에서 분쟁을 해결했어요."},"11145":{"meaning":"군대; 부대; 무리","example":"Her son's scout troop went camping in the mountains last weekend.","exampleTranslation":"그녀 아들의 스카우트 대원들은 지난 주말 산으로 캠핑을 갔어요."},"11161":{"meaning":"신발; 구두","example":"She lost one shoe while running to catch the bus.","exampleTranslation":"그녀는 버스를 잡으려고 뛰다가 신발 한 짝을 잃어버렸다."},"11176":{"meaning":"불평하다; 항의하다","example":"Customers often complain that the soup at this place is too salty.","exampleTranslation":"손님들은 이 집 수프가 너무 짜다고 자주 불평한다."},"11185":{"meaning":"탐험하다; 살펴보다","example":"We had a whole day to explore the city on our own.","exampleTranslation":"우리는 하루 종일 자유롭게 도시를 둘러볼 수 있었다."},"11199":{"meaning":"피해자; 희생자","example":"Every victim of the flood received emergency help from the city.","exampleTranslation":"홍수 피해자 모두가 시로부터 긴급 지원을 받았다."},"11212":{"meaning":"추천; 권고","example":"Thanks to your recommendation, we found a great place for dinner.","exampleTranslation":"네 추천 덕분에 저녁 먹기 좋은 곳을 찾았어."},"11213":{"meaning":"순위; 등급; 순위를 매기다","example":"Players move up in rank as they win more games.","exampleTranslation":"선수들은 경기를 더 많이 이길수록 순위가 올라간다."},"11217":{"meaning":"주민; 거주자","example":"One local resident complained about the loud music late at night.","exampleTranslation":"한 지역 주민이 늦은 밤 시끄러운 음악에 대해 항의했다."},"11225":{"meaning":"구성되다; 이루어지다","example":"Most of their meals consist of rice, vegetables, and fish.","exampleTranslation":"그들의 식사는 대부분 밥, 채소, 생선으로 이루어져 있다."},"11229":{"meaning":"주장하다; 고집하다","example":"My grandmother will insist on paying for the whole meal.","exampleTranslation":"할머니는 식사비를 전부 내겠다고 고집하실 거다."},"11238":{"meaning":"그럼에도 불구하고; 그래도","example":"It was raining hard. Nevertheless, we went for a walk.","exampleTranslation":"비가 많이 왔다. 그래도 우리는 산책을 나갔다."},"11240":{"meaning":"이전에; 예전에","example":"I previously worked as a nurse at a hospital in Seoul.","exampleTranslation":"저는 이전에 서울의 한 병원에서 간호사로 일했어요."},"11246":{"meaning":"합리적인; 적당한","example":"The hotel price was very reasonable for a city center location.","exampleTranslation":"도심이라는 위치를 생각하면 호텔 가격이 꽤 적당했어요."},"11259":{"meaning":"면허(증); 허가","example":"You need a valid license to drive on public roads.","exampleTranslation":"일반 도로에서 운전하려면 유효한 면허증이 필요해요."},"11270":{"meaning":"협회; 연관; 연상","example":"She joined the local teachers' association last year.","exampleTranslation":"그녀는 작년에 지역 교사 협회에 가입했어요."},"11272":{"meaning":"투자자","example":"Every investor at the meeting wanted to hear more about the startup's plan.","exampleTranslation":"회의에 온 투자자들은 모두 그 스타트업의 계획을 더 듣고 싶어 했어요."},"11280":{"meaning":"기대; 예상","example":"The new restaurant lived up to every expectation we had.","exampleTranslation":"그 새 식당은 우리가 가졌던 모든 기대에 부응했다."},"11292":{"meaning":"생각; 개념","example":"The notion that money brings happiness is not always true.","exampleTranslation":"돈이 행복을 가져다준다는 생각이 항상 맞는 것은 아니다."},"11325":{"meaning":"입장; 항목; 출품작","example":"Entry to the museum is free on the first Sunday of every month.","exampleTranslation":"매달 첫째 주 일요일에는 박물관 입장이 무료다."},"11331":{"meaning":"비율; 균형","example":"A large proportion of students walk to school every day.","exampleTranslation":"학생 중 상당수가 매일 걸어서 학교에 다닌다."},"11340":{"meaning":"지시; 설명서; 교육","example":"Follow each instruction carefully when you put the furniture together.","exampleTranslation":"가구를 조립할 때 각 설명을 꼼꼼히 따르세요."},"11344":{"meaning":"분명히; 틀림없이","example":"Surely you don't have to leave so early tonight?","exampleTranslation":"오늘 밤 설마 그렇게 일찍 가야 하는 건 아니죠?"},"11354":{"meaning":"감소; 축소; 할인","example":"The new law led to a big reduction in traffic accidents.","exampleTranslation":"새 법 덕분에 교통사고가 크게 줄었다."},"11359":{"meaning":"어떻게든; 왠지","example":"I forgot my umbrella but somehow stayed dry all day.","exampleTranslation":"우산을 잊고 왔는데 어째서인지 하루 종일 비를 맞지 않았다."},"11368":{"meaning":"종교","example":"In this country, people are free to practice any religion they choose.","exampleTranslation":"이 나라에서는 사람들이 원하는 어떤 종교든 자유롭게 믿을 수 있습니다."},"11381":{"meaning":"매력적인; 눈길을 끄는","example":"The low price makes this apartment very attractive to young buyers.","exampleTranslation":"저렴한 가격 덕분에 이 아파트는 젊은 구매자들에게 매우 매력적입니다."},"11403":{"meaning":"이동 가능한; 휴대용의, 모바일의","example":"You can check your balance anytime on the bank's mobile app.","exampleTranslation":"은행 모바일 앱으로 언제든 잔액을 확인할 수 있어요."},"11415":{"meaning":"그러는 동안에; 한편","example":"She cooked dinner; meanwhile, her husband set the table.","exampleTranslation":"그녀는 저녁을 요리했고, 그동안 남편은 식탁을 차렸습니다."},"11432":{"meaning":"재산, 유산; 부동산","example":"Grandma left her entire estate to her three grandchildren.","exampleTranslation":"할머니는 전 재산을 손자녀 세 명에게 남겼습니다."},"11435":{"meaning":"살아 있는; 생생한","example":"The plant is still alive even though I forgot to water it last week.","exampleTranslation":"지난주에 물 주는 걸 잊었는데도 식물이 여전히 살아 있습니다."},"11443":{"meaning":"감정; 정서","example":"Her voice was full of emotion when she thanked her parents.","exampleTranslation":"부모님께 감사 인사를 할 때 그녀의 목소리는 감정이 북받쳐 있었습니다."},"11451":{"meaning":"냄새; 냄새가 나다","example":"The smell of fresh bread from the bakery filled the street.","exampleTranslation":"제과점에서 나는 갓 구운 빵 냄새가 거리를 가득 채웠습니다."},"11461":{"meaning":"광대한; 방대한","example":"There is a vast difference between knowing and actually doing.","exampleTranslation":"아는 것과 실제로 하는 것 사이에는 엄청난 차이가 있습니다."},"11481":{"meaning":"안녕","example":"Hi, is anyone home?","exampleTranslation":"안녕하세요, 집에 누구 계세요?"},"11507":{"meaning":"가정; 추정","example":"My assumption was that the store would be open on Sunday.","exampleTranslation":"저는 그 가게가 일요일에도 문을 열 거라고 짐작했어요."},"11512":{"meaning":"앞으로; (back and forth) 이리저리","example":"The kids ran back and forth across the yard all afternoon.","exampleTranslation":"아이들은 오후 내내 마당을 이리저리 뛰어다녔어요."},"11521":{"meaning":"집중; 농도","example":"Background noise really affects my concentration when I study.","exampleTranslation":"공부할 때 주변 소음이 제 집중력에 정말 영향을 줘요."},"11529":{"meaning":"무너지다; 쓰러지다","example":"After the long hike, I just wanted to collapse on the couch.","exampleTranslation":"긴 등산 후에 저는 그냥 소파에 쓰러지고 싶었어요."},"11532":{"meaning":"요리; 접시","example":"This dish is my grandmother's specialty.","exampleTranslation":"이 요리는 우리 할머니가 제일 잘하시는 음식이에요."},"11542":{"meaning":"구별하다; 식별하다","example":"It's hard to distinguish one twin from the other.","exampleTranslation":"쌍둥이 중 누가 누군지 구별하기가 정말 어렵다."},"11560":{"meaning":"마주치다; 맞닥뜨리다","example":"If you encounter any problems with the app, please contact us.","exampleTranslation":"앱을 쓰다가 문제가 생기면 저희에게 연락해 주세요."},"11578":{"meaning":"차지하다; 점유하다","example":"Video games occupy most of his free time these days.","exampleTranslation":"요즘은 비디오 게임이 그의 여가 시간 대부분을 차지한다."},"11581":{"meaning":"운; 행운","example":"I had no luck finding a parking spot downtown.","exampleTranslation":"시내에서 주차할 곳을 찾으려 했지만 운이 없었다."},"11593":{"meaning":"두 번째로; 다음으로","example":"First, the rent is too high, and secondly, it's too far from work.","exampleTranslation":"첫째, 월세가 너무 비싸고, 둘째, 회사에서 너무 멀어요."},"11596":{"meaning":"전망; 가능성","example":"She was excited by the prospect of living abroad.","exampleTranslation":"그녀는 해외에서 살게 된다는 생각에 설렜다."},"11604":{"meaning":"관례; 대회; 협약","example":"Shaking hands when you meet someone is a common social convention.","exampleTranslation":"누군가를 만날 때 악수하는 건 흔한 사회적 관례예요."},"11626":{"meaning":"지적인; 지식인","example":"She finds chess to be a stimulating intellectual challenge.","exampleTranslation":"그녀는 체스가 흥미진진한 지적 도전이라고 생각해요."},"11643":{"meaning":"찾다; 사냥하다","example":"She loves to hunt for bargains at flea markets.","exampleTranslation":"그녀는 벼룩시장에서 싼 물건을 찾아다니는 걸 좋아해."},"11653":{"meaning":"날개; 건물의 한 동","example":"The little bird had a broken wing, so it couldn't fly.","exampleTranslation":"작은 새가 날개가 부러져서 날 수 없었어."},"11683":{"meaning":"출판(물); 발행","example":"The magazine is a monthly publication for young travelers.","exampleTranslation":"그 잡지는 젊은 여행자를 위한 월간 간행물이다."},"11690":{"meaning":"동등한; 상당하는 것","example":"In terms of caffeine, one cup of coffee is roughly equivalent to three cans of cola.","exampleTranslation":"카페인으로 따지면 커피 한 잔은 콜라 세 캔과 거의 맞먹는다."},"11698":{"meaning":"음조; 던지다; (판매) 홍보","example":"Her voice rose in pitch when she got excited.","exampleTranslation":"그녀는 흥분하자 목소리 톤이 높아졌다."},"11709":{"meaning":"증상; 징후","example":"A headache can be an early symptom of dehydration.","exampleTranslation":"두통은 탈수의 초기 증상일 수 있다."},"11726":{"meaning":"제외하다; 배제하다","example":"The prices on this website exclude taxes and shipping fees.","exampleTranslation":"이 웹사이트의 가격에는 세금과 배송비가 빠져 있어요."},"11731":{"meaning":"웅장한; 멋진","example":"The hotel lobby was grand, with high ceilings and marble floors.","exampleTranslation":"그 호텔 로비는 천장이 높고 대리석 바닥이 깔려 있어 웅장했어요."},"11732":{"meaning":"그러므로; 따라서","example":"The main road is closed, hence the long detour through town.","exampleTranslation":"큰길이 막혀 있어서 시내를 거쳐 멀리 돌아가는 거예요."},"11750":{"meaning":"미터; 계량기","example":"The water in this part of the pool is only one meter deep.","exampleTranslation":"수영장의 이쪽은 물 깊이가 1미터밖에 안 돼요."},"11752":{"meaning":"코","example":"My nose gets runny every time I go out in the cold.","exampleTranslation":"추운 날 밖에 나갈 때마다 콧물이 줄줄 흘러요."},"11773":{"meaning":"붓다; 쏟아지다","example":"Could you pour me a glass of water, please?","exampleTranslation":"물 한 잔 따라 줄 수 있어요?"},"11788":{"meaning":"서쪽의; 서양의","example":"She moved to a small town in the western part of the state.","exampleTranslation":"그녀는 주 서부에 있는 작은 마을로 이사했어요."},"11796":{"meaning":"에세이; 논술문","example":"She stayed up late to finish her essay before the deadline.","exampleTranslation":"그녀는 마감 전에 에세이를 끝내려고 늦게까지 깨어 있었어요."},"11797":{"meaning":"비명을 지르다; 소리치다","example":"She started to scream when she saw the spider on the wall.","exampleTranslation":"벽에 붙은 거미를 보고 그녀는 비명을 지르기 시작했어요."},"11808":{"meaning":"제한; 규제","example":"There is a weight restriction of ten tons on this old bridge.","exampleTranslation":"이 오래된 다리에는 10톤 중량 제한이 있어요."},"11823":{"meaning":"곡; 선율","example":"I haven't been able to get that tune out of my head since this morning.","exampleTranslation":"아침부터 그 곡이 머릿속에서 떠나지 않아요."},"11827":{"meaning":"겁주다; 무섭게 하다","example":"Loud thunder can frighten young children during a storm.","exampleTranslation":"폭풍이 칠 때 큰 천둥소리는 어린아이들을 겁먹게 할 수 있어요."},"11843":{"meaning":"농업의; 농사와 관련된","example":"The region is known for its rich agricultural land.","exampleTranslation":"그 지역은 비옥한 농지로 유명하다."},"11856":{"meaning":"신(神); 하느님","example":"Many people pray to God when they face difficult times.","exampleTranslation":"많은 사람들이 힘든 시간에 신에게 기도한다."},"11858":{"meaning":"물질; 실질","example":"The label warned that the substance could be harmful.","exampleTranslation":"라벨에는 그 물질이 해로울 수 있다는 경고가 적혀 있었다."},"11877":{"meaning":"차원; 크기","example":"Measure each dimension of the box: length, width, and height.","exampleTranslation":"상자의 치수를 길이, 너비, 높이 하나하나 재세요."},"11887":{"meaning":"방송; 방송하다","example":"The game will be broadcast live on national television tonight.","exampleTranslation":"그 경기는 오늘 밤 전국 방송으로 생중계될 것이다."},"11908":{"meaning":"부츠; 장화","example":"My left boot has a hole in it, so my sock got wet.","exampleTranslation":"왼쪽 부츠에 구멍이 나서 양말이 젖었다."},"11947":{"meaning":"봉인하다; 밀봉; 물개","example":"Make sure to seal the envelope before you drop it in the mailbox.","exampleTranslation":"우편함에 넣기 전에 봉투를 꼭 봉하세요."},"11950":{"meaning":"특징짓다; 묘사하다","example":"How would you characterize your relationship with your manager?","exampleTranslation":"당신과 매니저의 관계를 어떻게 설명하시겠어요?"},"11954":{"meaning":"운영자; 교환원","example":"The tour operator arranged everything including hotels and transfers.","exampleTranslation":"그 여행사는 호텔과 이동편을 포함해 모든 것을 준비해 줬다."},"11962":{"meaning":"전문으로 하다; 특화하다","example":"This small bakery decided to specialize in sourdough bread.","exampleTranslation":"이 작은 빵집은 사워도우 빵을 전문으로 하기로 했어요."},"11968":{"meaning":"경쟁자; 맞수","example":"The bakery across the street is our biggest rival.","exampleTranslation":"길 건너 빵집이 우리의 가장 큰 경쟁자예요."},"11980":{"meaning":"보편적인; 전 세계적인","example":"Smiling is a universal sign of friendliness in almost every culture.","exampleTranslation":"미소는 거의 모든 문화에서 친근함을 나타내는 보편적인 표시예요."},"11981":{"meaning":"담배","example":"He smoked his last cigarette two years ago and never started again.","exampleTranslation":"그는 2년 전에 마지막 담배를 피운 뒤로 다시는 피우지 않았어요."},"11982":{"meaning":"구성하다; ~에 해당하다","example":"Women constitute more than half of the workforce here.","exampleTranslation":"여기서는 여성이 전체 직원의 절반 이상을 차지해요."},"11990":{"meaning":"민족의; 인종의","example":"The city has a rich mix of ethnic restaurants to explore.","exampleTranslation":"그 도시에는 가 볼 만한 다양한 민족 음식점이 많아요."},"11992":{"meaning":"임상의; 의료의","example":"The new drug passed clinical trials with promising results.","exampleTranslation":"그 신약은 임상 시험에서 유망한 결과를 내며 통과했어요."},"11998":{"meaning":"모래","example":"The kids spent the whole afternoon playing in the sand.","exampleTranslation":"아이들은 오후 내내 모래밭에서 놀았어요."},"12009":{"meaning":"종합적인, 포괄적인","example":"The book is a comprehensive guide to Korean home cooking.","exampleTranslation":"그 책은 한국 가정 요리에 대한 종합적인 안내서예요."},"12022":{"meaning":"능력, 역량","example":"This camera has the capability to record video in very low light.","exampleTranslation":"이 카메라는 아주 어두운 곳에서도 영상을 찍을 수 있는 성능을 갖추고 있어요."},"12056":{"meaning":"측정; 치수","example":"Write down each measurement before you go shopping for curtains.","exampleTranslation":"커튼 사러 가기 전에 치수를 하나하나 적어 두세요."},"12105":{"meaning":"무게를 재다; 무게가 나가다","example":"Could you weigh this bag for me before I check it?","exampleTranslation":"부치기 전에 이 가방 무게 좀 재 주시겠어요?"},"12120":{"meaning":"다치게 하다; 부상을 입히다","example":"Be careful not to injure your knee on those steep stairs.","exampleTranslation":"그 가파른 계단에서 무릎을 다치지 않게 조심하세요."},"12122":{"meaning":"오렌지; 주황색","example":"I peel an orange every morning with my breakfast.","exampleTranslation":"나는 매일 아침 식사와 함께 오렌지를 하나 까 먹는다."},"12148":{"meaning":"생물; 동물","example":"A strange creature with long legs crawled out from under the rock.","exampleTranslation":"다리가 긴 이상한 생물이 바위 밑에서 기어 나왔다."},"12152":{"meaning":"벌칙; 처벌","example":"There's a penalty for late payment on your bill.","exampleTranslation":"청구서를 늦게 내면 연체료가 부과된다."},"12176":{"meaning":"제약, 제한","example":"Our biggest constraint is time, not money.","exampleTranslation":"우리의 가장 큰 제약은 돈이 아니라 시간이에요."},"12180":{"meaning":"잠재적으로, 어쩌면","example":"The storm is potentially dangerous, so please stay indoors tonight.","exampleTranslation":"폭풍이 위험할 수 있으니 오늘 밤은 실내에 계세요."},"12191":{"meaning":"껍데기, 껍질; 조개껍데기","example":"She picked up a beautiful shell on the beach.","exampleTranslation":"그녀는 해변에서 예쁜 조개껍데기를 하나 주웠어요."},"12195":{"meaning":"한계, 제한","example":"The biggest limitation of this phone is its short battery life.","exampleTranslation":"이 휴대폰의 가장 큰 한계는 배터리가 오래가지 않는다는 거예요."},"12205":{"meaning":"규제하다; 조절하다","example":"The government needs to regulate the use of chemicals in food.","exampleTranslation":"정부는 식품에 쓰이는 화학 물질 사용을 규제할 필요가 있다."},"12206":{"meaning":"치즈","example":"Can you put extra cheese on my pizza, please?","exampleTranslation":"피자에 치즈를 더 넣어 주시겠어요?"},"12211":{"meaning":"깃발; 표시하다","example":"Each fan waved a small flag as the team walked onto the field.","exampleTranslation":"팀이 경기장에 들어서자 팬들은 저마다 작은 깃발을 흔들었다."},"12221":{"meaning":"축복하다; 은혜를 베풀다","example":"My grandmother asked the priest to bless her new house.","exampleTranslation":"할머니는 신부님께 새집을 축복해 달라고 부탁했다."},"12224":{"meaning":"할머니","example":"My grandmother taught me how to make her famous soup.","exampleTranslation":"할머니는 자신의 그 유명한 수프 만드는 법을 나에게 가르쳐 주셨다."},"12228":{"meaning":"구성; 작품","example":"The teacher praised the composition she wrote for class.","exampleTranslation":"선생님은 그녀가 수업 과제로 쓴 작문을 칭찬했다."},"12235":{"meaning":"바라건대; 희망적으로","example":"Hopefully the weather will be nice for the picnic.","exampleTranslation":"소풍 날 날씨가 좋았으면 좋겠다."},"12240":{"meaning":"초콜릿","example":"I always keep a bar of chocolate in my desk drawer.","exampleTranslation":"나는 항상 책상 서랍에 초콜릿 바 하나를 넣어 둔다."},"12275":{"meaning":"지침; 가이드라인","example":"Each guideline on this page explains one step of the application.","exampleTranslation":"이 페이지의 각 지침은 신청 절차의 한 단계를 설명한다."},"12281":{"meaning":"매주의; 주 1회의","example":"We have a weekly meeting on Monday mornings.","exampleTranslation":"우리는 월요일 아침마다 주간 회의가 있어."},"12289":{"meaning":"기진맥진하게 하다; 다 써버리다","example":"Climbing all those stairs will exhaust even the fittest hikers.","exampleTranslation":"그 많은 계단을 오르면 아무리 체력 좋은 등산객이라도 녹초가 될 거야."},"12310":{"meaning":"액체; 액상의","example":"This bottle can hold up to one liter of liquid.","exampleTranslation":"이 병에는 액체를 1리터까지 담을 수 있어."},"12331":{"meaning":"결백한; 순진한","example":"The investigation proved that he was innocent.","exampleTranslation":"조사 결과 그가 결백하다는 것이 밝혀졌어요."},"12332":{"meaning":"대체하다; 대용품","example":"You can substitute honey for sugar in this recipe.","exampleTranslation":"이 레시피에서는 설탕 대신 꿀을 써도 돼요."},"12343":{"meaning":"그늘; 색조","example":"Let's sit in the shade to cool down a bit.","exampleTranslation":"더위 좀 식히게 그늘에 앉아요."},"12345":{"meaning":"위치시키다; 배치하다","example":"Architects try to situate bedrooms away from street noise.","exampleTranslation":"건축가들은 침실을 거리 소음에서 떨어진 곳에 배치하려고 한다."},"12366":{"meaning":"그 후에; 나중에","example":"He left the company and subsequently started his own business.","exampleTranslation":"그는 회사를 그만둔 뒤 자기 사업을 시작했어."},"12370":{"meaning":"자격; 자격증","example":"A teaching qualification is required for this job.","exampleTranslation":"이 일에는 교원 자격이 필요해."},"12404":{"meaning":"모듈; 단위 구성 요소","example":"Each module in this course ends with a short quiz.","exampleTranslation":"이 강좌의 각 모듈은 짧은 퀴즈로 끝나요."},"12410":{"meaning":"활짝 웃다; 씩 웃음","example":"I couldn't help but grin when I heard the good news.","exampleTranslation":"좋은 소식을 듣고 나도 모르게 활짝 웃었어요."},"12411":{"meaning":"명사","example":"The word \\"dog\\" is a noun because it names an animal.","exampleTranslation":"'dog'라는 단어는 동물을 가리키므로 명사예요."},"13006":{"meaning":"산(酸); 신맛의","example":"The scientist wore thick gloves while handling the acid.","exampleTranslation":"과학자는 두꺼운 장갑을 끼고 산을 다뤘습니다."},"13017":{"meaning":"제휴하다; 가맹점","example":"The local clinic decided to affiliate with a major hospital network.","exampleTranslation":"지역 클리닉은 대형 병원 네트워크와 제휴하기로 결정했습니다."},"13033":{"meaning":"조상; 선조","example":"Her earliest known ancestor came from a small village in Ireland.","exampleTranslation":"그녀의 알려진 가장 오래된 조상은 아일랜드의 작은 마을 출신이었습니다."},"13060":{"meaning":"변호사; 법률 대리인","example":"The attorney advised her client not to speak to the press.","exampleTranslation":"변호사는 의뢰인에게 언론과 대화하지 말라고 조언했습니다."},"13066":{"meaning":"대로; 방법","example":"The main avenue through the city is lined with old trees.","exampleTranslation":"도시를 가로지르는 중앙 대로에는 오래된 나무들이 늘어서 있습니다."},"13072":{"meaning":"투표; 투표용지","example":"Each voter cast a ballot at the local polling station.","exampleTranslation":"유권자들은 각자 지역 투표소에서 투표했습니다."},"13075":{"meaning":"통; 배럴","example":"Each barrel of wine is aged for two years in a cool cellar.","exampleTranslation":"와인은 한 통 한 통 서늘한 저장고에서 2년간 숙성됩니다."},"13081":{"meaning":"낡고 망가진; 심하게 두드려진","example":"He found a battered old suitcase at the back of the garage.","exampleTranslation":"그는 차고 뒤편에서 낡고 찌그러진 여행 가방을 발견했습니다."},"13085":{"meaning":"배; 복부","example":"The puppy rolled over and showed us its belly for a rub.","exampleTranslation":"강아지가 몸을 뒤집어 배를 쓰다듬어 달라고 내밀었습니다."},"13087":{"meaning":"배신하다; 배반하다","example":"It hurt deeply when my closest friend chose to betray my trust.","exampleTranslation":"가장 친한 친구가 내 신뢰를 저버렸을 때 깊이 상처받았습니다."},"13101":{"meaning":"한계; 경계","example":"Her curiosity knows no bounds; she asks questions all day long.","exampleTranslation":"그녀의 호기심은 끝이 없어서 하루 종일 질문을 합니다."},"13107":{"meaning":"중개인; 브로커","example":"The broker helped us find a good deal on a new apartment.","exampleTranslation":"중개인 덕분에 새 아파트를 좋은 조건에 구할 수 있었습니다."},"13112":{"meaning":"전구; 알뿌리","example":"Please replace the burned-out bulb in the kitchen light.","exampleTranslation":"주방 조명의 나간 전구를 갈아 주세요."},"13116":{"meaning":"괴롭히는 사람; 약자를 괴롭히다","example":"The teacher stepped in when she noticed a bully harassing younger students.","exampleTranslation":"선생님은 어린 학생들을 못살게 구는 아이를 보고 끼어들었습니다."},"13121":{"meaning":"윙윙거리는 소리; 소문","example":"There was a buzz of excitement in the crowd before the concert started.","exampleTranslation":"콘서트가 시작되기 전 관중 사이에 들뜬 웅성거림이 감돌았습니다."},"13134":{"meaning":"만화; 만화 영화","example":"My kids watch their favorite cartoon every Saturday morning.","exampleTranslation":"우리 아이들은 매주 토요일 아침에 제일 좋아하는 만화를 봐요."},"13138":{"meaning":"주의; 경고","example":"The sign advised drivers to proceed with caution on the icy road.","exampleTranslation":"표지판은 운전자들에게 빙판길에서 조심해서 운전하라고 안내했습니다."},"13142":{"meaning":"묘지; 공동묘지","example":"The family visited the cemetery every year on the anniversary of her passing.","exampleTranslation":"가족은 매년 그녀의 기일에 묘지를 찾았습니다."},"13153":{"meaning":"턱; 아래턱","example":"He rested his chin on his hand while thinking.","exampleTranslation":"그는 생각에 잠겨 손으로 턱을 괴었어요."},"13162":{"meaning":"충돌하다; 부딪히다","example":"The two groups always clash over how the money should be spent.","exampleTranslation":"두 집단은 그 돈을 어떻게 쓸지를 두고 늘 충돌해요."},"13168":{"meaning":"매달리다; 달라붙다","example":"On humid days, my shirt tends to cling to my back.","exampleTranslation":"습한 날에는 셔츠가 등에 달라붙곤 해요."},"13172":{"meaning":"관; 棺","example":"The coffin was carried slowly by six pallbearers at the funeral.","exampleTranslation":"장례식에서 운구자 여섯 명이 관을 천천히 옮겼어요."},"13186":{"meaning":"보완하다; 완벽하게 맞다","example":"The white wine will complement the fish dish perfectly tonight.","exampleTranslation":"오늘 밤 화이트 와인이 생선 요리와 완벽하게 어울릴 거예요."},"13190":{"meaning":"단점; 사기; 속이다","example":"The only con of this apartment is the long commute.","exampleTranslation":"이 아파트의 유일한 단점은 통근 시간이 길다는 거예요."},"13193":{"meaning":"양보; 특허권; 매점","example":"Each side had to make a concession to reach an agreement.","exampleTranslation":"합의에 이르기 위해 양측은 각각 한 가지씩 양보해야 했어요."},"13195":{"meaning":"따르다; 순응하다","example":"New employees are expected to conform to the company's dress code.","exampleTranslation":"신입 사원들은 회사의 복장 규정을 따라야 해요."},"13201":{"meaning":"위로하다; 위안을 주다","example":"She tried to console her friend after his dog died.","exampleTranslation":"그녀는 반려견을 잃은 친구를 위로하려고 했습니다."},"13209":{"meaning":"반대의; 상반되는","example":"Contrary to popular belief, bats are not actually blind.","exampleTranslation":"흔히 알려진 것과 달리 박쥐는 사실 앞을 못 보는 동물이 아닙니다."},"13216":{"meaning":"부대; 단체","example":"The medical corps set up a field hospital near the border.","exampleTranslation":"의무 부대는 국경 근처에 야전 병원을 세웠습니다."},"13219":{"meaning":"대응하는 사람; 상대방","example":"The minister met with his counterpart from the neighboring country.","exampleTranslation":"장관은 이웃 나라의 상대 장관을 만났습니다."},"13236":{"meaning":"데뷔; 첫 등장","example":"The young singer made her debut on a popular TV show.","exampleTranslation":"그 젊은 가수는 인기 TV 프로그램에서 데뷔했습니다."},"13249":{"meaning":"빼앗다; 박탈하다","example":"Noisy neighbors can deprive you of a good night's sleep.","exampleTranslation":"시끄러운 이웃 때문에 밤에 푹 자지 못할 수 있습니다."},"13269":{"meaning":"구별하다; 차별화하다","example":"Even their mother can hardly differentiate between the identical twins.","exampleTranslation":"그 일란성 쌍둥이는 엄마조차 거의 구별하지 못합니다."},"13274":{"meaning":"줄이다; 줄어들다","example":"Regular exercise can diminish the risk of heart disease.","exampleTranslation":"규칙적인 운동은 심장 질환의 위험을 줄일 수 있습니다."},"13281":{"meaning":"낙담시키다; 단념하게 하다","example":"A bad grade should not discourage you from trying again.","exampleTranslation":"성적이 나쁘다고 다시 도전하기를 포기해서는 안 됩니다."},"13286":{"meaning":"왜곡하다; 변형하다","example":"Cheap speakers can distort the sound when the volume is too high.","exampleTranslation":"싸구려 스피커는 볼륨이 너무 높으면 소리가 찌그러질 수 있습니다."},"13297":{"meaning":"점; 작은 점","example":"Mark your location on the map with a red dot.","exampleTranslation":"지도에 빨간 점으로 현재 위치를 표시하세요."},"13299":{"meaning":"익사하다; 물에 빠지다","example":"Every summer, some swimmers drown because they ignore the warning flags.","exampleTranslation":"매년 여름 경고 깃발을 무시하다가 익사하는 사람들이 있습니다."},"13300":{"meaning":"이중의; 두 가지의","example":"This phone has a dual camera system for sharper photos.","exampleTranslation":"이 휴대폰은 더 선명한 사진을 위한 듀얼 카메라를 갖추고 있어요."},"13303":{"meaning":"거주하다; 살다","example":"Long ago, people used to dwell in caves along the river.","exampleTranslation":"아주 오래전 사람들은 강가의 동굴에서 살았어요."},"13329":{"meaning":"세우다; 건립하다; 직립의","example":"The city plans to erect a statue of the famous poet in the plaza.","exampleTranslation":"시는 광장에 그 유명한 시인의 동상을 세울 계획이에요."},"13336":{"meaning":"대피하다; 소개하다","example":"Authorities ordered residents to evacuate the area before the hurricane.","exampleTranslation":"당국은 허리케인이 오기 전에 주민들에게 그 지역에서 대피하라고 명령했어요."},"13337":{"meaning":"전날 밤; 전날","example":"We always watch the fireworks downtown on New Year's Eve.","exampleTranslation":"우리는 매년 마지막 날 밤에 시내에서 불꽃놀이를 봐요."},"13341":{"meaning":"외치다; 소리치다","example":"I heard her exclaim, \\"What a beautiful view!\\"","exampleTranslation":"그녀가 \\"경치 정말 멋지다!\\" 하고 외치는 소리가 들렸어요."},"13344":{"meaning":"발휘하다; 행사하다","example":"You need to exert more effort if you want to improve your grades.","exampleTranslation":"성적을 올리고 싶다면 더 노력해야 해요."},"13358":{"meaning":"여객선; 나룻배","example":"We took the ferry from the mainland to the island.","exampleTranslation":"우리는 본토에서 섬까지 여객선을 탔다."},"13368":{"meaning":"던지다; 내팽개치다","example":"Please don't fling your wet towel on the bed.","exampleTranslation":"젖은 수건을 침대 위에 휙 던져 놓지 마세요."},"13370":{"meaning":"밀가루","example":"This bread recipe calls for two cups of flour.","exampleTranslation":"이 빵 레시피에는 밀가루 두 컵이 들어간다."},"13372":{"meaning":"유체; 액체","example":"Brake fluid was leaking from under the car.","exampleTranslation":"차 밑에서 브레이크액이 새고 있었다."},"13375":{"meaning":"좋아하는; 애정 어린","example":"She has been fond of classical music since childhood.","exampleTranslation":"그녀는 어릴 때부터 클래식 음악을 좋아했다."},"13377":{"meaning":"앞쪽; 앞부분","example":"The issue of housing costs came to the fore during the election.","exampleTranslation":"선거 기간 동안 주거비 문제가 전면에 떠올랐다."},"13392":{"meaning":"개척지; 국경지대","example":"Many people still call space the final frontier.","exampleTranslation":"많은 사람들이 여전히 우주를 마지막 개척지라고 부른다."},"13397":{"meaning":"갤런(부피 단위)","example":"A gallon of milk costs about four dollars here.","exampleTranslation":"이곳에서는 우유 1갤런이 약 4달러다."},"13400":{"meaning":"숨을 헐떡이다; 깜짝 놀라 숨을 들이쉬다","example":"I heard the audience gasp when the magician vanished.","exampleTranslation":"마술사가 사라지자 관중이 놀라 숨을 들이켜는 소리가 들렸어요."},"13408":{"meaning":"반짝이다; 희미하게 빛나다","example":"The polished floors gleam in the afternoon sun.","exampleTranslation":"윤이 나는 바닥이 오후 햇살에 반짝여요."},"13412":{"meaning":"장갑","example":"I lost one glove somewhere on the bus this morning.","exampleTranslation":"오늘 아침 버스 어딘가에서 장갑 한 짝을 잃어버렸어요."},"13418":{"meaning":"자갈","example":"They laid gravel on the path to prevent mud after rain.","exampleTranslation":"비가 온 뒤 진흙탕이 되지 않도록 길에 자갈을 깔았어요."},"13423":{"meaning":"격자; 전력망","example":"The streets of the city are laid out in a simple grid.","exampleTranslation":"그 도시의 거리는 단순한 격자 모양으로 나 있어요."},"13425":{"meaning":"암울한; 엄격한","example":"The report painted a grim picture of next year's economy.","exampleTranslation":"그 보고서는 내년 경제를 암울하게 전망했어요."},"13428":{"meaning":"게릴라; 비정규 전투원","example":"Guerilla fighters used surprise attacks to cut the supply lines.","exampleTranslation":"게릴라 대원들은 기습 공격으로 보급선을 끊었어요."},"13432":{"meaning":"망치; 망치로 치다","example":"He used a hammer to drive a nail into the wall.","exampleTranslation":"그는 망치로 벽에 못을 박았어요."},"13434":{"meaning":"잘생긴; 상당한","example":"Everyone noticed the handsome man who had just walked in.","exampleTranslation":"방금 들어온 잘생긴 남자를 모두가 눈여겨봤어요."},"13438":{"meaning":"수확; 수확하다","example":"Farmers celebrate a good harvest at the end of autumn.","exampleTranslation":"농부들은 늦가을에 풍성한 수확을 축하해요."},"13439":{"meaning":"서두름; 급함","example":"In her haste to finish the exam, she made several careless mistakes.","exampleTranslation":"그녀는 시험을 빨리 끝내려고 서두르다가 여러 번 실수를 했어요."},"13442":{"meaning":"(장소에) 출몰하다; (기억 등이) 계속 괴롭히다","example":"Old regrets can haunt a person for many years.","exampleTranslation":"오래된 후회는 수년간 사람을 괴롭힐 수 있어요."},"13449":{"meaning":"동성애의; 동성애자인","example":"The law now protects homosexual couples from discrimination.","exampleTranslation":"법이 이제 동성애 커플을 차별로부터 보호해요."},"13453":{"meaning":"수평의; 가로 방향의","example":"Draw a horizontal line across the middle of the page.","exampleTranslation":"페이지 한가운데에 가로선을 그으세요."},"13454":{"meaning":"호르몬","example":"The doctor explained that a hormone called melatonin controls your sleep cycle.","exampleTranslation":"의사는 멜라토닌이라는 호르몬이 수면 주기를 조절한다고 설명했어요."},"13455":{"meaning":"뿔; 경적","example":"The driver honked the horn to warn the pedestrian.","exampleTranslation":"운전자는 보행자에게 경고하려고 경적을 울렸어요."},"13462":{"meaning":"혼합형; 두 가지를 결합한","example":"Many drivers choose a hybrid vehicle to save on fuel costs.","exampleTranslation":"많은 운전자들이 연료비를 아끼려고 하이브리드 차량을 선택해요."},"13470":{"meaning":"거대한; 막대한","example":"Building the dam required immense effort from thousands of workers.","exampleTranslation":"댐을 건설하는 데 수천 명의 노동자들의 엄청난 노력이 필요했어요."},"13477":{"meaning":"기울다; ~하는 경향이 있다","example":"The path begins to incline sharply near the summit.","exampleTranslation":"길은 정상 근처에서 가파르게 경사지기 시작해요."},"13481":{"meaning":"간접적인; 돌아가는","example":"She took an indirect route to avoid the heavy traffic downtown.","exampleTranslation":"그녀는 도심의 극심한 교통 체증을 피하려고 돌아가는 길을 택했어요."},"13485":{"meaning":"무한한; 끝없는","example":"Some scientists believe the universe may be infinite.","exampleTranslation":"일부 과학자들은 우주가 무한할지도 모른다고 믿어요."},"13503":{"meaning":"간격; 사이","example":"There was a long interval between his first and second novels.","exampleTranslation":"그의 첫 소설과 두 번째 소설 사이에는 긴 공백이 있었다."},"13507":{"meaning":"발동하다; 불러내다","example":"The lawyer decided to invoke an old legal precedent in court.","exampleTranslation":"변호사는 법정에서 오래된 판례를 근거로 들기로 했다."},"13521":{"meaning":"도구 세트; 장비 일식","example":"Always keep a first-aid kit in your car for emergencies.","exampleTranslation":"비상시를 대비해 차에 항상 구급상자를 넣어 두어라."},"13522":{"meaning":"무릎을 꿇다","example":"The knight had to kneel before the king to receive his title.","exampleTranslation":"기사는 작위를 받기 위해 왕 앞에 무릎을 꿇어야 했다."},"13536":{"meaning":"지렛대; 레버","example":"Pull the lever on the right side to open the safety gate.","exampleTranslation":"안전문을 열려면 오른쪽 레버를 당기세요."},"13537":{"meaning":"핥다","example":"The puppy would lick your hand whenever you petted him.","exampleTranslation":"강아지는 쓰다듬을 때마다 손을 핥곤 했다."},"13541":{"meaning":"선형의; 직선의","example":"The story is not linear; it jumps back and forth in time.","exampleTranslation":"그 이야기는 순차적으로 흘러가지 않고 시간을 오가며 전개된다."},"13547":{"meaning":"고리; 루프","example":"He tied the rope in a loop around the post.","exampleTranslation":"그는 밧줄을 고리 모양으로 만들어 기둥에 묶었다."},"13549":{"meaning":"폐; 허파","example":"Smoking for many years can permanently reduce your lung capacity.","exampleTranslation":"오랜 흡연은 폐활량을 영구적으로 줄일 수 있다."},"13553":{"meaning":"포유동물","example":"The blue whale is the largest mammal on Earth.","exampleTranslation":"대왕고래는 지구에서 가장 큰 포유동물이에요."},"13562":{"meaning":"중재하다; 조정하다","example":"A neutral party was asked to mediate between the two companies.","exampleTranslation":"두 회사 사이를 중재해 달라고 중립적인 제3자에게 요청했어요."},"13563":{"meaning":"중세의; 중세 시대의","example":"The old town still has narrow medieval streets and stone walls.","exampleTranslation":"그 구시가지에는 아직도 좁은 중세 골목과 돌담이 남아 있어요."},"13570":{"meaning":"중간의; 한가운데의","example":"The meeting is scheduled for mid-afternoon on Friday.","exampleTranslation":"회의는 금요일 오후 서너 시쯤으로 잡혀 있어요."},"13574":{"meaning":"광물; 미네랄","example":"Calcium is an important mineral for strong bones.","exampleTranslation":"칼슘은 튼튼한 뼈에 중요한 미네랄이에요."},"13590":{"meaning":"~씨 (기혼·미혼 구분 없는 여성 경칭)","example":"Please address the letter to Ms. Johnson at the front desk.","exampleTranslation":"편지 수신인을 안내 데스크의 존슨 씨로 적어 주세요."},"13594":{"meaning":"버섯; 급속히 늘다","example":"This mushroom is poisonous, so please do not eat it.","exampleTranslation":"이 버섯은 독버섯이니 먹지 마세요."},"13601":{"meaning":"그럼에도 불구하고; 그렇지만","example":"The task was difficult; nonetheless, the team finished it on time.","exampleTranslation":"작업은 어려웠어요. 그럼에도 불구하고 팀은 제시간에 끝냈어요."},"13605":{"meaning":"악명 높은; 나쁜 뜻으로 유명한","example":"That intersection is notorious for causing accidents during rush hour.","exampleTranslation":"그 교차로는 출퇴근 시간에 사고가 잦기로 악명 높아요."},"13610":{"meaning":"불분명한; 잘 알려지지 않은","example":"The professor made an obscure reference that only experts understood.","exampleTranslation":"교수는 전문가들만 알아들을 수 있는 생소한 내용을 언급했어요."},"13623":{"meaning":"궤도; 공전하다","example":"The satellite has been in orbit around Earth for ten years.","exampleTranslation":"그 위성은 10년째 지구 궤도를 돌고 있어요."},"13627":{"meaning":"정통적인; 전통적인","example":"The professor takes an orthodox approach to teaching grammar.","exampleTranslation":"그 교수는 문법을 정통적인 방식으로 가르쳐요."},"13635":{"meaning":"감독하다; 관리하다","example":"The project manager will oversee all phases of the construction work.","exampleTranslation":"프로젝트 관리자가 건설 작업의 모든 단계를 감독할 거예요."},"13639":{"meaning":"소포; 꾸러미; 패킷","example":"She tore open the packet of sugar and stirred it into her coffee.","exampleTranslation":"그녀는 설탕 봉지를 뜯어 커피에 넣고 저었어요."},"13654":{"meaning":"침투하다; 꿰뚫다","example":"Sunlight cannot penetrate the ocean below about a thousand meters.","exampleTranslation":"햇빛은 수심 약 천 미터 아래까지는 뚫고 들어가지 못해요."},"13662":{"meaning":"꼬집다; 한 꼬집","example":"My grandmother used to pinch my cheeks every time she saw me.","exampleTranslation":"할머니는 나를 볼 때마다 볼을 꼬집곤 하셨어요."},"13666":{"meaning":"탄원; 변론; 항변","example":"The lawyer entered a plea of not guilty on behalf of her client.","exampleTranslation":"변호사는 의뢰인을 대신해 무죄를 주장했어요."},"13669":{"meaning":"뛰어들다; 급락하다","example":"Stock prices plunge dramatically when investors lose confidence.","exampleTranslation":"투자자들이 신뢰를 잃으면 주가가 급락해요."},"13686":{"meaning":"최고의; 수상","example":"This is the city's premier hotel for business travelers.","exampleTranslation":"이곳은 출장객들에게 이 도시 최고의 호텔이에요."},"13691":{"meaning":"대통령직; 의장직","example":"Her presidency was marked by significant economic reforms.","exampleTranslation":"그녀의 대통령 재임 기간은 굵직한 경제 개혁으로 기억돼요."},"13693":{"meaning":"우세하다; 만연하다","example":"I still believe that justice will prevail in the end.","exampleTranslation":"나는 결국 정의가 이길 거라고 여전히 믿어요."},"13702":{"meaning":"규약; 절차","example":"Doctors must follow the correct protocol in every emergency.","exampleTranslation":"의사들은 모든 응급 상황에서 정해진 절차를 따라야 한다."},"13708":{"meaning":"선반; 걸이대","example":"She placed the wet clothes on the rack to dry.","exampleTranslation":"그녀는 젖은 옷을 건조대에 널어 말렸다."},"13709":{"meaning":"세게 들이받다; 숫양","example":"The thief tried to ram the gate with a stolen truck.","exampleTranslation":"도둑은 훔친 트럭으로 문을 들이받으려 했다."},"13724":{"meaning":"연습하다; 리허설하다","example":"The actors rehearse their lines every day before the opening night.","exampleTranslation":"배우들은 첫 공연 날까지 매일 대사를 연습한다."},"13725":{"meaning":"통치하다; 지배하다","example":"Queen Victoria would reign over Britain for more than sixty years.","exampleTranslation":"빅토리아 여왕은 이후 60년 넘게 영국을 통치하게 된다."},"13745":{"meaning":"회전하다; 순환하다","example":"You should rotate your tires every six months to extend their life.","exampleTranslation":"타이어 수명을 늘리려면 6개월마다 타이어 위치를 바꿔 줘야 한다."},"13753":{"meaning":"야만적인; 잔인한","example":"The documentary showed a savage attack by a pack of wolves.","exampleTranslation":"그 다큐멘터리는 늑대 무리의 잔인한 공격 장면을 보여주었습니다."},"13761":{"meaning":"서둘러 움직이다; 뒤엉키다","example":"Passengers scramble for seats as soon as the train doors open.","exampleTranslation":"열차 문이 열리자마자 승객들이 자리를 차지하려고 우르르 몰려갑니다."},"13763":{"meaning":"긁다; 긁어내다","example":"He used a spatula to scrape the burnt bits off the pan.","exampleTranslation":"그는 뒤집개로 팬에 눌어붙은 탄 부분을 긁어냈습니다."},"13765":{"meaning":"철저한 검사; 면밀한 조사","example":"The new policy came under intense scrutiny from the public.","exampleTranslation":"새 정책은 대중의 날카로운 감시를 받게 되었습니다."},"13766":{"meaning":"세속적인; 종교와 무관한","example":"The country's public schools are entirely secular and teach no religion.","exampleTranslation":"그 나라의 공립학교는 완전히 종교와 무관하며 종교 교육을 하지 않습니다."},"13776":{"meaning":"산산조각 내다; 박살내다","example":"A small rock kicked up by a truck can shatter a windshield.","exampleTranslation":"트럭이 튀긴 작은 돌멩이 하나로도 앞 유리가 산산조각 날 수 있습니다."},"13777":{"meaning":"순전한; 완전한; 가파른","example":"The team succeeded through sheer determination and hard work.","exampleTranslation":"그 팀은 오로지 굳은 의지와 노력만으로 성공했습니다."},"13778":{"meaning":"보안관; 지방 치안관","example":"The sheriff arrived at the scene before anyone else.","exampleTranslation":"보안관이 누구보다 먼저 현장에 도착했습니다."},"13785":{"meaning":"건너뛰다; 빠뜨리다","example":"Students who skip class often miss important information.","exampleTranslation":"수업을 빼먹는 학생들은 중요한 내용을 놓치는 경우가 많습니다."},"13787":{"meaning":"쾅 닫다; 세게 치다","example":"Please don't slam the door when you leave.","exampleTranslation":"나갈 때 문을 쾅 닫지 마세요."},"13812":{"meaning":"향신료; 양념","example":"Cinnamon is my favorite spice to use when baking cookies.","exampleTranslation":"시나몬은 내가 쿠키를 구울 때 제일 즐겨 쓰는 향신료예요."},"13815":{"meaning":"침을 뱉다; 내뱉다","example":"It is rude to spit on the sidewalk.","exampleTranslation":"인도에 침을 뱉는 것은 무례한 행동이에요."},"13828":{"meaning":"깜짝 놀라게 하다","example":"Try not to startle the baby; she just fell asleep.","exampleTranslation":"아기 깜짝 놀라게 하지 마세요. 방금 잠들었어요."},"13831":{"meaning":"조종하다; 이끌다","example":"The captain had to steer the ship carefully through the narrow channel.","exampleTranslation":"선장은 좁은 수로에서 배를 조심스럽게 몰아야 했어요."},"13834":{"meaning":"자극; 동기 부여","example":"The government passed an economic stimulus package to help businesses recover.","exampleTranslation":"정부는 기업 회복을 돕기 위해 경기 부양책을 통과시켰어요."},"13843":{"meaning":"줄무늬","example":"There is a white stripe down the middle of the road.","exampleTranslation":"도로 한가운데에 흰 줄이 그어져 있어요."},"13847":{"meaning":"하위의; 부하","example":"In this company, safety is never subordinate to profit.","exampleTranslation":"이 회사에서는 안전이 결코 이익보다 뒷전이 되지 않아요."},"13856":{"meaning":"급증; 급격히 증가하다","example":"The city saw a surge in tourism after the movie came out.","exampleTranslation":"그 영화가 개봉한 뒤 도시에 관광객이 급증했습니다."},"13860":{"meaning":"빠른; 신속한","example":"The paramedics' swift response saved the man's life.","exampleTranslation":"구급대원들의 신속한 대응이 그 남자의 목숨을 살렸습니다."},"13863":{"meaning":"큰 숟가락; 테이블스푼","example":"Add one tablespoon of olive oil to the pan before cooking.","exampleTranslation":"요리하기 전에 팬에 올리브 오일을 한 큰술 두르세요."},"13870":{"meaning":"터미널; 말기의; 최종의","example":"Passengers on international flights must proceed to Terminal B.","exampleTranslation":"국제선 승객들은 B 터미널로 이동해야 합니다."},"13882":{"meaning":"그대; 당신 (고어)","example":"In Shakespeare's plays, characters often say \\"thou\\" instead of \\"you.\\"","exampleTranslation":"셰익스피어 희곡에서 인물들은 '당신' 대신 '그대'라는 고어를 자주 씁니다."},"13886":{"meaning":"밀다; 찌르다; 추력","example":"She thrust the letter into my hand and walked away.","exampleTranslation":"그녀는 편지를 내 손에 불쑥 쥐여 주고 가 버렸습니다."},"13887":{"meaning":"엄지손가락","example":"He accidentally cut his thumb while chopping onions for dinner.","exampleTranslation":"그는 저녁에 쓸 양파를 썰다가 실수로 엄지손가락을 베었습니다."},"13890":{"meaning":"호랑이","example":"The tiger is one of the most powerful predators in the animal kingdom.","exampleTranslation":"호랑이는 동물 세계에서 가장 강력한 포식자 중 하나입니다."},"13921":{"meaning":"위쪽으로; 상향으로","example":"The hot air balloon drifted slowly upwards into the clear blue sky.","exampleTranslation":"열기구가 맑고 파란 하늘을 향해 천천히 떠올랐어요."},"13939":{"meaning":"처녀의; 사람 손이 닿지 않은","example":"The explorers hiked deep into a virgin forest.","exampleTranslation":"탐험가들은 원시림 깊숙이 걸어 들어갔어요."},"14000":{"meaning":"수도원; 대성당","example":"Tourists visit the ancient abbey to admire its Gothic architecture.","exampleTranslation":"관광객들은 고딕 건축을 감상하려고 그 오래된 수도원을 찾습니다."},"14007":{"meaning":"여파; 후유증; 결과","example":"In the aftermath of the storm, many homes were left without power.","exampleTranslation":"폭풍이 지나간 뒤 많은 가정에 전기가 끊겼습니다."},"14008":{"meaning":"악화시키다; 짜증나게 하다","example":"Eating spicy food can aggravate an existing stomach condition.","exampleTranslation":"매운 음식을 먹으면 앓고 있던 위장 질환이 악화될 수 있습니다."},"14013":{"meaning":"항공로; 기도; 방송국","example":"Asthma causes the airways to narrow, making it hard to breathe.","exampleTranslation":"천식은 기도를 좁혀 숨쉬기 어렵게 만듭니다."},"14029":{"meaning":"일화; 짧은 이야기","example":"The speaker shared a funny anecdote to break the ice with the audience.","exampleTranslation":"연사는 청중의 긴장을 풀어 주려고 재미있는 일화를 들려주었습니다."},"14035":{"meaning":"항체","example":"Each antibody recognizes one specific part of a virus or bacterium.","exampleTranslation":"각 항체는 바이러스나 세균의 특정한 한 부분을 알아봅니다."},"14038":{"meaning":"식욕; 욕구","example":"A long hike in the mountains always gives me a big appetite.","exampleTranslation":"산에서 오래 하이킹을 하고 나면 늘 식욕이 왕성해집니다."},"14048":{"meaning":"중재하다; 조정하다","example":"A neutral party was asked to arbitrate the dispute between the two companies.","exampleTranslation":"두 회사 간의 분쟁을 중재해 달라고 중립적인 제3자에게 요청했습니다."},"14051":{"meaning":"동맥; 주요 도로","example":"The doctor explained that the main artery carries blood away from the heart.","exampleTranslation":"의사는 주요 동맥이 심장에서 나온 혈액을 온몸으로 운반한다고 설명했습니다."},"14063":{"meaning":"경외감; 경이로움","example":"The tourists stood in awe as they gazed at the massive waterfall.","exampleTranslation":"관광객들은 거대한 폭포를 바라보며 경외감에 휩싸인 채 서 있었습니다."},"14066":{"meaning":"보석금; 보석으로 석방하다","example":"The judge set bail at ten thousand dollars for the defendant.","exampleTranslation":"판사는 피고인의 보석금을 1만 달러로 정했습니다."},"14069":{"meaning":"대머리의; 민둥한","example":"My uncle started going bald in his early thirties.","exampleTranslation":"삼촌은 30대 초반에 머리가 벗어지기 시작했어요."},"14071":{"meaning":"침례교 신자; 침례교의","example":"The Baptist congregation gathered every Sunday morning for worship.","exampleTranslation":"침례교 신자들은 예배를 위해 매주 일요일 아침에 모였습니다."},"14074":{"meaning":"한 묶음; 일괄 처리","example":"The baker prepared a fresh batch of cookies for the school event.","exampleTranslation":"제빵사는 학교 행사를 위해 쿠키 한 판을 새로 구웠습니다."},"14090":{"meaning":"한 차례; 발작","example":"He had a bad bout of flu that lasted two weeks.","exampleTranslation":"그는 2주 동안 이어진 심한 독감을 한 차례 앓았어요."},"14092":{"meaning":"보이콧하다; 불매운동을 벌이다; 불매운동","example":"Consumers decided to boycott the brand over its labor practices.","exampleTranslation":"소비자들은 그 브랜드의 노동 관행에 항의해 불매운동을 하기로 결정했어요."},"14093":{"meaning":"대비하다; 각오하다; 버팀대","example":"You should brace yourself for some difficult news.","exampleTranslation":"힘든 소식을 들을 각오를 해야 해요."},"14094":{"meaning":"괄호; 범주","example":"Don't forget the closing bracket at the end of the line.","exampleTranslation":"줄 끝에 닫는 괄호를 빠뜨리지 마세요."},"14096":{"meaning":"여단; 소방대","example":"The army sent a brigade of soldiers to help after the flood.","exampleTranslation":"홍수 후 군은 여단 병력을 보내 복구를 도왔어요."},"14100":{"meaning":"버클; 구부러지다","example":"He fastened the buckle on his backpack before heading out.","exampleTranslation":"그는 나가기 전에 배낭의 버클을 채웠어요."},"14101":{"meaning":"꽃봉오리; 싹","example":"I noticed the first bud on the rose bush this morning.","exampleTranslation":"오늘 아침 장미 덤불에 첫 꽃봉오리가 맺힌 것을 봤어요."},"14105":{"meaning":"침입 절도하다","example":"Thieves tried to burgle the shop after it closed for the night.","exampleTranslation":"도둑들은 밤에 가게가 문을 닫은 뒤 침입해 물건을 훔치려 했어요."},"14108":{"meaning":"끝부분; 엉덩이","example":"He rested the butt of his rifle on the ground.","exampleTranslation":"그는 소총 개머리판을 땅에 대고 세웠어요."},"14114":{"meaning":"사로잡힌; 갇힌; 포로","example":"The captive animal paced restlessly inside its small enclosure.","exampleTranslation":"사로잡힌 동물은 좁은 우리 안에서 불안하게 왔다 갔다 했어요."},"14137":{"meaning":"낮게 웃다; 빙그레 웃음","example":"She couldn't help but chuckle when she read the funny message.","exampleTranslation":"그녀는 재미있는 메시지를 읽고 낮게 웃음을 터뜨리지 않을 수 없었어요."},"14140":{"meaning":"죔쇠로 고정하다; 꽉 죄다","example":"Clamp the two pieces of wood together until the glue dries.","exampleTranslation":"접착제가 마를 때까지 두 나무 조각을 꽉 고정하세요."},"14144":{"meaning":"발톱; 발톱으로 할퀴다","example":"The cat caught its claw on my wool sweater.","exampleTranslation":"고양이 발톱이 내 털 스웨터에 걸렸어요."},"14173":{"meaning":"원뿔; 솔방울","example":"A traffic cone was placed in the middle of the road to warn drivers.","exampleTranslation":"운전자에게 경고하기 위해 도로 한가운데에 원뿔 표지가 놓였어요."},"14176":{"meaning":"혼잡하게 하다; 막히게 하다","example":"Road construction will congest downtown traffic for weeks.","exampleTranslation":"도로 공사로 몇 주 동안 시내 교통이 혼잡해질 거예요."},"14181":{"meaning":"소집하다; 모이다","example":"The board will convene next Monday to review the annual budget.","exampleTranslation":"이사회는 다음 주 월요일에 모여 연간 예산을 검토할 거예요."},"14193":{"meaning":"경련; 쥐","example":"He stopped running because he suddenly got a cramp in his leg.","exampleTranslation":"그는 갑자기 다리에 쥐가 나서 달리기를 멈췄어요."},"14210":{"meaning":"원기둥; 실린더","example":"Each cylinder in the engine has a piston that moves up and down.","exampleTranslation":"엔진의 각 실린더에는 위아래로 움직이는 피스톤이 하나씩 있어요."},"14211":{"meaning":"유제품; 낙농의","example":"I try to avoid dairy because it upsets my stomach.","exampleTranslation":"나는 유제품을 먹으면 배탈이 나서 피하려고 해요."},"14214":{"meaning":"돌진하다; 다트(게임)","example":"A small fish will dart away when it senses danger.","exampleTranslation":"작은 물고기는 위험을 감지하면 쏜살같이 달아나요."},"14216":{"meaning":"눈을 부시게 하다; 황홀하게 하다","example":"The fireworks display never fails to dazzle the crowd.","exampleTranslation":"불꽃놀이는 언제나 관중을 황홀하게 해요."},"14218":{"meaning":"고인이 된; 사망한","example":"The lawyer read the will of her deceased husband to the family.","exampleTranslation":"변호사가 가족들에게 그녀의 세상을 떠난 남편의 유언장을 읽어 주었어요."},"14228":{"meaning":"비난하다; 공개적으로 규탄하다","example":"World leaders were quick to denounce the attack on the embassy.","exampleTranslation":"세계 지도자들은 대사관 공격을 즉각 규탄했어요."},"14229":{"meaning":"치과 의사","example":"My dentist recommended brushing my teeth after every meal.","exampleTranslation":"치과 의사 선생님이 매 식사 후 이를 닦으라고 권했어요."},"14232":{"meaning":"하강; 내리막; 혈통","example":"The descent from the mountain was steeper than the climb up.","exampleTranslation":"산에서 내려오는 길은 올라갈 때보다 더 가팔랐어요."},"14239":{"meaning":"확산시키다; 퍼뜨리다; 분산된","example":"A small fan helped diffuse the scent of lavender throughout the room.","exampleTranslation":"작은 선풍기 덕분에 라벤더 향이 방 전체로 퍼졌습니다."},"14248":{"meaning":"망신; 불명예; 창피를 주다","example":"He resigned in disgrace after the scandal became public.","exampleTranslation":"그는 스캔들이 알려진 뒤 불명예스럽게 사임했습니다."},"14251":{"meaning":"당혹감; 낙담시키다","example":"To everyone's dismay, the event was canceled at the last minute.","exampleTranslation":"모두가 당혹스럽게도 행사가 마지막 순간에 취소되었습니다."},"14259":{"meaning":"우회; 전환; 기분 전환","example":"Reading mystery novels is a pleasant diversion from my busy job.","exampleTranslation":"추리 소설 읽기는 바쁜 일상에서 즐거운 기분 전환이 돼요."},"14262":{"meaning":"피하다; 빠져나가다","example":"He managed to dodge the flying ball just in time.","exampleTranslation":"그는 날아오는 공을 아슬아슬하게 피했습니다."},"14273":{"meaning":"의심스러운; 미심쩍은","example":"She was dubious about the salesman's overly generous offer.","exampleTranslation":"그녀는 판매원의 지나치게 후한 제안을 미심쩍어했습니다."},"14274":{"meaning":"어리석은; 바보 같은; 말을 못 하는","example":"It was a dumb mistake, and I felt embarrassed about it.","exampleTranslation":"어리석은 실수라서 창피했어요."},"14304":{"meaning":"뒤따르다; 결과로 일어나다","example":"Whenever the referee made a close call, a loud argument would ensue.","exampleTranslation":"심판이 아슬아슬한 판정을 내릴 때마다 큰 언쟁이 뒤따르곤 했다."},"14319":{"meaning":"광활한 공간; 넓은 지역","example":"The hikers stood in awe before the vast expanse of the desert stretching ahead.","exampleTranslation":"등산객들은 앞에 끝없이 펼쳐진 광활한 사막을 보며 경외감에 사로잡혔다."},"14323":{"meaning":"외부; 외관","example":"Workers repainted the exterior of the old building to improve its appearance.","exampleTranslation":"작업자들은 보기 좋게 하려고 낡은 건물의 외벽을 다시 칠했다."},"14325":{"meaning":"멋진; 엄청난","example":"We had a fabulous time at the beach last weekend.","exampleTranslation":"우리는 지난 주말 해변에서 정말 멋진 시간을 보냈다."},"14329":{"meaning":"고정하다; 잠그다","example":"Always fasten your seatbelt before the car starts moving.","exampleTranslation":"차가 출발하기 전에 항상 안전벨트를 매세요."},"14333":{"meaning":"막다; 스스로 해나가다","example":"Young adults must learn to fend for themselves when they leave home.","exampleTranslation":"젊은 성인들은 독립할 때 스스로 해나가는 법을 배워야 한다."},"14337":{"meaning":"고정 장치; 비품; 정기 행사","example":"The plumber came to replace a broken fixture in the bathroom.","exampleTranslation":"배관공이 욕실의 고장 난 설비를 교체하러 왔습니다."},"14341":{"meaning":"털썩 쓰러지다; 실패하다; 실패작","example":"After the long hike, he was so tired that he couldn't wait to flop onto the couch.","exampleTranslation":"긴 하이킹 후 그는 너무 지쳐서 얼른 소파에 털썩 눕고 싶었습니다."},"14343":{"meaning":"펄럭이다; 두근거리다; 설렘","example":"The flags began to flutter in the strong breeze outside the stadium.","exampleTranslation":"경기장 밖에서 강한 바람에 깃발들이 펄럭이기 시작했습니다."},"14353":{"meaning":"연기; 가스; 화가 나다","example":"He began to fume when he saw the scratch on his new car.","exampleTranslation":"그는 새 차에 긁힌 자국을 보고 화가 치밀기 시작했습니다."},"14363":{"meaning":"유약; 유리를 끼우다; 눈이 흐려지다","example":"The baker brushed a sweet glaze over the freshly baked pastries.","exampleTranslation":"제빵사는 갓 구운 페이스트리에 달콤한 글레이즈를 발랐습니다."},"14368":{"meaning":"그램","example":"One gram of sugar contains about four calories.","exampleTranslation":"설탕 1그램에는 약 4칼로리가 들어 있습니다."},"14369":{"meaning":"포도","example":"She popped a grape into her mouth and smiled.","exampleTranslation":"그녀는 포도 한 알을 입에 쏙 넣고 미소 지었습니다."},"14374":{"meaning":"손질하다; 신랑; 마부","example":"She likes to groom her dog herself instead of paying a pet salon.","exampleTranslation":"그녀는 애견 미용실에 돈을 쓰는 대신 직접 개를 손질하는 것을 좋아합니다."},"14379":{"meaning":"잇몸; 껌","example":"Chewing gum is not allowed in the classroom.","exampleTranslation":"교실에서는 껌을 씹으면 안 됩니다."},"14382":{"meaning":"우박; 환영하다; 부르다","example":"The hail was so heavy that it left dents in several parked cars.","exampleTranslation":"우박이 너무 거세서 주차된 여러 차량이 움푹 패었습니다."},"14392":{"meaning":"반구; 반구체","example":"Australia is located in the Southern Hemisphere.","exampleTranslation":"호주는 남반구에 있습니다."},"14404":{"meaning":"겁에 질린; 몹시 충격받은","example":"She was horrified to find that her wallet had been stolen.","exampleTranslation":"그녀는 지갑이 도둑맞은 것을 알고 극도로 충격을 받았습니다."},"14410":{"meaning":"세게 던지다; 내던지다","example":"He was so angry that he wanted to hurl his phone against the wall.","exampleTranslation":"그는 너무 화가 나서 휴대폰을 벽에 내던지고 싶었습니다."},"14412":{"meaning":"신분증; 이드(정신분석의 원초아)","example":"You will need to show a valid ID to enter the venue.","exampleTranslation":"행사장에 입장하려면 유효한 신분증을 제시해야 합니다."},"14420":{"meaning":"부수적인; 우연한","example":"There may be some incidental expenses, such as parking and meals.","exampleTranslation":"주차비나 식비 같은 부수적인 비용이 생길 수 있습니다."},"14425":{"meaning":"(고통·피해 등을) 가하다; 끼치다","example":"Storms like this can inflict serious damage on coastal towns.","exampleTranslation":"이런 폭풍은 해안 마을에 심각한 피해를 입힐 수 있습니다."},"14431":{"meaning":"(크리켓·야구의) 이닝","example":"In cricket, each team usually bats for one or two innings.","exampleTranslation":"크리켓에서 각 팀은 보통 한두 이닝 동안 타격을 합니다."},"14446":{"meaning":"질투하는; 시기하는","example":"He felt jealous when his friend got a promotion before him.","exampleTranslation":"그는 친구가 자신보다 먼저 승진하자 질투를 느꼈습니다."},"14448":{"meaning":"보석; 귀중품","example":"The necklace had a single blue jewel that once belonged to her grandmother.","exampleTranslation":"그 목걸이에는 할머니의 것이었던 파란 보석 하나가 달려 있었습니다."},"14454":{"meaning":"쓰레기; 잡동사니","example":"The garage was full of junk that nobody had touched in years.","exampleTranslation":"차고는 몇 년 동안 아무도 손대지 않은 잡동사니로 가득했습니다."},"14455":{"meaning":"신장; 콩팥","example":"She donated a kidney to her brother last year.","exampleTranslation":"그녀는 작년에 남동생에게 신장 하나를 기증했습니다."},"14459":{"meaning":"뒤처지다; 지연","example":"My internet connection tends to lag during busy hours.","exampleTranslation":"제 인터넷은 사람이 몰리는 시간대에 자주 느려집니다."},"14460":{"meaning":"슬퍼하다; 애도하다","example":"Many residents began to lament the loss of the old community center.","exampleTranslation":"많은 주민들이 오래된 주민 센터가 사라진 것을 슬퍼하기 시작했습니다."},"14471":{"meaning":"치명적인; 치사의","example":"The scientist warned that the chemical could be lethal in large doses.","exampleTranslation":"과학자는 그 화학물질을 다량 섭취하면 치명적일 수 있다고 경고했습니다."},"14479":{"meaning":"소송을 제기하다; 법정에서 다투다","example":"The company decided to litigate the contract dispute rather than settle.","exampleTranslation":"그 회사는 계약 분쟁을 합의하지 않고 소송으로 다투기로 결정했습니다."},"14499":{"meaning":"원수; 연방 보안관; 행사 진행 책임자; 정리하다","example":"The marshal directed traffic near the parade route throughout the event.","exampleTranslation":"행사 진행 책임자는 행사 내내 퍼레이드 경로 근처에서 교통을 정리했습니다."},"14500":{"meaning":"순교자; 희생자","example":"He died a martyr for the cause of equal rights.","exampleTranslation":"그는 평등권을 위한 대의에 목숨을 바친 순교자였습니다."},"14504":{"meaning":"어머니의; 모성의","example":"She had a warm, maternal way with children that made them feel safe.","exampleTranslation":"그녀는 아이들을 따뜻하게 보살피는 모성적인 면이 있어 아이들이 안심했습니다."},"14515":{"meaning":"전령; 메신저; 심부름꾼","example":"A messenger arrived at the office with an urgent package for the director.","exampleTranslation":"배달원이 이사님께 전할 긴급 소포를 들고 사무실에 도착했습니다."},"14518":{"meaning":"한가운데; 중간","example":"We were in the midst of dinner when the power suddenly went out.","exampleTranslation":"한창 저녁을 먹고 있을 때 갑자기 전기가 나갔습니다."},"14529":{"meaning":"신음하다; 불평하다; 신음 소리","example":"He began to moan about his knee pain after the long walk.","exampleTranslation":"긴 산책 후 그는 무릎이 아프다고 투덜대기 시작했습니다."},"14537":{"meaning":"모르타르(시멘트); 절구","example":"The bricklayer mixed mortar to hold the bricks together.","exampleTranslation":"벽돌공은 벽돌을 붙이기 위해 모르타르를 섞었습니다."},"14539":{"meaning":"모기","example":"She got a mosquito bite on her arm while sitting outside.","exampleTranslation":"그녀는 바깥에 앉아 있다가 팔을 모기에 물렸습니다."},"14551":{"meaning":"신비로운; 신비주의자","example":"The old temple is known for its mystic traditions and quiet rituals.","exampleTranslation":"그 오래된 사원은 신비로운 전통과 고요한 의식으로 알려져 있습니다."},"14560":{"meaning":"명목상의; 아주 적은","example":"There is a nominal fee to enter the community garden on weekends.","exampleTranslation":"주말에 커뮤니티 정원에 들어가려면 아주 적은 입장료를 내야 합니다."},"14568":{"meaning":"영양소; 영양분","example":"Iron is an important nutrient that helps carry oxygen in the blood.","exampleTranslation":"철분은 혈액 속 산소 운반을 돕는 중요한 영양소입니다."},"14571":{"meaning":"시작; 발병","example":"Doctors say treatment should begin at the onset of symptoms.","exampleTranslation":"의사들은 증상이 시작될 때 바로 치료를 시작해야 한다고 말합니다."},"14581":{"meaning":"공공연한; 명백한","example":"The report found no overt discrimination, but some hidden bias remained.","exampleTranslation":"보고서는 공공연한 차별은 없었지만 숨은 편견은 일부 남아 있다고 밝혔습니다."},"14585":{"meaning":"협정; 조약; 약속","example":"The two friends made a pact to support each other no matter what happens.","exampleTranslation":"두 친구는 무슨 일이 있어도 서로 돕기로 약속했습니다."},"14586":{"meaning":"노; 패들; 노를 젓다","example":"She grabbed a paddle and steered the canoe across the lake.","exampleTranslation":"그녀는 노를 잡고 카누를 몰아 호수를 건넜습니다."},"14605":{"meaning":"완두콩","example":"The princess could feel a single pea under all her mattresses.","exampleTranslation":"공주는 매트리스를 여러 겹 깔아도 그 아래의 완두콩 한 알을 느낄 수 있었습니다."},"14614":{"meaning":"박해하다; 괴롭히다","example":"Many governments have tried to persecute people for their religious beliefs.","exampleTranslation":"많은 정부가 종교적 신념을 이유로 사람들을 박해하려 했습니다."},"14616":{"meaning":"해충; 골칫거리","example":"A pest has been eating the leaves of her tomato plants in the garden.","exampleTranslation":"해충이 정원에 있는 그녀의 토마토 잎을 갉아먹고 있습니다."},"14618":{"meaning":"석유","example":"Many countries depend on petroleum as their main source of energy.","exampleTranslation":"많은 나라가 주요 에너지원으로 석유에 의존하고 있습니다."},"14628":{"meaning":"파인트(용량 단위); 맥주 한 잔","example":"He ordered a pint of beer and watched the game at the bar.","exampleTranslation":"그는 바에서 맥주 한 파인트를 주문하고 경기를 봤습니다."},"14629":{"meaning":"파이프라인; 수송관; 진행 중인 계획","example":"The company has several new products in the pipeline for next year.","exampleTranslation":"그 회사는 내년 출시를 목표로 여러 신제품을 준비하고 있습니다."},"14630":{"meaning":"해적; 저작권 침해자","example":"My son dressed up as a pirate for the school costume party.","exampleTranslation":"내 아들은 학교 코스튬 파티에서 해적으로 변장했습니다."},"14636":{"meaning":"석고; 반창고; 회반죽을 바르다","example":"The workers covered the cracked wall with a fresh layer of plaster.","exampleTranslation":"인부들은 금 간 벽에 회반죽을 새로 발랐습니다."},"14653":{"meaning":"수습 기간; 집행유예","example":"New employees are on probation for the first three months.","exampleTranslation":"신입 직원은 처음 3개월 동안 수습 기간을 거칩니다."},"14654":{"meaning":"행렬; 행진","example":"A long procession of students walked across the stage to receive their diplomas.","exampleTranslation":"학생들이 긴 행렬을 이루어 졸업장을 받으러 무대를 가로질러 걸어갔습니다."},"14664":{"meaning":"훅 불다; 한 모금; 부풀리다","example":"He took a puff of his cigar and leaned back in his chair.","exampleTranslation":"그는 시가를 한 모금 빨고 의자에 등을 기댔습니다."},"14667":{"meaning":"피라미드; 삼각뿔","example":"Visiting the Great Pyramid in Egypt was an unforgettable experience.","exampleTranslation":"이집트의 대피라미드를 방문한 것은 잊을 수 없는 경험이었습니다."},"14696":{"meaning":"고삐; 통제하다","example":"Keep a tight rein on your spending if you want to save money.","exampleTranslation":"돈을 모으고 싶다면 지출을 엄격하게 통제하세요."},"14707":{"meaning":"필수적인; 필요 조건","example":"She lacked the requisite experience for the senior position.","exampleTranslation":"그녀는 그 고위직에 필요한 경력이 부족했습니다."},"14713":{"meaning":"재회; 동창회","example":"The family planned a reunion at their grandmother's house this summer.","exampleTranslation":"가족은 이번 여름 할머니 댁에서 가족 모임을 하기로 했습니다."},"14719":{"meaning":"장비; 조작하다","example":"The workers set up a rig to drill for oil in the open sea.","exampleTranslation":"작업자들은 먼바다에서 석유를 시추하기 위해 장비를 설치했습니다."},"14727":{"meaning":"돌아다니다; 방랑하다","example":"As a young man, he loved to rove across different countries.","exampleTranslation":"젊은 시절 그는 여러 나라를 떠돌아다니는 것을 좋아했습니다."},"14746":{"meaning":"분리하다; 격리하다","example":"In the past, some schools would segregate students by race.","exampleTranslation":"과거에 일부 학교는 인종에 따라 학생들을 분리했습니다."},"14759":{"meaning":"관목; 덤불","example":"She planted a flowering shrub next to the front steps.","exampleTranslation":"그녀는 현관 계단 옆에 꽃이 피는 관목을 심었습니다."},"14762":{"meaning":"셔틀; 왕복 운행하다","example":"The hotel provides a free shuttle between the airport and the hotel.","exampleTranslation":"호텔은 공항과 호텔 사이에 무료 셔틀을 운행합니다."},"14765":{"meaning":"의미하다; 나타내다","example":"A red light on the device is used to signify a low battery.","exampleTranslation":"기기의 빨간 불빛은 배터리 부족을 나타내는 데 쓰입니다."},"14769":{"meaning":"단수의; 유일한; 특이한","example":"She has a singular talent for making people feel at ease.","exampleTranslation":"그녀는 사람들을 편안하게 해 주는 보기 드문 재능이 있습니다."},"14773":{"meaning":"느슨한; 부진한; 여유","example":"Business has been slack this month, so the store has been closing early.","exampleTranslation":"이번 달은 장사가 부진해서 가게가 일찍 문을 닫고 있습니다."},"14774":{"meaning":"베다; 대폭 삭감하다; 빗금","example":"The store decided to slash prices by fifty percent during the sale.","exampleTranslation":"그 가게는 세일 기간에 가격을 50% 내리기로 했습니다."},"14776":{"meaning":"도살하다; 학살; 대패시키다","example":"Farmers used to slaughter a pig for the winter festival.","exampleTranslation":"농부들은 겨울 축제를 위해 돼지를 잡곤 했습니다."},"14780":{"meaning":"철썩 때리다; 탁 치다; 맛","example":"Be careful not to smack your head on the low ceiling.","exampleTranslation":"낮은 천장에 머리를 부딪히지 않도록 조심하세요."},"14788":{"meaning":"사회주의","example":"In class, the professor explained how socialism differs from capitalism.","exampleTranslation":"교수님은 수업에서 사회주의가 자본주의와 어떻게 다른지 설명했습니다."},"14799":{"meaning":"낳다; 생기게 하다","example":"The viral video went on to spawn dozens of similar online trends.","exampleTranslation":"그 바이럴 영상은 수십 개의 유사한 온라인 트렌드를 만들어냈습니다."},"14811":{"meaning":"쪼그려 앉다; 스쿼트","example":"Squat down slowly and keep your back straight.","exampleTranslation":"등을 곧게 편 채 천천히 쪼그려 앉으세요."},"14818":{"meaning":"무균의; 불임의; 메마른","example":"The nurse put on sterile gloves before treating the patient's wound.","exampleTranslation":"간호사는 환자의 상처를 치료하기 전에 무균 장갑을 꼈습니다."},"14840":{"meaning":"늪; 압도하다","example":"The hikers carefully avoided the swamp on the edge of the trail.","exampleTranslation":"등산객들은 등산로 가장자리에 있는 늪을 조심스럽게 피했습니다."},"14869":{"meaning":"치료의; 치유적인","example":"Many people find gardening to be therapeutic after a stressful week at work.","exampleTranslation":"많은 사람들은 일로 스트레스받은 한 주를 보낸 뒤 정원 가꾸기가 마음을 치유해 준다고 느낍니다."},"14870":{"meaning":"그 이후에; 그 후로","example":"She graduated in June and shortly thereafter moved to a new city for work.","exampleTranslation":"그녀는 6월에 졸업하고 얼마 후 일 때문에 새 도시로 이사했습니다."},"14906":{"meaning":"궤양","example":"The doctor said the stomach ulcer was caused by a bacterial infection.","exampleTranslation":"의사는 위궤양이 세균 감염 때문에 생겼다고 말했습니다."},"14913":{"meaning":"지지하다; 유지하다; 옹호하다","example":"It is the court's duty to uphold the rights guaranteed by the law.","exampleTranslation":"법이 보장하는 권리를 수호하는 것은 법원의 의무입니다."},"14942":{"meaning":"볼트(전압 단위)","example":"My car has a twelve-volt battery under the hood.","exampleTranslation":"내 차의 보닛 아래에는 12볼트 배터리가 있습니다."},"14944":{"meaning":"맹세; 서약하다","example":"He made a vow to visit his grandmother every Sunday.","exampleTranslation":"그는 매주 일요일 할머니를 찾아뵙겠다고 맹세했습니다."},"14949":{"meaning":"경계하는; 조심하는","example":"Be wary of strangers who offer to help you for no reason.","exampleTranslation":"아무 이유 없이 도와주겠다는 낯선 사람을 조심하세요."},"14954":{"meaning":"밀; 소맥","example":"This bread is made from whole wheat flour, so it is healthier.","exampleTranslation":"이 빵은 통밀가루로 만들어서 더 건강에 좋습니다."},"14963":{"meaning":"마법사; 달인","example":"The old wizard in the story could turn any object into gold.","exampleTranslation":"이야기 속 늙은 마법사는 어떤 물건이든 금으로 바꿀 수 있었습니다."},"15014":{"meaning":"적; 상대방","example":"In the final round, she faced her old adversary from the national championship.","exampleTranslation":"결승에서 그녀는 전국 선수권 대회 때의 오랜 맞수와 맞붙었습니다."},"15026":{"meaning":"아몬드","example":"She dipped each almond in melted chocolate.","exampleTranslation":"그녀는 아몬드를 하나씩 녹인 초콜릿에 담갔습니다."},"15028":{"meaning":"알프스 산맥","example":"They spent their vacation skiing in the Alps last winter.","exampleTranslation":"그들은 지난 겨울 알프스에서 스키를 타며 휴가를 보냈습니다."},"15055":{"meaning":"주의 깊은; 배려하는","example":"The students were attentive throughout the lecture and took careful notes.","exampleTranslation":"학생들은 강의 내내 주의를 기울이며 꼼꼼히 필기했습니다."},"15059":{"meaning":"아우라; 분위기; 기운","example":"The old cathedral had a mysterious aura that made visitors fall silent.","exampleTranslation":"오래된 대성당에는 방문객들을 저절로 숙연하게 만드는 신비로운 분위기가 있었습니다."},"15064":{"meaning":"자기(연인 호칭, 구어); 아기(문어)","example":"Hey babe, do you want to order pizza tonight?","exampleTranslation":"자기야, 오늘 밤에 피자 시킬까?"},"15065":{"meaning":"독신남; 학사 학위","example":"He remained a bachelor well into his forties before finally getting married.","exampleTranslation":"그는 40대가 한참 지나도록 독신으로 지내다가 마침내 결혼했습니다."},"15075":{"meaning":"세게 치다; 파티","example":"Be careful not to bash your knee against the corner of the table.","exampleTranslation":"테이블 모서리에 무릎을 세게 찧지 않도록 조심하세요."},"15076":{"meaning":"손짓하여 부르다; 유혹하다","example":"From across the crowded room, she waved to beckon her friend over.","exampleTranslation":"그녀는 붐비는 방 건너편에서 손을 흔들어 친구에게 이리 오라고 손짓했습니다."},"15089":{"meaning":"싱거운; 밋밋한; 단조로운","example":"The soup was too bland, so she added some salt and pepper.","exampleTranslation":"국이 너무 싱거워서 그녀는 소금과 후추를 조금 넣었습니다."},"15091":{"meaning":"표백제; 탈색하다","example":"She used bleach to remove the stubborn stain from the white shirt.","exampleTranslation":"그녀는 흰 셔츠에 묻은 잘 지워지지 않는 얼룩을 없애려고 표백제를 썼습니다."},"15098":{"meaning":"단발로 자른; 위아래로 흔들린","example":"She arrived at the party with freshly bobbed hair that everyone admired.","exampleTranslation":"그녀는 갓 단발로 자른 머리를 하고 파티에 나타났고 모두가 감탄했습니다."},"15112":{"meaning":"억센 털; 반발하다","example":"Each bristle on the old toothbrush was bent out of shape.","exampleTranslation":"낡은 칫솔의 털이 하나하나 모양이 휘어져 있었습니다."},"15114":{"meaning":"브라우니(초콜릿 케이크)","example":"She served a warm brownie with a scoop of vanilla ice cream.","exampleTranslation":"그녀는 따뜻한 브라우니에 바닐라 아이스크림 한 스쿱을 곁들여 냈습니다."},"15123":{"meaning":"부표; 기운을 북돋우다","example":"A bright orange buoy marked the end of the swimming course.","exampleTranslation":"밝은 주황색 부표가 수영 코스의 끝을 표시하고 있었습니다."},"15129":{"meaning":"낙타","example":"I rode a camel across the sand dunes during our desert tour.","exampleTranslation":"나는 사막 투어 중에 낙타를 타고 모래 언덕을 넘었습니다."},"15135":{"meaning":"캐러밴; 이동식 주택; 여행 대열","example":"A caravan of trucks and cars crossed the desert together.","exampleTranslation":"트럭과 승용차 행렬이 함께 사막을 건넜습니다."},"15155":{"meaning":"밤; 밤나무","example":"She peeled a roasted chestnut and handed it to her little brother.","exampleTranslation":"그녀는 군밤 하나를 까서 남동생에게 건넸습니다."},"15161":{"meaning":"연대기; 시간 순서","example":"The detective carefully pieced together a chronology of the victim's last day.","exampleTranslation":"형사는 피해자의 마지막 하루를 시간 순서대로 꼼꼼히 재구성했습니다."},"15164":{"meaning":"쪼개다; 갈라지다; 달라붙다","example":"He used an axe to cleave the large log in half.","exampleTranslation":"그는 도끼로 큰 통나무를 반으로 쪼갰습니다."},"15171":{"meaning":"덩어리; 무리","example":"A clump of trees at the edge of the field provided welcome shade.","exampleTranslation":"들판 가장자리에 모여 선 나무들이 반가운 그늘을 드리워 주었습니다."},"15175":{"meaning":"조종석","example":"The pilot invited the child to take a quick look at the cockpit.","exampleTranslation":"조종사는 아이에게 조종석을 잠깐 구경해 보라고 했습니다."},"15176":{"meaning":"코코아; 카카오","example":"She made a warm cup of cocoa to drink on a cold winter evening.","exampleTranslation":"그녀는 추운 겨울 저녁에 마시려고 따뜻한 코코아 한 잔을 만들었습니다."},"15178":{"meaning":"동기 집단; 동료 무리","example":"Our cohort from the training program meets once a year for a reunion.","exampleTranslation":"연수 프로그램 동기들은 1년에 한 번 동창회로 모입니다."},"15179":{"meaning":"충돌하다; 부딪히다","example":"Shopping carts often collide in the narrow aisles of this grocery store.","exampleTranslation":"이 식료품점의 좁은 통로에서는 쇼핑 카트끼리 자주 부딪힙니다."},"15193":{"meaning":"정복; 획득","example":"The conquest of Mount Everest in 1953 made headlines around the world.","exampleTranslation":"1953년 에베레스트 정복은 전 세계의 헤드라인을 장식했습니다."},"15195":{"meaning":"공모하다; 음모를 꾸미다","example":"Rain, wind, and ants all seemed to conspire to ruin their picnic.","exampleTranslation":"비와 바람, 개미까지 모두 그들의 소풍을 망치려고 작정한 것 같았습니다."},"15208":{"meaning":"우주의; 광대한","example":"The scientist talked about cosmic rays and their effect on Earth's atmosphere.","exampleTranslation":"그 과학자는 우주 방사선과 그것이 지구 대기에 미치는 영향에 대해 이야기했습니다."},"15222":{"meaning":"구기다; 쭈그러들다","example":"She watched him crumple the rejection letter and toss it in the trash.","exampleTranslation":"그녀는 그가 불합격 통지서를 구겨서 쓰레기통에 던지는 것을 지켜봤어."},"15223":{"meaning":"소맷부리; 수갑","example":"His shirt cuff was stained with ink after hours of writing at his desk.","exampleTranslation":"책상에서 몇 시간 동안 글을 쓰고 나니 그의 셔츠 소맷부리가 잉크로 얼룩졌어."},"15224":{"meaning":"요리; 요리법","example":"I love trying the local cuisine whenever I travel abroad.","exampleTranslation":"나는 해외여행을 갈 때마다 현지 요리를 맛보는 걸 좋아해."},"15225":{"meaning":"누적되는; 점점 증가하는","example":"The cumulative effect of losing sleep night after night can be serious.","exampleTranslation":"밤마다 잠이 부족한 상태가 누적되면 그 영향은 심각할 수 있어."},"15239":{"meaning":"숙의했다; 심사숙고했다(deliberate의 과거·과거분사)","example":"The jury deliberated for three days before finally reaching a verdict.","exampleTranslation":"배심원단은 사흘 동안 숙의한 끝에 마침내 평결을 내렸어."},"15249":{"meaning":"추방하다; 강제 출국시키다","example":"The authorities decided to deport the man who had entered the country illegally.","exampleTranslation":"당국은 불법으로 입국한 그 남자를 추방하기로 결정했어."},"15253":{"meaning":"경멸하다; 몹시 싫어하다","example":"She grew to despise dishonesty after being lied to many times.","exampleTranslation":"그녀는 여러 번 거짓말을 당한 뒤로 부정직함을 경멸하게 됐어."},"15265":{"meaning":"제자; 신봉자","example":"As a young disciple of the philosopher, he followed his teacher everywhere.","exampleTranslation":"그 철학자의 젊은 제자로서 그는 스승을 어디든 따라다녔습니다."},"15271":{"meaning":"경멸; 무시","example":"She responded to the rude comment with obvious disdain.","exampleTranslation":"그녀는 그 무례한 말에 노골적인 경멸로 응수했습니다."},"15273":{"meaning":"환멸을 느끼게 하다; 환상을 깨다","example":"A few months of long hours and low pay were enough to disillusion him.","exampleTranslation":"몇 달간 이어진 장시간 근무와 박봉만으로도 그가 환멸을 느끼기에는 충분했습니다."},"15281":{"meaning":"증류하다; 핵심을 추출하다","example":"They distill water by boiling it and collecting the steam.","exampleTranslation":"그들은 물을 끓여 나오는 증기를 모아 물을 증류합니다."},"15297":{"meaning":"웅변적인; 표현이 유창한","example":"The mayor gave an eloquent speech that moved many in the audience to tears.","exampleTranslation":"시장은 청중 상당수를 눈물짓게 한 유려한 연설을 했습니다."},"15300":{"meaning":"저명한; 탁월한","example":"An eminent professor from Oxford was invited to give the keynote speech.","exampleTranslation":"옥스퍼드의 저명한 교수가 기조연설자로 초청되었습니다."},"15304":{"meaning":"매혹하다; 마법을 걸다","example":"Her gentle voice never fails to enchant the audience.","exampleTranslation":"그녀의 부드러운 목소리는 언제나 관객을 매혹합니다."},"15305":{"meaning":"부호화하다; 인코딩하다; 암호로 바꾸다","example":"The program will encode the video so it plays on any device.","exampleTranslation":"그 프로그램은 어떤 기기에서도 재생되도록 영상을 인코딩합니다."},"15320":{"meaning":"유로(유럽 통화 단위)","example":"In Paris, I paid for my coffee with a two-euro coin.","exampleTranslation":"파리에서 나는 2유로짜리 동전으로 커피값을 냈습니다."},"15341":{"meaning":"벌채된; 쓰러뜨려진","example":"Loggers stacked the felled trees beside the mountain road.","exampleTranslation":"벌목꾼들이 베어 낸 나무들을 산길 옆에 쌓아 두었습니다."},"15347":{"meaning":"유한한; 한계가 있는","example":"We only have a finite amount of time to finish the project before the deadline.","exampleTranslation":"마감일 전에 프로젝트를 끝낼 수 있는 시간은 한정되어 있습니다."},"15353":{"meaning":"추파를 던지다; 시시덕거리다; (생각을) 잠깐 해 보다","example":"He would always flirt with the barista when ordering his morning coffee.","exampleTranslation":"그는 아침 커피를 주문할 때마다 바리스타에게 추파를 던지곤 했습니다."},"15356":{"meaning":"유창한; 능숙한","example":"After two years in Spain, she became fluent in Spanish.","exampleTranslation":"스페인에서 2년을 지낸 뒤 그녀는 스페인어를 유창하게 하게 되었습니다."},"15382":{"meaning":"입을 벌리고 바라보다; 멍하니 쳐다보다","example":"Tourists stopped to gape at the giant sculpture in the middle of the square.","exampleTranslation":"관광객들은 걸음을 멈추고 광장 한가운데의 거대한 조각상을 입을 벌린 채 바라봤습니다."},"15394":{"meaning":"반짝이다; 번득임","example":"Coins at the bottom of the fountain glint in the afternoon sun.","exampleTranslation":"분수 바닥의 동전들이 오후 햇살에 반짝입니다."},"15420":{"meaning":"헥타르(면적 단위)","example":"Each hectare of the farm produces about ten tons of rice a year.","exampleTranslation":"그 농장은 1헥타르당 매년 약 10톤의 쌀을 생산합니다."},"15440":{"meaning":"색조; 색깔","example":"The sunset gave the sky a warm orange hue.","exampleTranslation":"석양이 하늘을 따뜻한 주황빛으로 물들였습니다."},"15450":{"meaning":"히스테리적인; 극도로 웃긴","example":"She found the comedian so hysterical that she could not stop laughing.","exampleTranslation":"그녀는 그 코미디언이 너무 웃겨서 웃음을 멈출 수 없었습니다."},"15451":{"meaning":"같은 책에(앞서 인용한 것과 동일한 출처)","example":"The footnote simply reads ibid to refer to the same source cited above.","exampleTranslation":"그 각주에는 위에 인용한 것과 같은 출처라는 뜻의 약어만 적혀 있습니다."},"15456":{"meaning":"방해하다; 지연시키다","example":"Heavy traffic can impede deliveries and cause packages to arrive late.","exampleTranslation":"심한 교통 체증은 배송을 지연시켜 택배가 늦게 도착하게 만들 수 있습니다."},"15461":{"meaning":"의도하지 않은; 무심코 한","example":"The inadvertent error in the report caused a brief delay in the project.","exampleTranslation":"보고서의 의도치 않은 오류 때문에 프로젝트가 잠시 지연되었습니다."},"15484":{"meaning":"교환하다; 교차로","example":"You can interchange these two parts because they are exactly the same size.","exampleTranslation":"이 두 부품은 크기가 똑같아서 서로 바꿔 끼울 수 있습니다."},"15487":{"meaning":"참을 수 없는; 견딜 수 없는","example":"After an hour parked in the sun, the heat inside the car was intolerable.","exampleTranslation":"햇볕 아래 한 시간 주차해 두었더니 차 안의 열기가 견딜 수 없을 정도였습니다."},"15514":{"meaning":"손가락 관절; 너클","example":"He cut his knuckle on a sharp edge while fixing his bike.","exampleTranslation":"그는 자전거를 고치다가 날카로운 모서리에 손가락 관절을 베였습니다."},"15523":{"meaning":"상추; 양상추","example":"She added fresh lettuce to the sandwich to make it crunchier.","exampleTranslation":"그녀는 샌드위치를 더 아삭하게 만들려고 신선한 상추를 넣었습니다."},"15525":{"meaning":"백합","example":"She placed a single white lily on her grandmother's grave.","exampleTranslation":"그녀는 할머니 산소에 흰 백합 한 송이를 놓았습니다."},"15533":{"meaning":"보라!; 이봐(주의를 끌 때 쓰는 감탄사)","example":"Lo and behold, she walked in just as we were talking about her.","exampleTranslation":"놀랍게도 우리가 그녀 얘기를 하던 바로 그때 그녀가 들어왔습니다."},"15535":{"meaning":"몹시 싫어하다; 혐오하다","example":"I loathe having to commute two hours every day.","exampleTranslation":"나는 매일 두 시간씩 통근해야 하는 게 정말 싫습니다."},"15547":{"meaning":"갑자기 기울다; 비틀거리다","example":"I felt the bus lurch to one side as it hit a pothole.","exampleTranslation":"버스가 움푹 팬 곳을 지나면서 한쪽으로 휘청하는 게 느껴졌습니다."},"15548":{"meaning":"무성한; 풍성한; 풍요로운","example":"The hiking trail wound through a lush green forest for several miles.","exampleTranslation":"등산로는 무성한 초록 숲을 지나 몇 마일이나 구불구불 이어졌습니다."},"15556":{"meaning":"손상시키다; 흠집 내다","example":"A single spelling error can mar an otherwise perfect cover letter.","exampleTranslation":"철자 오류 하나가 그것만 빼면 완벽한 자기소개서를 망칠 수 있습니다."},"15573":{"meaning":"형이상학 체계; 형이상학(드문 단수형)","example":"Kant hoped to build a metaphysic that could stand as a true science.","exampleTranslation":"칸트는 진정한 학문으로 설 수 있는 형이상학 체계를 세우고자 했습니다."},"15576":{"meaning":"극소의; 매우 작은","example":"The investor focuses on micro and small businesses in rural areas.","exampleTranslation":"그 투자자는 농촌 지역의 초소형 및 소규모 기업에 집중합니다."},"15577":{"meaning":"백만장자; 큰 부자","example":"He became a millionaire after selling his tech startup.","exampleTranslation":"그는 자신의 기술 스타트업을 매각한 후 백만장자가 되었습니다."},"15580":{"meaning":"소형의; 아주 작은","example":"She ordered a mini cheesecake because she was already quite full.","exampleTranslation":"그녀는 이미 배가 꽤 불러서 미니 치즈케이크를 주문했습니다."},"15610":{"meaning":"콧구멍","example":"He had a small cut inside his left nostril that bled a little.","exampleTranslation":"그는 왼쪽 콧구멍 안쪽에 작은 상처가 나서 피가 조금 났습니다."},"15625":{"meaning":"신탁; 예언자","example":"In ancient times, people traveled far to consult the oracle for guidance.","exampleTranslation":"고대에는 사람들이 신탁을 구하러 먼 길을 떠났습니다."},"15629":{"meaning":"오스카 (영화 시상식 트로피); 아카데미상","example":"She burst into tears the moment she received the Oscar on stage.","exampleTranslation":"그녀는 무대에서 아카데미상 트로피를 받는 순간 눈물을 터뜨렸습니다."},"15630":{"meaning":"진동하다; 왔다 갔다 하다","example":"This fan can oscillate from side to side to cool the entire room.","exampleTranslation":"이 선풍기는 좌우로 회전하며 방 전체를 시원하게 할 수 있습니다."},"15643":{"meaning":"굴","example":"He slurped down a fresh oyster with a squeeze of lemon.","exampleTranslation":"그는 레몬즙을 살짝 뿌린 신선한 굴 하나를 후루룩 삼켰습니다."},"15658":{"meaning":"병리학; 병리","example":"The lab report came back from the pathology department with detailed findings.","exampleTranslation":"병리과에서 상세한 소견이 담긴 검사 보고서가 나왔습니다."},"15660":{"meaning":"후원; 단골 거래","example":"The small bookstore survived thanks to the loyal patronage of local readers.","exampleTranslation":"그 작은 서점은 지역 독자들의 꾸준한 단골 이용 덕분에 살아남았습니다."},"15666":{"meaning":"조약돌; 자갈","example":"She skipped a pebble across the surface of the calm lake.","exampleTranslation":"그녀는 잔잔한 호수에서 조약돌로 물수제비를 떴습니다."},"15681":{"meaning":"피클; 곤경","example":"She bit into the crunchy dill pickle that came with her sandwich.","exampleTranslation":"그녀는 샌드위치에 곁들여 나온 아삭한 딜 피클을 한 입 베어 물었습니다."},"15691":{"meaning":"통통한; 살찐","example":"The baker chose plump, juicy berries to decorate the top of the cake.","exampleTranslation":"제빵사는 케이크 윗면을 장식하려고 통통하고 즙이 많은 베리를 골랐습니다."},"15699":{"meaning":"사전의; ~이전의 (접두사)","example":"Please complete the pre-work before attending the training session.","exampleTranslation":"교육에 참석하기 전에 사전 과제를 꼭 완료하세요."},"15709":{"meaning":"선전; 프로파간다","example":"The government used propaganda posters to encourage citizens to support the war effort.","exampleTranslation":"정부는 시민들이 전쟁 수행을 지지하도록 독려하기 위해 선전 포스터를 활용했습니다."},"15734":{"meaning":"열광하다; 극찬하다","example":"People in the office rave about the new coffee machine in the break room.","exampleTranslation":"사무실 사람들은 휴게실에 새로 들어온 커피 머신을 극찬합니다."},"15738":{"meaning":"물러나다; 후퇴하다","example":"The floodwaters began to recede after three days of dry weather.","exampleTranslation":"사흘 동안 비가 오지 않자 불어난 물이 빠지기 시작했습니다."},"15746":{"meaning":"반사 작용; 반사적 행동","example":"Blinking when something flies toward your eyes is a natural reflex.","exampleTranslation":"무언가가 눈 쪽으로 날아올 때 눈을 깜빡이는 것은 자연스러운 반사 작용입니다."},"15763":{"meaning":"공명; 울림; 반향","example":"The singer's voice had a rich resonance that filled the whole hall.","exampleTranslation":"그 가수의 목소리에는 홀 전체를 채우는 풍부한 울림이 있었습니다."},"15764":{"meaning":"호흡기; 방독면","example":"Workers must wear a respirator when handling hazardous chemicals in the lab.","exampleTranslation":"실험실에서 위험한 화학물질을 다룰 때 작업자는 호흡 보호 마스크를 착용해야 합니다."},"15770":{"meaning":"운율; 운이 맞다","example":"The children learned a simple rhyme to remember the days of the week.","exampleTranslation":"아이들은 요일을 외우려고 간단한 운율 노래를 배웠습니다."},"15773":{"meaning":"악당; 무법자; 불량의","example":"In the old movie, a charming rogue steals the heart of a rich man's daughter.","exampleTranslation":"그 옛날 영화에서 매력적인 건달이 부잣집 딸의 마음을 사로잡습니다."},"15792":{"meaning":"진홍색; 새빨간","example":"She wore a scarlet scarf that stood out in the gray crowd.","exampleTranslation":"그녀는 회색빛 군중 속에서 눈에 띄는 진홍색 스카프를 하고 있었습니다."},"15795":{"meaning":"경멸; 비웃음; 경멸하다","example":"She met his excuse with open scorn and walked away.","exampleTranslation":"그녀는 그의 변명에 노골적인 경멸을 드러내고는 자리를 떴습니다."},"15811":{"meaning":"결점; 단점","example":"His only real shortcoming as a manager is that he hates delegating work.","exampleTranslation":"관리자로서 그의 유일한 단점은 일을 남에게 맡기기 싫어한다는 점입니다."},"15814":{"meaning":"비명을 지르다; 날카로운 비명","example":"I could hear the kids shriek with laughter on the roller coaster.","exampleTranslation":"롤러코스터를 탄 아이들이 깔깔대며 비명을 지르는 소리가 들렸습니다."},"15815":{"meaning":"수의; 가리다; 덮다","example":"A thick shroud of fog covered the valley in the early morning.","exampleTranslation":"이른 아침, 짙은 안개가 장막처럼 계곡을 뒤덮었습니다."},"15828":{"meaning":"슬리퍼; 실내화","example":"She could only find one slipper, so she searched under the bed.","exampleTranslation":"그녀는 슬리퍼 한 짝밖에 찾지 못해서 침대 밑을 뒤졌습니다."},"15829":{"meaning":"미끄러운; 파악하기 어려운","example":"Be careful, the kitchen floor is slippery after mopping.","exampleTranslation":"조심하세요, 걸레질을 해서 부엌 바닥이 미끄러워요."},"15834":{"meaning":"교활한; 능청스러운","example":"The sly fox in the story always found a way to outsmart the other animals.","exampleTranslation":"이야기 속 교활한 여우는 늘 다른 동물들을 속여 넘길 방법을 찾아냈습니다."},"15839":{"meaning":"소다; 탄산음료","example":"He ordered a burger and a large soda to go with it.","exampleTranslation":"그는 버거와 함께 큰 사이즈 탄산음료를 주문했습니다."},"15857":{"meaning":"규정하다; 명시하다","example":"The new contract should stipulate that all payments be made within thirty days.","exampleTranslation":"새 계약서에는 모든 대금을 30일 이내에 지급해야 한다고 명시해야 합니다."},"15872":{"meaning":"굴복하다; (병 등으로) 쓰러지다","example":"On a diet, it is easy to succumb to the temptation of late-night snacks.","exampleTranslation":"다이어트 중에는 야식의 유혹에 굴복하기 쉽습니다."},"15874":{"meaning":"능가하다; 뛰어넘다","example":"She studied hard and managed to surpass everyone else in the class on the final exam.","exampleTranslation":"그녀는 열심히 공부해서 기말고사에서 반 친구들 모두를 뛰어넘었습니다."},"15878":{"meaning":"음절","example":"In the word 'banana,' the stress falls on the second syllable.","exampleTranslation":"'banana'라는 단어에서는 강세가 두 번째 음절에 있습니다."},"15897":{"meaning":"층; 단계; 등급","example":"The basic tier of the subscription is free, but it shows ads.","exampleTranslation":"그 구독의 기본 등급은 무료지만 광고가 나옵니다."},"15909":{"meaning":"호민관; 연단; 대변인","example":"In ancient Rome, a tribune protected the rights of ordinary citizens.","exampleTranslation":"고대 로마에서 호민관은 평민의 권리를 보호했습니다."},"15911":{"meaning":"트롤리; 손수레; 전차","example":"We rode the old trolley down the hill to the waterfront.","exampleTranslation":"우리는 오래된 전차를 타고 언덕을 내려가 해안가로 갔습니다."},"15912":{"meaning":"이기다; 능가하다; 으뜸패","example":"In this card game, hearts trump every other suit.","exampleTranslation":"이 카드 게임에서는 하트가 다른 모든 무늬를 이깁니다."},"15919":{"meaning":"황혼; 어스름","example":"They sat on the porch and watched the sky at twilight.","exampleTranslation":"그들은 해 질 녘 현관에 앉아 하늘을 바라봤습니다."},"15922":{"meaning":"타자기로 치다; 타이프하다","example":"Before computers, secretaries had to typewrite every letter without a single mistake.","exampleTranslation":"컴퓨터가 나오기 전에는 비서들이 모든 편지를 실수 하나 없이 타자기로 쳐야 했습니다."},"15951":{"meaning":"호두","example":"She added a handful of walnut pieces to the salad for extra crunch.","exampleTranslation":"그녀는 식감을 더하려고 샐러드에 호두 조각을 한 줌 넣었습니다."},"15967":{"meaning":"슬픔; 불행; 고통","example":"She listened patiently as he poured out his tale of woe.","exampleTranslation":"그녀는 그가 자신의 딱한 사연을 털어놓는 동안 참을성 있게 들어 주었습니다."},"16013":{"meaning":"10억","example":"A billion is written as a one followed by nine zeros.","exampleTranslation":"10억은 1 뒤에 0을 아홉 개 붙여 써요."},"16025":{"meaning":"모든; ~마다","example":"She calls her mother every morning on her way to work.","exampleTranslation":"그녀는 매일 아침 출근길에 어머니께 전화해요."},"16026":{"meaning":"다섯; 5","example":"Most people have five fingers on each hand.","exampleTranslation":"대부분의 사람은 한 손에 손가락이 다섯 개 있어요."},"16041":{"meaning":"그녀 자신","example":"She made the birthday cake all by herself.","exampleTranslation":"그녀는 생일 케이크를 혼자서 다 만들었어요."},"16044":{"meaning":"백; 100","example":"My great-grandmother just turned a hundred years old.","exampleTranslation":"증조할머니께서 막 백 세가 되셨어요."},"16064":{"meaning":"백만","example":"One million is written as a one followed by six zeros.","exampleTranslation":"백만은 1 뒤에 0을 여섯 개 붙여 써요."},"16076":{"meaning":"뒤덮다; 완전히 덮다","example":"Heavy snow is expected to blanket the entire town by morning.","exampleTranslation":"폭설이 아침까지 온 마을을 뒤덮을 것으로 예상돼요."},"16093":{"meaning":"결코 ~않다","example":"I will never forget the day we first met.","exampleTranslation":"우리가 처음 만난 날을 절대 잊지 못할 거예요."},"16100":{"meaning":"청소년의; 사춘기의","example":"Adolescent children often need more sleep than adults.","exampleTranslation":"청소년기 아이들은 보통 어른보다 잠이 더 많이 필요해요."},"16156":{"meaning":"환하게 웃다; 빛을 비추다","example":"She could not help but beam with pride at her daughter's graduation.","exampleTranslation":"그녀는 딸의 졸업식에서 자랑스러움에 환하게 웃지 않을 수 없었습니다."},"16162":{"meaning":"12월","example":"The whole family gets together every December for the holidays.","exampleTranslation":"온 가족이 매년 12월에 연휴를 보내려고 모입니다."},"16177":{"meaning":"주교","example":"The bishop gave a moving sermon at the cathedral.","exampleTranslation":"그 주교는 대성당에서 감동적인 설교를 했습니다."},"16180":{"meaning":"사무국; 서랍장","example":"She keeps her winter sweaters in the old wooden bureau.","exampleTranslation":"그녀는 겨울 스웨터를 낡은 나무 서랍장에 보관합니다."},"16191":{"meaning":"문명화하다; 교화하다","example":"Some writers argued that art and music help civilize a society.","exampleTranslation":"일부 작가들은 예술과 음악이 사회를 교화하는 데 도움이 된다고 주장했습니다."},"16196":{"meaning":"홱 수그리다; 머리를 숙이다","example":"Everyone had to duck to get through the low doorway.","exampleTranslation":"낮은 출입구를 지나가려면 모두 몸을 숙여야 했습니다."},"16198":{"meaning":"손위의; 연장자의","example":"Her elder brother helps her with homework every evening.","exampleTranslation":"그녀의 오빠는 매일 저녁 그녀의 숙제를 도와줍니다."},"16200":{"meaning":"기절하다; 실신하다","example":"She felt like she might faint after standing in the sun so long.","exampleTranslation":"그녀는 햇볕 아래 너무 오래 서 있어서 기절할 것 같았습니다."},"16205":{"meaning":"그들 자신; 스스로","example":"The kids learned to solve the puzzle by themselves.","exampleTranslation":"아이들은 스스로 퍼즐 푸는 법을 익혔습니다."},"16259":{"meaning":"검사하다; 점검하다","example":"Workers inspect every vehicle carefully before it leaves the factory.","exampleTranslation":"작업자들은 모든 차량이 공장을 나가기 전에 꼼꼼히 검사합니다."},"16282":{"meaning":"민주당원; 민주주의자","example":"She has been a loyal Democrat since her college days.","exampleTranslation":"그녀는 대학 시절부터 충실한 민주당원이었습니다."},"16283":{"meaning":"몰두하는; 의도된","example":"He was intent on finishing the marathon no matter what.","exampleTranslation":"그는 무슨 일이 있어도 마라톤을 완주하겠다고 단단히 마음먹고 있었습니다."},"16306":{"meaning":"원반; 디스크","example":"He slipped a disc while lifting a heavy box at work.","exampleTranslation":"그는 직장에서 무거운 상자를 들다가 허리 디스크가 생겼습니다."},"16334":{"meaning":"훈련시키다; 반복 연습시키다","example":"The coach will drill the players on basic passing skills at every practice.","exampleTranslation":"코치는 훈련 때마다 선수들에게 기본 패스 기술을 반복 훈련시킬 것입니다."},"16336":{"meaning":"열망하는; 간절히 바라는","example":"The new intern seemed eager to learn everything about the job.","exampleTranslation":"새 인턴은 그 일에 대해 모든 것을 몹시 배우고 싶어 하는 것 같았습니다."},"16362":{"meaning":"제분하다; 갈다","example":"Long ago, farmers had to mill wheat into flour by hand.","exampleTranslation":"옛날에는 농부들이 손으로 밀을 갈아 밀가루를 만들어야 했습니다."},"16384":{"meaning":"만지작거리다; 장난치다","example":"Don't monkey around with the settings, or you might break something.","exampleTranslation":"설정을 함부로 만지작거리지 마세요, 뭔가 고장 날 수도 있어요."},"16395":{"meaning":"10월","example":"The leaves usually start changing color in October.","exampleTranslation":"나뭇잎은 보통 10월에 물들기 시작합니다."},"16399":{"meaning":"꽉 잡다","example":"He tends to grip the steering wheel tightly when he drives in heavy rain.","exampleTranslation":"그는 폭우 속에서 운전할 때 운전대를 꽉 움켜쥐는 경향이 있습니다."},"16421":{"meaning":"상속받다; 물려받다","example":"She will inherit the house when her grandmother passes away.","exampleTranslation":"할머니가 돌아가시면 그녀가 그 집을 물려받을 것입니다."},"16427":{"meaning":"냄비; 팬","example":"She stirred the sauce in a large pan on the stove.","exampleTranslation":"그녀는 스토브 위 큰 팬에서 소스를 저었습니다."},"16454":{"meaning":"문자 그대로의","example":"The literal meaning of the idiom is very different from what people actually mean.","exampleTranslation":"그 관용구의 문자 그대로의 의미는 사람들이 실제로 뜻하는 것과 매우 다릅니다."},"16474":{"meaning":"정비공; 기술자","example":"The mechanic fixed my car's engine in one afternoon.","exampleTranslation":"그 정비공은 오후 한나절 만에 제 차 엔진을 고쳤습니다."},"16488":{"meaning":"고개를 끄덕이다","example":"Just nod if you agree with the plan, and we will get started.","exampleTranslation":"계획에 동의하면 고개만 끄덕여 주세요, 그럼 시작하겠습니다."},"16498":{"meaning":"주먹으로 치다","example":"At the gym, he likes to punch the heavy bag as hard as he can.","exampleTranslation":"그는 체육관에서 샌드백을 있는 힘껏 치는 것을 좋아합니다."},"16527":{"meaning":"금지하다","example":"The new rules prohibit smoking anywhere inside the building.","exampleTranslation":"새 규칙은 건물 안 어디에서든 흡연을 금지합니다."},"16562":{"meaning":"(어떤 상태가 되게) 만들다; 제공하다","example":"The heavy snow could render the roads impassable by morning.","exampleTranslation":"폭설 때문에 아침이면 도로가 통행 불가능해질 수도 있습니다."},"16594":{"meaning":"상원","example":"The bill must still pass through the Senate before it becomes law.","exampleTranslation":"그 법안은 법이 되기 전에 아직 상원을 통과해야 합니다."},"16611":{"meaning":"딸기","example":"The children ate each strawberry as soon as they picked it.","exampleTranslation":"아이들은 딸기를 따자마자 하나씩 먹어 버렸습니다."},"16634":{"meaning":"동정; 공감","example":"Neighbors sent flowers to show their sympathy after the accident.","exampleTranslation":"이웃들은 사고 이후 위로의 마음을 전하기 위해 꽃을 보냈습니다."},"16655":{"meaning":"잡초","example":"A stubborn weed kept growing between the bricks.","exampleTranslation":"끈질긴 잡초 하나가 벽돌 사이에서 계속 자라났습니다."},"17012":{"meaning":"끓어오르게 하다; 팔팔 끓이다","example":"Pour the broth into the pot and bring to a boil, then add the noodles.","exampleTranslation":"육수를 냄비에 붓고 팔팔 끓인 다음 면을 넣어."},"17110":{"meaning":"일이 산더미인","example":"We've been totally snowed under with orders since the sale started.","exampleTranslation":"세일이 시작된 뒤로 주문이 완전 산더미예요."},"17111":{"meaning":"내가 맡은 일; 처리할 일","example":"I have too much on my plate to take on another project right now.","exampleTranslation":"지금은 맡은 일이 너무 많아서 프로젝트를 하나 더 맡을 수 없어요."},"17137":{"meaning":"월급 인상을 요청하다","example":"I plan to ask for a raise at my review next week, and I'm nervous.","exampleTranslation":"다음 주 평가 때 월급을 올려 달라고 할 건데 긴장돼요."},"17265":{"meaning":"바가지 관광지; 관광객 상대 함정","example":"That restaurant is a tourist trap with terrible food and high prices.","exampleTranslation":"그 식당은 음식은 형편없고 값만 비싼, 관광객 상대 바가지 집이에요."},"17275":{"meaning":"단체 사진","example":"Everyone, gather around for a group photo by the waterfall!","exampleTranslation":"여러분, 폭포 옆에서 단체 사진 찍게 모여 주세요!"},"17308":{"meaning":"소원을 빌다","example":"Close your eyes and make a wish before you release the lantern.","exampleTranslation":"등을 날려 보내기 전에 눈을 감고 소원을 빌어요."},"17321":{"meaning":"어른을 공경하다","example":"My mother always said, \\"Respect your elders and never interrupt them.\\"","exampleTranslation":"엄마는 늘 \\"어른을 공경하고 절대 말을 끊지 마라\\"라고 하셨어요."},"17323":{"meaning":"가만히 서 있다","example":"When the anthem plays in the park, people stand still until it ends.","exampleTranslation":"공원에서 국가가 나오면 사람들은 끝날 때까지 가만히 서 있어요."},"17347":{"meaning":"전통 의상","example":"Each dancer wore a traditional costume with gold jewelry.","exampleTranslation":"무용수들은 저마다 금장신구를 단 전통 의상을 입었어요."},"17355":{"meaning":"예산 초과인","example":"We went over budget on the trip because of the hotel.","exampleTranslation":"호텔 때문에 여행 예산을 초과했어요."},"17364":{"meaning":"저축 목표","example":"My savings goal this year is to save enough for a scooter.","exampleTranslation":"올해 제 저축 목표는 스쿠터 살 돈을 모으는 거예요."},"17453":{"meaning":"너무 짠","example":"This fried rice is too salty for me, so I need some water.","exampleTranslation":"이 볶음밥은 저한테 너무 짜서 물이 필요해요."},"17481":{"meaning":"너무 단","example":"This iced tea is too sweet. Could I get one with less sugar?","exampleTranslation":"이 아이스티가 너무 달아요. 설탕 덜 넣은 걸로 하나 주실래요?"},"17515":{"meaning":"거래하다; 사업하다","example":"We've been happy to do business with them for years.","exampleTranslation":"우리는 몇 년째 그들과 만족스럽게 거래해 오고 있어."},"17526":{"meaning":"약을 먹다","example":"Try not to take medicine on an empty stomach.","exampleTranslation":"빈속에 약을 먹지 않도록 해."},"17566":{"meaning":"농담하다","example":"Every night at dinner, my dad tries to tell a joke.","exampleTranslation":"아빠는 매일 저녁 식사 때마다 농담을 하려고 하세요."},"17571":{"meaning":"기회를 놓치다","example":"Never miss a chance to practice your English with locals.","exampleTranslation":"현지인과 영어 연습할 기회를 절대 놓치지 마세요."},"17637":{"meaning":"배터리 부족","example":"My phone is running on low battery, so I might not answer later.","exampleTranslation":"휴대폰 배터리가 얼마 없어서 이따가 전화를 못 받을 수도 있어요."},"17691":{"meaning":"참을성 있게 기다리다","example":"We had to patiently wait in line for an hour to get into the museum.","exampleTranslation":"박물관에 들어가려고 한 시간 동안 줄을 서서 참을성 있게 기다려야 했어요."},"17726":{"meaning":"다시 생각해 보니","example":"I'll have the chicken. Actually, on second thought, I'll get the fish.","exampleTranslation":"치킨으로 할게요. 아, 다시 생각해 보니 생선으로 할게요."},"17741":{"meaning":"몸매가 망가진; 체력이 떨어진","example":"I'm so out of shape that I can't even run for five minutes.","exampleTranslation":"체력이 너무 떨어져서 5분도 못 뛰겠어요."},"17785":{"meaning":"놀리다; 농담하다","example":"Don't believe him; he just likes to pull your leg.","exampleTranslation":"그 사람 말 믿지 마, 그냥 사람 놀리는 걸 좋아해."},"17794":{"meaning":"호랑이도 제 말 하면 온다","example":"Speak of the devil, here comes Tom.","exampleTranslation":"호랑이도 제 말 하면 온다더니, 톰이 오네."},"17950":{"meaning":"있는 그대로 말하다","example":"I like my teacher because she isn't afraid to tell it like it is.","exampleTranslation":"선생님은 있는 그대로 말하는 걸 두려워하지 않으셔서 저는 좋아요."},"17981":{"meaning":"불행 중 다행; 한 줄기 희망","example":"The flight was canceled, but there was a silver lining: a free hotel room.","exampleTranslation":"항공편이 취소됐지만 무료 호텔 방을 받은 건 불행 중 다행이었어요."},"17984":{"meaning":"불확실한 상태에 있다; 위태롭다","example":"Hundreds of jobs could hang in the balance if the factory closes.","exampleTranslation":"그 공장이 문을 닫으면 수백 개의 일자리가 위태로워질 수 있어요."},"18002":{"meaning":"앱을 업데이트하다","example":"If the map keeps freezing, you should update the app first.","exampleTranslation":"지도가 계속 멈추면 먼저 앱을 업데이트하세요."},"18207":{"meaning":"바가지를 쓴; 요금을 더 청구당한","example":"I think I was overcharged. I only had two coffees, but the bill says three.","exampleTranslation":"요금을 더 낸 것 같아요. 커피는 두 잔만 마셨는데 계산서에는 세 잔으로 적혀 있어요."},"18213":{"meaning":"제대로 작동하지 않는","example":"The washing machine in my apartment is not working properly again.","exampleTranslation":"우리 집 세탁기가 또 제대로 작동하지 않아요."},"18215":{"meaning":"누락된 물건; 빠진 품목","example":"There's a missing item in my delivery. Could you please check my order?","exampleTranslation":"배달에 빠진 품목이 있어요. 주문 내역 좀 확인해 주시겠어요?"},"18230":{"meaning":"허위 광고; 과장 광고","example":"The pool looked huge in the photos, but it's tiny. That's false advertising.","exampleTranslation":"사진에서는 수영장이 엄청 커 보였는데 실제로는 아주 작아요. 이건 허위 광고예요."},"18251":{"meaning":"칭찬하다; 칭찬의 말을 건네다","example":"He always tries to pay a compliment to the chef after a good meal.","exampleTranslation":"그는 맛있게 먹고 나면 늘 셰프에게 칭찬의 말을 건네려고 해요."},"18293":{"meaning":"격려의 말","example":"Even a single word of encouragement can make a big difference.","exampleTranslation":"격려의 말 한마디도 큰 차이를 만들 수 있어요."},"18310":{"meaning":"개봉일 밤; 첫 공연 날","example":"We got tickets for opening night, and the theater is sure to be packed.","exampleTranslation":"개봉 첫날 밤 표를 구했는데, 극장이 꽉 찰 게 분명해요."},"18315":{"meaning":"귀에 쏙 들어오는 곡; 중독성 있는 멜로디","example":"It's such a catchy tune that I've been humming it all day.","exampleTranslation":"귀에 쏙 들어오는 곡이라 하루 종일 흥얼거리고 있어요."},"18432":{"meaning":"반려견 놀이터; 애견 공원","example":"I met most of my neighbors while taking my dog to the dog park.","exampleTranslation":"강아지를 데리고 애견 공원에 다니면서 이웃들 대부분을 알게 됐어요."},"18465":{"meaning":"나쁜 습관을 고치다","example":"It takes time to break a bad habit, so be patient with yourself.","exampleTranslation":"나쁜 습관을 고치는 데는 시간이 걸리니 스스로에게 너그러워지세요."},"18525":{"meaning":"망치다; 엉망으로 만들다","example":"I'm so nervous that I'm afraid I'll mess up my speech.","exampleTranslation":"너무 긴장돼서 발표를 망칠까 봐 걱정이에요."},"18580":{"meaning":"겁먹고 포기하다","example":"I was terrified at the top of the bungee tower, but I didn't chicken out.","exampleTranslation":"번지 점프대 꼭대기에서 너무 무서웠지만 겁먹고 포기하진 않았어요."},"18598":{"meaning":"(말을) 끝까지 들어 주다","example":"A good manager will hear out both sides before making a decision.","exampleTranslation":"좋은 관리자는 결정을 내리기 전에 양쪽 이야기를 끝까지 들어 봐요."},"18657":{"meaning":"(기계·가게가) 꺼지다; 문을 닫다","example":"Don't forget to shut down your computer before you leave the office.","exampleTranslation":"퇴근하기 전에 컴퓨터 끄는 거 잊지 마세요."},"18693":{"meaning":"돌려주다; (기억을) 떠올리게 하다","example":"Old songs like this always bring back memories of college.","exampleTranslation":"이런 옛날 노래는 늘 대학 시절 추억을 떠올리게 해요."},"18750":{"meaning":"(자원·시장을) 활용하다; 이용하다","example":"Online classes let you tap into the knowledge of teachers worldwide.","exampleTranslation":"온라인 수업 덕분에 전 세계 선생님들의 지식을 활용할 수 있어요."},"18850":{"meaning":"네 생각 알려 줘(의견 요청)","example":"Here's my plan for the trip. Let me know what you think.","exampleTranslation":"이게 내 여행 계획이야. 네 생각 알려 줘."},"18881":{"meaning":"~할 기분이 아니야; ~하기 싫어(내키지 않음)","example":"I don't feel like going out tonight. Let's just order in.","exampleTranslation":"오늘 밤엔 나갈 기분이 아니야. 그냥 배달시키자."},"18890":{"meaning":"~이 부러워; 질투 나(부러움)","example":"I'm jealous of your long vacation. I only get five days.","exampleTranslation":"네 긴 휴가가 부럽다. 난 5일밖에 없어."},"18897":{"meaning":"~해서 다행이야(다행)","example":"It's a good thing that we left early, because the traffic is terrible.","exampleTranslation":"교통이 엉망이라 일찍 출발해서 다행이야."},"18898":{"meaning":"~은 이제 질렸어; 더는 못 참아(한계)","example":"I've had enough of this noise. I'm moving out.","exampleTranslation":"이 소음은 더는 못 참겠어. 이사 갈 거야."},"18918":{"meaning":"진작 ~했어야지; ~할 때가 됐다","example":"It's about time we cleaned out the garage.","exampleTranslation":"이제 차고를 정리할 때가 됐어요."},"19057":{"meaning":"반칙","example":"That was clearly a foul, but the referee didn't call it.","exampleTranslation":"저건 명백한 반칙인데 심판이 안 불었어요."},"19082":{"meaning":"완봉; 무실점 경기","example":"Our goalie has recorded a shutout in each of the last three games.","exampleTranslation":"우리 골키퍼는 최근 세 경기 연속 무실점을 기록했어요."},"19093":{"meaning":"앞서 나가다; 리드를 잡다","example":"It took them a while, but they finally managed to take the lead.","exampleTranslation":"시간이 좀 걸렸지만 그들은 결국 리드를 잡았어요."},"19103":{"meaning":"촛불을 불어 끄다","example":"Make a wish and blow out the candles before the wax drips on the cake!","exampleTranslation":"촛농이 케이크에 떨어지기 전에 얼른 소원 빌고 촛불 불어 꺼!"},"19130":{"meaning":"초대받지 않은 파티에 끼어들다","example":"A few college kids tried to crash a party in our building last night.","exampleTranslation":"어젯밤 대학생 몇 명이 우리 건물에서 열린 파티에 초대도 없이 끼어들려고 했다."},"19238":{"meaning":"논의 대상인; 제시된","example":"Is working remotely still on the table, or has that changed?","exampleTranslation":"원격 근무도 아직 논의 대상인가요, 아니면 달라졌나요?"},"19263":{"meaning":"글머리 기호 항목","example":"Keep each bullet point short, ideally under ten words.","exampleTranslation":"글머리 항목은 하나하나 짧게, 되도록 열 단어 이내로 쓰세요."},"19299":{"meaning":"초청 연사","example":"Our guest speaker today flew in all the way from Singapore.","exampleTranslation":"오늘의 초청 연사는 멀리 싱가포르에서 비행기를 타고 오셨어요."},"19302":{"meaning":"이쪽으로 오세요(안내할 때)","example":"Your table is ready, so right this way, please.","exampleTranslation":"테이블이 준비되었습니다. 이쪽으로 오세요."},"19355":{"meaning":"델리 코너(햄·치즈 등 즉석 판매대)","example":"Ask the guy at the deli counter to slice the ham really thin.","exampleTranslation":"델리 코너 직원한테 햄을 아주 얇게 썰어 달라고 해."},"19376":{"meaning":"무료 시식; 무료 샘플","example":"A staff member offered me a free sample of mango juice.","exampleTranslation":"직원이 망고 주스 무료 시음을 권했어."},"19387":{"meaning":"대용량; 가족용 크기","example":"We bought a family size bag of chips for movie night.","exampleTranslation":"영화 보는 날 먹으려고 대용량 과자 한 봉지를 샀어."},"19388":{"meaning":"여행용 크기; 소용량","example":"I bought a travel size tube of toothpaste for my weekend trip.","exampleTranslation":"주말 여행용으로 소용량 치약 하나를 샀어."},"19390":{"meaning":"달걀 한 판(곽)","example":"Open the carton of eggs and make sure none are cracked.","exampleTranslation":"달걀 곽을 열어서 깨진 게 없는지 확인해."},"19422":{"meaning":"노랗게 변한 잎","example":"Yellow leaves can be a sign that you're giving your plant too much water.","exampleTranslation":"잎이 노랗게 변하는 건 물을 너무 많이 준다는 신호일 수 있어요."},"19483":{"meaning":"리필 스테이션(용기 충전소)","example":"There is a refill station at the market where you can refill your shampoo bottle.","exampleTranslation":"시장에 샴푸 통을 다시 채울 수 있는 리필 스테이션이 있어요."},"19489":{"meaning":"삼림 벌채; 숲 파괴","example":"Deforestation has destroyed the homes of many wild animals.","exampleTranslation":"숲 파괴로 많은 야생 동물의 서식지가 사라졌어요."},"19495":{"meaning":"자기 몫을 하다; 각자 할 일을 하다","example":"You can do your part by sorting your trash at home.","exampleTranslation":"집에서 쓰레기를 분리배출하는 것만으로도 자기 몫을 할 수 있어요."},"19511":{"meaning":"조의를 표하다; 경의를 표하다","example":"You should go to the funeral to pay your respects to the family.","exampleTranslation":"장례식에 가서 유족에게 조의를 표하는 게 좋겠어요."},"19513":{"meaning":"기차를 타다(시간 맞춰)","example":"You can catch a train to the airport from the station across the street.","exampleTranslation":"길 건너편 역에서 공항 가는 기차를 탈 수 있어요."},"19514":{"meaning":"습관을 고치다; 버릇을 끊다","example":"It's hard to break a habit you've had since childhood.","exampleTranslation":"어릴 때부터 가진 버릇을 고치기는 어려워요."},"19516":{"meaning":"이야기를 들려주다","example":"Every time we visit, Grandpa has to tell a story about his army days.","exampleTranslation":"우리가 갈 때마다 할아버지는 꼭 군대 시절 이야기를 들려주세요."},"19526":{"meaning":"장난치다; 속이다","example":"My brother always tries to play a trick on me on April Fools' Day.","exampleTranslation":"형은 만우절마다 나한테 꼭 장난을 치려고 해요."},"19538":{"meaning":"사과를 받아들이다","example":"A good friend knows how to accept an apology gracefully.","exampleTranslation":"좋은 친구는 사과를 너그럽게 받아들일 줄 알아요."},"19544":{"meaning":"법을 어기다","example":"It's not worth it to break the law just to save a few minutes.","exampleTranslation":"몇 분 아끼자고 법을 어기는 건 그럴 가치가 없어요."},"19566":{"meaning":"덜컹거리는 승차; 순탄치 않은 과정","example":"It was a bumpy ride to the waterfall, but the view was worth it.","exampleTranslation":"폭포까지 가는 길은 덜컹거렸지만 경치는 그럴 만한 가치가 있었다."},"19600":{"meaning":"급격한 하락; 급감","example":"There was a sharp drop in the number of tourists during the rainy season.","exampleTranslation":"우기 동안 관광객 수가 급격히 줄었다."},"19605":{"meaning":"몹시 필요한","example":"After the long flight, I took a badly needed hot shower.","exampleTranslation":"긴 비행 후에 정말 절실했던 뜨거운 샤워를 했어요."},"19648":{"meaning":"끊임없이 불평하다","example":"I wish my roommate didn't constantly complain about the noise.","exampleTranslation":"룸메이트가 소음 때문에 끊임없이 불평하지 않았으면 좋겠어요."},"19658":{"meaning":"해가 뜨다","example":"I love sitting on the beach to watch as the sun rises over the sea.","exampleTranslation":"해변에 앉아 바다 위로 해가 뜨는 걸 보는 게 정말 좋아."},"19665":{"meaning":"배에서 꼬르륵 소리가 나다","example":"Whenever I skip breakfast, my stomach growls during the morning meeting.","exampleTranslation":"아침을 거를 때마다 오전 회의 중에 배에서 꼬르륵 소리가 나."},"19714":{"meaning":"(결과적으로) ~을 낳다; ~로 끝나다","example":"Skipping breakfast can result in overeating later in the day.","exampleTranslation":"아침을 거르면 나중에 과식하게 될 수 있어요."},"19785":{"meaning":"소박하고 정직한 사람; 세상의 소금 같은 사람","example":"My neighbors are the salt of the earth; they'd help anyone.","exampleTranslation":"우리 이웃들은 정말 소박하고 정직해서 누구든 도와줄 거예요."},"19893":{"meaning":"많은 것을 말해 주다","example":"The empty seats at the concert speak volumes about the band's popularity.","exampleTranslation":"콘서트장의 빈자리만 봐도 그 밴드의 인기가 어떤지 알 수 있어요."},"19901":{"meaning":"은혜를 원수로 갚다","example":"Don't bite the hand that feeds you by complaining about your boss online.","exampleTranslation":"온라인에서 사장 욕을 해서 은혜를 원수로 갚지 마."},"19911":{"meaning":"몹시 아픈","example":"I ate some bad street food and was sick as a dog all night.","exampleTranslation":"길거리 음식을 잘못 먹고 밤새 몹시 아팠어."},"19922":{"meaning":"아주 적게 먹다","example":"My sister barely touches her food; she really does eat like a bird.","exampleTranslation":"언니는 음식에 거의 손을 안 대, 정말 새 모이만큼 먹는다니까."},"19958":{"meaning":"다시 생각해 보니 망설여지다","example":"I booked the trip, but now I'm starting to have second thoughts.","exampleTranslation":"여행을 예약했는데 이제 와서 망설여지기 시작해요."},"20042":{"meaning":"원두","example":"You can buy a bag of our coffee beans to brew at home.","exampleTranslation":"집에서 내려 드실 수 있게 저희 원두를 한 봉지 사 가실 수 있어요."},"20107":{"meaning":"(학교) 급식실; 구내식당","example":"My daughter says Friday is pizza day in the cafeteria.","exampleTranslation":"딸 말로는 금요일이 급식실 피자 나오는 날이래요."},"20142":{"meaning":"학년 수준","example":"Her reading is already two years above grade level.","exampleTranslation":"그 애 읽기 실력은 이미 학년 수준보다 2년 앞서 있어요."},"20166":{"meaning":"텐트를 치다","example":"Have you ever tried to pitch a tent in strong wind?","exampleTranslation":"강한 바람 속에서 텐트를 쳐 본 적 있어요?"},"20185":{"meaning":"별 보기","example":"The sky is so clear out here that the stargazing is amazing.","exampleTranslation":"여긴 하늘이 정말 맑아서 별 보기가 끝내줘요."},"20251":{"meaning":"입소문이 나다; 크게 퍼지다","example":"Nobody expected her video about cooking rice in a mug to go viral overnight.","exampleTranslation":"머그잔으로 밥 짓는 그녀의 영상이 하룻밤 사이에 크게 퍼질 줄은 아무도 몰랐어요."},"20255":{"meaning":"팔로워; 구독자","example":"After that funny clip, she gained a new follower almost every minute.","exampleTranslation":"그 웃긴 영상 이후로 그녀는 거의 1분마다 새 팔로워가 생겼어요."},"20269":{"meaning":"프로필 사진","example":"Your new profile picture looks great! Where was it taken?","exampleTranslation":"새 프로필 사진 정말 멋지다! 어디서 찍은 거야?"},"20271":{"meaning":"(SNS) 아이디; 계정 이름","example":"What's your handle on that app? I want to follow you.","exampleTranslation":"그 앱에서 네 아이디가 뭐야? 팔로우하고 싶어."},"20295":{"meaning":"키보드 워리어; 온라인에서만 강한 척하는 사람","example":"He's a real keyboard warrior, but he's very quiet in person.","exampleTranslation":"그는 인터넷에선 진짜 키보드 워리어지만 실제로 만나면 아주 조용해요."},"20386":{"meaning":"돋보기 안경","example":"Grandpa is looking for his reading glasses again, but they're on his head.","exampleTranslation":"할아버지가 또 돋보기를 찾으시는데, 머리 위에 있어요."},"20389":{"meaning":"(위아래) 물다; 깨물다","example":"Please bite down gently on this gauze for twenty minutes.","exampleTranslation":"이 거즈를 20분 동안 살짝 물고 계세요."},"20444":{"meaning":"그늘","example":"It's too hot, so let's sit in the shade for a while.","exampleTranslation":"너무 더우니 잠깐 그늘에 앉아 있자."},"20456":{"meaning":"정직한; 솔직한","example":"She's very honest, so she always tells me what she really thinks.","exampleTranslation":"그녀는 아주 솔직해서 항상 자기 생각을 그대로 말해 줘요."},"20465":{"meaning":"예민한; 섬세한","example":"He's sensitive, so please don't joke about his singing.","exampleTranslation":"그는 예민하니까 노래 실력 갖고 농담하지 마."},"20468":{"meaning":"믿을 수 있는; 의지가 되는","example":"My best friend is very reliable. He always shows up when I need help.","exampleTranslation":"제일 친한 친구는 정말 믿음직해요. 도움이 필요할 때 늘 와 줘요."},"20483":{"meaning":"비관주의자; 부정적인 사람","example":"Don't be such a pessimist. The weather might still clear up.","exampleTranslation":"너무 비관하지 마. 아직 날씨가 갤 수도 있잖아."},"20504":{"meaning":"(먼저) 하세요; 진행하다","example":"You can go ahead and start eating. I'll be there soon.","exampleTranslation":"먼저 드시기 시작하세요. 저도 곧 갈게요."},"20516":{"meaning":"(병에) 걸리다","example":"I hope I don't come down with a cold before the trip.","exampleTranslation":"여행 전에 감기에 걸리지 않으면 좋겠어요."},"20517":{"meaning":"~와 잘 지내다","example":"How do you get along with your new roommate these days?","exampleTranslation":"요즘 새 룸메이트랑은 잘 지내요?"},"20569":{"meaning":"미리 계획하다","example":"If you plan ahead, holiday shopping is much less stressful.","exampleTranslation":"미리 계획하면 연휴 쇼핑이 스트레스가 훨씬 덜해요."},"20590":{"meaning":"(음식을) 먹기 시작하다","example":"Dinner is ready, everyone, so please sit down and dig in!","exampleTranslation":"다들 저녁 준비됐으니 앉아서 어서 드세요!"},"20594":{"meaning":"(질문을) 어서 하세요","example":"If you have any questions, just fire away.","exampleTranslation":"질문 있으면 그냥 어서 하세요."},"20606":{"meaning":"웃어넘기다","example":"She tends to laugh off small mistakes and move on.","exampleTranslation":"그녀는 작은 실수는 웃어넘기고 툭툭 털어 버리는 편이에요."},"20610":{"meaning":"기분을 풀다; 너무 심각하게 굴지 않다","example":"Come on, lighten up a little. It's only a game.","exampleTranslation":"에이, 좀 편하게 생각해. 그냥 게임일 뿐이야."},"20612":{"meaning":"잘 들어(주목)","example":"Okay, everyone, listen up! I have an important announcement.","exampleTranslation":"자, 여러분 잘 들어요! 중요한 공지가 있어요."},"20640":{"meaning":"구경시켜 주다; 안내하다","example":"Who's going to show around the new interns on Monday?","exampleTranslation":"월요일에 새 인턴들한테 회사 구경은 누가 시켜 줄 거야?"},"20642":{"meaning":"(회의 등에) 참관하다; 대신 앉다","example":"Is it okay if I sit in today? I just want to watch the class.","exampleTranslation":"오늘 참관해도 괜찮을까요? 수업을 그냥 보고 싶어서요."},"20644":{"meaning":"실수하다","example":"We all slip up sometimes, so don't be too hard on yourself.","exampleTranslation":"누구나 가끔 실수하니까 자신을 너무 몰아붙이지 마세요."},"20653":{"meaning":"뱉어 내다; (말을) 털어놓다","example":"Even if it tastes bitter, try not to spit out the medicine.","exampleTranslation":"맛이 써도 약을 뱉지 않도록 해 봐."},"20726":{"meaning":"따라가다","example":"My little sister wants to tag along tonight. Is that okay?","exampleTranslation":"오늘 밤에 제 여동생이 따라가고 싶어 하는데 괜찮을까요?"},"20784":{"meaning":"얼마나 자주 ~해?(빈도 묻기)","example":"How often do you go to the gym near your office?","exampleTranslation":"회사 근처 헬스장에 얼마나 자주 가?"},"20815":{"meaning":"~에 대해선 네 말이 맞아","example":"You're right about that restaurant. The food there is amazing.","exampleTranslation":"그 식당에 대해선 네 말이 맞아. 음식이 정말 맛있어."},"20817":{"meaning":"그렇게 생각 안 해(반대)","example":"Will they still be open? I don't think so. The store closes at nine.","exampleTranslation":"아직 문 열었을까? 아닐 것 같아. 그 가게는 9시에 닫아."},"20819":{"meaning":"난 다르게 봐(정중한 반대)","example":"I see it differently. I think the plan could actually work.","exampleTranslation":"난 다르게 봐. 그 계획이 실제로 잘될 수도 있다고 생각해."},"20820":{"meaning":"그건 사실이 아니야(반박)","example":"That's not true! I called you three times yesterday.","exampleTranslation":"그렇지 않아! 어제 너한테 세 번이나 전화했어."},"20840":{"meaning":"완전 동의해(강한 동의)","example":"I totally agree. This cafe is way too crowded on weekends.","exampleTranslation":"완전 동의해. 이 카페는 주말에 너무 붐벼."},"20842":{"meaning":"나도 안 그래(부정문 동의)","example":"You don't drink coffee at night? Neither do I. It keeps me awake.","exampleTranslation":"밤엔 커피 안 마셔? 나도 안 마셔. 잠이 안 오거든."},"20843":{"meaning":"나도 마찬가지야","example":"I'm exhausted today. Same here. I barely slept last night.","exampleTranslation":"오늘 너무 피곤해. 나도 마찬가지야. 어젯밤에 거의 못 잤어."},"20845":{"meaning":"무슨 말인지 알아(공감)","example":"I know what you mean. Mondays are always hard for me too.","exampleTranslation":"무슨 말인지 알아. 나도 월요일은 늘 힘들어."},"20861":{"meaning":"~했어야 했는데(후회)","example":"I should have brought a jacket. It's freezing out here!","exampleTranslation":"재킷을 가져올걸. 여기 너무 추워!"},"20865":{"meaning":"~가 걱정돼","example":"I'm worried about my dog. He hasn't eaten anything all day.","exampleTranslation":"우리 개가 걱정돼. 하루 종일 아무것도 안 먹었어."},"20883":{"meaning":"~에 가 본 적 없어(경험)","example":"I've never been to Europe, but it's on my bucket list.","exampleTranslation":"유럽엔 가 본 적 없지만 꼭 가 보고 싶은 곳 목록에 있어."},"20885":{"meaning":"~ 먹어 본(해 본) 적 있어?","example":"Have you ever tried Korean barbecue wrapped in lettuce?","exampleTranslation":"상추에 싸 먹는 한국식 바비큐 먹어 본 적 있어?"},"20909":{"meaning":"제일 안 좋은 점은 ~야","example":"The worst part is that we have to wait another hour.","exampleTranslation":"최악인 건 한 시간을 더 기다려야 한다는 거야."},"20914":{"meaning":"좀 더 크게 말해 주실래요?","example":"Could you speak up a little? I can't hear you very well.","exampleTranslation":"좀 더 크게 말해 주실래요? 잘 안 들려요."},"20921":{"meaning":"무슨 말인지 잘 모르겠어(이해 못 함)","example":"Sorry, I'm not following. Can you explain that again?","exampleTranslation":"미안, 무슨 말인지 잘 모르겠어. 다시 설명해 줄래?"},"20924":{"meaning":"그건 불공평해(불만)","example":"That's not fair! I cleaned the kitchen last time too.","exampleTranslation":"그건 불공평해! 지난번에도 내가 부엌 청소했잖아."},"20928":{"meaning":"이건 ~한 게 아니에요(항의)","example":"Excuse me, this is not what I ordered. I asked for the chicken.","exampleTranslation":"저기요, 이건 제가 주문한 게 아니에요. 저는 치킨을 시켰어요."},"20939":{"meaning":"나한테 맡겨","example":"Leave it to me. I know a great place for dinner.","exampleTranslation":"나한테 맡겨. 저녁 먹기 좋은 데 알아."},"20943":{"meaning":"~는 걱정하지 마","example":"Don't worry about the dishes. I'll wash them later.","exampleTranslation":"설거지는 걱정하지 마. 내가 나중에 할게."},"20949":{"meaning":"신세 졌어(감사)","example":"Thanks for covering my shift today. I owe you one.","exampleTranslation":"오늘 내 근무 대신 서 줘서 고마워. 신세 졌다."},"20956":{"meaning":"뭐 할 거야?(계획 묻기)","example":"What are you going to do for summer vacation this year?","exampleTranslation":"올해 여름 방학에 뭐 할 거야?"},"20997":{"meaning":"잠깐만요","example":"Give me a second. I need to find my ticket.","exampleTranslation":"잠깐만요, 표 좀 찾을게요."},"20998":{"meaning":"난 좋아(동의)","example":"Dinner at seven sounds good to me. See you then!","exampleTranslation":"7시에 저녁 좋아. 그때 봐!"},"21042":{"meaning":"골동품","example":"My grandmother's clock is a real antique, and it still keeps perfect time.","exampleTranslation":"할머니의 시계는 진짜 골동품인데 아직도 시간이 정확해요."},"21060":{"meaning":"뮤지컬","example":"We're seeing a musical on Broadway tomorrow night.","exampleTranslation":"우리 내일 밤에 브로드웨이에서 뮤지컬 봐요."},"21151":{"meaning":"재시작하다; 다시 켜다","example":"Did you restart the computer? That fixes most problems.","exampleTranslation":"컴퓨터를 다시 켜 봤어요? 그러면 대부분 문제가 해결돼요."},"21185":{"meaning":"재설치하다","example":"If the app keeps crashing, delete it and then reinstall it.","exampleTranslation":"앱이 계속 꺼지면 지웠다가 다시 깔아 보세요."},"21197":{"meaning":"손상된 파일","example":"The email arrived, but the attachment was a corrupted file that wouldn't open.","exampleTranslation":"이메일은 왔는데 첨부 파일이 손상돼서 열리지 않았어요."},"21251":{"meaning":"공과금을 나눠 내다","example":"We split the bills evenly, but I pay for the internet myself.","exampleTranslation":"공과금은 똑같이 나눠 내지만 인터넷 요금은 제가 따로 내요."},"21275":{"meaning":"장보기 비용을 나누다","example":"We split the groceries, but everyone buys their own snacks.","exampleTranslation":"장보기 비용은 나눠 내지만 간식은 각자 사요."},"21289":{"meaning":"공존하다; 어울려 지내다","example":"We have different habits, but we've learned to coexist peacefully.","exampleTranslation":"생활 습관은 다르지만 사이좋게 함께 지내는 법을 배웠어요."},"21305":{"meaning":"마음을 쉬게 하려고 내는 휴가","example":"I'm taking a mental health day because I feel completely burned out.","exampleTranslation":"완전히 지쳐서 마음을 쉬게 하려고 하루 휴가를 내요."},"21329":{"meaning":"감정 기복","example":"I had a sudden mood swing and snapped at my sister for no reason.","exampleTranslation":"갑자기 기분이 확 바뀌어서 괜히 동생한테 쏘아붙였어요."},"21336":{"meaning":"스트레칭 휴식","example":"When you work at a desk, set a timer for a stretch break every hour.","exampleTranslation":"책상에서 일할 때는 한 시간마다 스트레칭하며 쉬도록 타이머를 맞춰요."},"21348":{"meaning":"압박이 심한 환경","example":"That office turns into a pressure cooker at the end of every quarter.","exampleTranslation":"분기 말마다 그 사무실은 압박감이 엄청난 곳이 돼요."},"21446":{"meaning":"화면 분할","example":"We had to use split screen because we only had one TV.","exampleTranslation":"텔레비전이 한 대뿐이라 화면을 나눠서 했어요."},"21461":{"meaning":"반차; 반일 근무","example":"I'm working a half day on Friday to catch an afternoon flight.","exampleTranslation":"오후 비행기를 타려고 금요일엔 반차를 써요."},"21463":{"meaning":"휴가 규정","example":"The new vacation policy lets us take time off in half days.","exampleTranslation":"새 휴가 규정으로 반나절 단위로도 쉴 수 있게 됐어요."},"21486":{"meaning":"징검다리 연휴(사이에 낀 날)","example":"Tuesday is a national holiday, so Monday is a bridge holiday and I'm taking it off.","exampleTranslation":"화요일이 공휴일이라 월요일이 징검다리 휴일이 돼서 그날 쉬려고요."},"21500":{"meaning":"휴가 모드","example":"I don't fly out until tomorrow, but I'm already in vacation mode.","exampleTranslation":"내일에야 출국하는데 벌써 휴가 기분이에요."},"21531":{"meaning":"사본을 인쇄하다","example":"Could you print a copy of the schedule for each of us?","exampleTranslation":"우리 모두에게 일정표를 한 부씩 뽑아 줄래요?"},"21559":{"meaning":"늦게까지 깨어 있다","example":"Let's not stay up late tonight since we have an early flight tomorrow.","exampleTranslation":"내일 이른 비행기니까 오늘 밤은 늦게까지 깨어 있지 말자."},"21570":{"meaning":"포장 음식을 주문하다","example":"Let's just order takeout tonight. I'm too tired to cook.","exampleTranslation":"요리하기엔 너무 피곤하니 오늘 밤엔 그냥 음식을 시켜 먹자."},"21582":{"meaning":"피자를 주문하다","example":"Let's order a pizza and watch a movie tonight.","exampleTranslation":"오늘 밤엔 피자 시켜서 영화 보자."},"21585":{"meaning":"소리를 내다","example":"Does your car make a noise when you turn left?","exampleTranslation":"좌회전할 때 차에서 소리가 나요?"},"21616":{"meaning":"건강한 생활 방식","example":"Walking every day is an easy way to start a healthy lifestyle.","exampleTranslation":"매일 걷는 것은 건강한 생활을 시작하는 쉬운 방법이에요."},"21639":{"meaning":"가벼운 간식","example":"Let's grab a light snack before the movie starts.","exampleTranslation":"영화 시작하기 전에 간단히 뭐 좀 먹자."},"21640":{"meaning":"완전히 회복하다","example":"The doctor says she should make a full recovery within a month.","exampleTranslation":"의사 말로는 그녀가 한 달 안에 완쾌할 거래요."},"21657":{"meaning":"대출을 다 갚다","example":"It took me five years to pay off a loan I took out for college.","exampleTranslation":"대학 때문에 받은 대출을 다 갚는 데 5년이 걸렸어요."},"21662":{"meaning":"쇼핑하러 가다","example":"Let's go shopping for new shoes this weekend.","exampleTranslation":"이번 주말에 새 신발 사러 쇼핑 가자."},"21666":{"meaning":"적당한 가격","example":"We finally found a nice sofa at an affordable price.","exampleTranslation":"마침내 부담 없는 가격에 괜찮은 소파를 찾았어요."},"21691":{"meaning":"택시를 타다","example":"It's late, so let's take a taxi home.","exampleTranslation":"늦었으니까 택시 타고 집에 가자."},"21692":{"meaning":"버스를 타다","example":"You can catch a bus to the airport right outside the hotel.","exampleTranslation":"호텔 바로 앞에서 공항 가는 버스를 탈 수 있어요."},"21724":{"meaning":"즉시, 바로","example":"I'm in a meeting now, but I'll call you back right away when it ends.","exampleTranslation":"지금 회의 중인데 끝나면 바로 다시 전화할게요."},"21726":{"meaning":"한동안, 잠시","example":"Let's sit here for a while and enjoy the view.","exampleTranslation":"여기 잠깐 앉아서 경치 좀 즐기자."},"21745":{"meaning":"좋은 날씨","example":"Let's eat outside and enjoy this nice weather.","exampleTranslation":"밖에서 먹으면서 이 좋은 날씨를 즐기자."},"21757":{"meaning":"(밤에) 그만 끝내다; 오늘은 여기까지 하다","example":"It's almost midnight, so let's call it a night.","exampleTranslation":"거의 자정이니까 오늘은 여기까지 하자."},"21760":{"meaning":"나를 미치게 하다; 몹시 짜증 나게 하다","example":"The noise from the construction next door is going to drive me up the wall.","exampleTranslation":"옆집 공사 소음 때문에 미쳐 버릴 것 같아."},"21797":{"meaning":"안 좋은 일은 한꺼번에 몰려온다; 엎친 데 덮친 격","example":"My car broke down, and then I lost my wallet. When it rains, it pours.","exampleTranslation":"차가 고장 나더니 지갑까지 잃어버렸어. 엎친 데 덮친 격이야."},"21812":{"meaning":"도를 넘다; 지나치게 하다","example":"Let's not go overboard with snacks for such a small party.","exampleTranslation":"이렇게 작은 파티에 간식을 너무 많이 사지는 말자."},"21826":{"meaning":"지난 일은 잊다; 과거는 묻어 두다","example":"We argued last year, but let's let bygones be bygones.","exampleTranslation":"작년에 다퉜지만 지난 일은 잊어버리자."},"21834":{"meaning":"완전히; 이번을 끝으로","example":"Let's fix this leaky faucet once and for all.","exampleTranslation":"이 새는 수도꼭지를 이번에 완전히 고쳐 버리자."},"21863":{"meaning":"몫; 이익의 일부","example":"Now that the company is making money, everyone wants a piece of the pie.","exampleTranslation":"회사가 돈을 벌기 시작하자 다들 자기 몫을 원해."},"21875":{"meaning":"절실히 와닿다; 정곡을 찌르다","example":"That sad movie about family is sure to hit home for many parents.","exampleTranslation":"가족에 관한 그 슬픈 영화는 많은 부모에게 분명 가슴 깊이 와닿을 거야."},"21895":{"meaning":"마침내 깨닫다; 진실을 알게 되다","example":"It took him years to see the light and quit his bad habits.","exampleTranslation":"그가 깨닫고 나쁜 습관을 끊기까지 몇 년이 걸렸어."},"21899":{"meaning":"최고다; (나쁜 쪽으로) 단연 으뜸이다","example":"I have heard many excuses, but this one might just take the cake.","exampleTranslation":"변명을 많이 들어 봤지만 이건 정말 압권이야."},"21912":{"meaning":"한계에 다다른; 더는 못 견디는","example":"The baby has been crying all night, and I am at the end of my rope.","exampleTranslation":"아기가 밤새 울어서 더는 못 버티겠어."},"21922":{"meaning":"풍전등화다; 위태롭다","example":"After the storm forecast, our weekend plans seemed to hang by a thread.","exampleTranslation":"폭풍 예보가 나오자 우리 주말 계획이 위태로워 보였어."},"21971":{"meaning":"타협하다; 서로 양보하다","example":"You want sixty dollars and I offered forty, so let's meet halfway at fifty.","exampleTranslation":"당신은 60달러를 원하고 저는 40달러를 제안했으니 중간인 50달러로 서로 양보해요."},"22042":{"meaning":"척추 마디 하나씩","example":"Roll up slowly, stacking your spine one vertebra at a time.","exampleTranslation":"척추를 한 마디씩 쌓아 올리듯 천천히 몸을 말아 올리세요."},"22135":{"meaning":"(연료를) 가득 채우기","example":"A fill-up costs me about sixty dollars these days.","exampleTranslation":"요즘은 한 번 가득 주유하는 데 60달러쯤 들어요."},"22199":{"meaning":"어서 와(집에 돌아온 사람에게 하는 말)","example":"Welcome home, honey! Dinner will be ready in ten minutes.","exampleTranslation":"어서 와, 여보. 저녁은 10분 뒤면 다 돼."},"22202":{"meaning":"생활 체육 리그","example":"I play basketball in a rec league every Thursday night.","exampleTranslation":"매주 목요일 밤에 생활 체육 리그에서 농구를 해요."},"22274":{"meaning":"(와인이) 단맛이 없는; 드라이한","example":"I prefer a dry white wine with seafood.","exampleTranslation":"해산물에는 드라이한 화이트 와인이 좋아요."},"22277":{"meaning":"위스키","example":"My uncle likes to have a small glass of whiskey after dinner.","exampleTranslation":"삼촌은 저녁 식사 후에 위스키를 작은 잔으로 한 잔 마시는 걸 좋아하세요."},"22341":{"meaning":"해상도","example":"The resolution on this copy is too low, so please send me the original file.","exampleTranslation":"이 사본은 해상도가 너무 낮으니까 원본 파일을 보내 줘."},"22391":{"meaning":"너울(큰 물결)","example":"A long, gentle swell made the ship rock slowly all night.","exampleTranslation":"길고 잔잔한 너울 때문에 배가 밤새 천천히 흔들렸어요."},"22418":{"meaning":"1인 탑승객(빈자리 채우는 혼자 타는 줄)","example":"If you don't mind sitting apart, the single rider line is much faster.","exampleTranslation":"따로 앉아도 괜찮다면 1인 탑승객 줄이 훨씬 빨라요."},"22423":{"meaning":"빛 공연(조명 쇼)","example":"The light show on the castle starts as soon as it gets dark.","exampleTranslation":"성에서 하는 조명 쇼는 어두워지자마자 시작해요."},"22434":{"meaning":"비명을 지르다","example":"Don't be embarrassed; everyone is going to scream on the big drop.","exampleTranslation":"창피해하지 마. 크게 떨어질 땐 다들 비명을 지를 거야."},"22457":{"meaning":"과세 소득","example":"Your taxable income is what's left after you take out deductions.","exampleTranslation":"과세 소득은 공제액을 빼고 남은 금액이에요."},"22475":{"meaning":"총소득(세전 소득)","example":"My gross income looks nice, but my take-home pay is much smaller.","exampleTranslation":"제 세전 소득은 괜찮아 보이지만 실수령액은 훨씬 적어요."},"22479":{"meaning":"세금 포함","example":"In Korea, prices in stores usually have tax included.","exampleTranslation":"한국에서는 매장 가격에 보통 세금이 포함되어 있어요."},"22489":{"meaning":"비과세의; 면세 대상인","example":"Interest from this savings account is tax-exempt up to a certain amount.","exampleTranslation":"이 저축 계좌의 이자는 일정 금액까지 비과세예요."},"22499":{"meaning":"소득공제","example":"In Korea, credit card spending above a certain amount qualifies for an income deduction.","exampleTranslation":"한국에서는 일정 금액을 넘는 신용카드 사용액에 소득공제를 받을 수 있어요."},"22562":{"meaning":"(~을) 지치게 하다","example":"A long walk will tire out the puppy, and he'll sleep well tonight.","exampleTranslation":"오래 산책하면 강아지가 지쳐서 오늘 밤엔 푹 잘 거야."},"22611":{"meaning":"현금으로 바꾸다; (수익을) 현금화하다","example":"You can cash out your points once you reach 5,000.","exampleTranslation":"포인트가 5,000점이 되면 현금으로 바꿀 수 있어요."},"22619":{"meaning":"(시간이) 쏜살같이 지나가다","example":"Summer vacation always seems to fly by when you're having fun.","exampleTranslation":"재미있게 지내다 보면 여름방학은 늘 쏜살같이 지나가는 것 같아."},"22792":{"meaning":"그래서 ~한 거야(앞 내용이 이유)","example":"My car is in the shop, which is why I took the bus today.","exampleTranslation":"차가 정비소에 있거든. 그래서 오늘 버스를 탔어."},"22800":{"meaning":"그것참 안됐다(유감 표현)","example":"You missed the last train? That is too bad. I could have driven you.","exampleTranslation":"막차를 놓쳤어? 그것참 안됐다. 내가 태워 줄 수도 있었는데."},"22840":{"meaning":"오히려, 굳이 말하자면","example":"The new phone is not slower than the old one. If anything, it is a bit faster.","exampleTranslation":"새 휴대폰이 예전 것보다 느리지 않아. 오히려 조금 더 빨라."},"90002":{"meaning":"eat의 과거형","example":"I ate a big breakfast before school this morning","exampleTranslation":"나는 오늘 아침 학교 가기 전에 아침을 든든히 먹었다"},"90007":{"meaning":"find의 과거형","example":"I finally found my lost keys under the sofa yesterday","exampleTranslation":"나는 어제 마침내 소파 밑에서 잃어버린 열쇠를 찾았다"},"90010":{"meaning":"lose의 과거형","example":"We lost the soccer game by one goal last Saturday","exampleTranslation":"지난 토요일 우리는 축구 경기에서 한 골 차로 졌다"},"90036":{"meaning":"wait의 과거형","example":"I waited outside the theater for twenty minutes last night","exampleTranslation":"나는 어젯밤 극장 밖에서 20분 동안 기다렸다"},"90038":{"meaning":"miss의 과거형","example":"I missed the last bus home last night","exampleTranslation":"나는 어젯밤 집에 가는 막차를 놓쳤다"},"90075":{"meaning":"lock의 과거분사","example":"She realized she had locked her keys inside the car","exampleTranslation":"그녀는 열쇠를 차 안에 두고 문을 잠갔다는 걸 깨달았다"},"90084":{"meaning":"lose의 과거분사","example":"He realized he had lost his wallet on the bus","exampleTranslation":"그는 버스에서 지갑을 잃어버렸다는 걸 깨달았다"},"90135":{"meaning":"catch의 3인칭 단수형","example":"Our goalkeeper catches almost every ball that comes his way","exampleTranslation":"우리 골키퍼는 자기 쪽으로 오는 공을 거의 다 잡아낸다"},"90142":{"meaning":"make의 과거분사","example":"This cake is made with fresh strawberries and cream","exampleTranslation":"이 케이크는 신선한 딸기와 크림으로 만들어진다"},"90152":{"meaning":"clean의 과거분사","example":"The kitchen floor is cleaned twice a week","exampleTranslation":"부엌 바닥은 일주일에 두 번 청소된다"},"91004":{"meaning":"watch의 복수형","example":"The store sells expensive watches imported from Switzerland.","exampleTranslation":"그 가게는 스위스에서 수입한 값비싼 시계를 판다."},"91005":{"meaning":"glass의 복수형","example":"She quickly filled four glasses with cold orange juice.","exampleTranslation":"그녀는 유리잔 네 개에 차가운 오렌지 주스를 재빨리 채웠다."},"91007":{"meaning":"brush의 복수형","example":"The artist carefully cleaned her brushes after every session.","exampleTranslation":"그 화가는 매 작업 후 붓을 꼼꼼히 씻었다."},"91009":{"meaning":"tax의 복수형","example":"Most Americans must pay their taxes by April 15 each year.","exampleTranslation":"대부분의 미국인은 매년 4월 15일까지 세금을 내야 한다."},"91012":{"meaning":"beach의 복수형","example":"Tourists love the quiet beaches along the southern coast.","exampleTranslation":"관광객들은 남쪽 해안을 따라 있는 조용한 해변을 좋아한다."},"91018":{"meaning":"echo의 복수형","example":"Our voices made strange echoes in the empty cave.","exampleTranslation":"텅 빈 동굴에서 우리 목소리가 이상한 메아리로 울렸다."},"91025":{"meaning":"crash의 복수형","example":"Stock market crashes can happen suddenly and without warning.","exampleTranslation":"주식 시장 폭락은 예고 없이 갑자기 일어날 수 있다."},"91029":{"meaning":"branch의 복수형","example":"This bank has several branches across the city.","exampleTranslation":"이 은행은 도시 곳곳에 지점 여러 곳을 두고 있다."},"91052":{"meaning":"library의 복수형","example":"Public libraries offer free internet access to local residents.","exampleTranslation":"공공 도서관은 지역 주민들에게 무료 인터넷 접속을 제공한다."},"91053":{"meaning":"dictionary의 복수형","example":"The library has dictionaries in more than fifty languages.","exampleTranslation":"그 도서관에는 50개가 넘는 언어의 사전이 있다."},"91054":{"meaning":"category의 복수형","example":"The contest awards prizes in five categories, including poetry and painting.","exampleTranslation":"그 대회는 시와 그림을 포함한 다섯 부문에서 상을 준다."},"91056":{"meaning":"hobby의 복수형","example":"My grandmother has many hobbies, including painting and gardening.","exampleTranslation":"우리 할머니는 그림 그리기와 정원 가꾸기 등 취미가 많다."},"91063":{"meaning":"county의 복수형","example":"Several rural counties reported heavy rain over the weekend.","exampleTranslation":"여러 시골 군에서 주말 동안 폭우가 내렸다고 보고했다."},"91064":{"meaning":"army의 복수형","example":"Historians study how ancient armies crossed the Alps in winter.","exampleTranslation":"역사학자들은 고대 군대가 겨울에 알프스산맥을 어떻게 넘었는지 연구한다."},"91065":{"meaning":"enemy의 복수형","example":"The general warned his soldiers about enemies hiding near the camp.","exampleTranslation":"그 장군은 병사들에게 야영지 근처에 숨어 있는 적들을 조심하라고 경고했다."},"91068":{"meaning":"diary의 복수형","example":"She kept her childhood diaries hidden inside an old wooden box.","exampleTranslation":"그녀는 어린 시절 일기장들을 낡은 나무 상자 속에 숨겨 두었다."},"91071":{"meaning":"nursery의 복수형","example":"Local nurseries sell young trees and flowers every spring.","exampleTranslation":"지역 묘목장들은 매년 봄 어린 나무와 꽃을 판매한다."},"91102":{"meaning":"wife의 복수형","example":"The players' wives sat together in the stands during the game.","exampleTranslation":"선수들의 아내들은 경기 중 관중석에 함께 앉아 있었다."},"91106":{"meaning":"half의 복수형","example":"Cut the peaches into halves and remove the pits.","exampleTranslation":"복숭아를 반으로 자르고 씨를 빼세요."},"91118":{"meaning":"basis의 복수형","example":"The two studies used very different bases for comparison.","exampleTranslation":"두 연구는 서로 매우 다른 비교 기준을 사용했다."},"91123":{"meaning":"nucleus의 복수형","example":"Under the microscope, the nuclei of the cells looked like dark spots.","exampleTranslation":"현미경으로 보니 세포핵들이 검은 점처럼 보였다."},"91125":{"meaning":"datum의 복수형","example":"These new data suggest a very different conclusion.","exampleTranslation":"이 새로운 자료는 매우 다른 결론을 시사한다."},"91134":{"meaning":"focus의 복수형","example":"Doctors found two foci of infection in the patient's lungs.","exampleTranslation":"의사들은 환자의 폐에서 감염 병소 두 곳을 발견했다."},"91135":{"meaning":"formula의 복수형","example":"The teacher wrote several chemical formulae on the board during the lesson.","exampleTranslation":"선생님은 수업 중에 칠판에 여러 화학식을 적었다."},"91142":{"meaning":"parenthesis의 복수형","example":"Write the abbreviation in parentheses after the full name.","exampleTranslation":"전체 명칭 뒤에 약어를 괄호 안에 쓰세요."},"92001":{"meaning":"cut의 -ing형","example":"She is cutting fresh vegetables for dinner tonight.","exampleTranslation":"그녀는 오늘 저녁 식사에 쓸 신선한 채소를 자르고 있다."},"92007":{"meaning":"win의 -ing형","example":"With ten minutes left, our team is winning by two goals.","exampleTranslation":"10분을 남기고 우리 팀이 두 골 차로 이기고 있다."},"92008":{"meaning":"begin의 -ing형","example":"The movie is beginning, so please turn off your phone.","exampleTranslation":"영화가 시작되고 있으니 휴대폰을 꺼 주세요."},"92009":{"meaning":"stop의 -ing형","example":"The bus is stopping right in front of the school.","exampleTranslation":"버스가 학교 바로 앞에서 멈추고 있다."},"92010":{"meaning":"drop의 -ing형","example":"The temperature is dropping quickly now that the sun has set.","exampleTranslation":"해가 지자 기온이 빠르게 떨어지고 있다."},"92022":{"meaning":"hope의 -ing형","example":"We are hoping for sunny weather for our trip this weekend.","exampleTranslation":"우리는 이번 주말 여행 때 날씨가 화창하기를 바라고 있다."},"92026":{"meaning":"arrive의 -ing형","example":"Our guests are arriving at the station in ten minutes.","exampleTranslation":"손님들이 10분 후에 역에 도착할 예정이다."},"92028":{"meaning":"leave의 -ing형","example":"The train is leaving the platform in two minutes.","exampleTranslation":"기차가 2분 후에 승강장을 떠난다."},"92045":{"meaning":"guess의 3인칭 단수형","example":"If he does not know an answer, he simply guesses.","exampleTranslation":"그는 답을 모르면 그냥 찍는다."},"92060":{"meaning":"empty의 3인칭 단수형","example":"He always empties the trash can before he goes to bed.","exampleTranslation":"그는 자기 전에 항상 쓰레기통을 비운다."},"92066":{"meaning":"throw의 과거형","example":"The pitcher threw a fastball right down the middle yesterday.","exampleTranslation":"그 투수는 어제 한가운데로 빠른 공을 던졌다."},"92080":{"meaning":"spin의 과거형","example":"The dancer spun gracefully across the stage during last night's show.","exampleTranslation":"그 무용수는 어젯밤 공연에서 무대를 가로지르며 우아하게 회전했다."},"92085":{"meaning":"creep의 과거형","example":"The cat crept slowly toward the bird in the garden.","exampleTranslation":"고양이가 정원에 있는 새를 향해 천천히 살금살금 다가갔다."},"92086":{"meaning":"mean의 과거형","example":"Sorry, I meant to call you last night, but I fell asleep.","exampleTranslation":"미안, 어젯밤에 전화하려고 했는데 잠들어 버렸어."},"92089":{"meaning":"hide의 과거형","example":"The children hid behind the couch to surprise their dad last week.","exampleTranslation":"아이들은 지난주 아빠를 놀라게 하려고 소파 뒤에 숨었다."},"92091":{"meaning":"lead의 과거형","example":"Our guide led the tourists through the old market yesterday morning.","exampleTranslation":"우리 가이드는 어제 아침 관광객들을 데리고 오래된 시장 곳곳을 안내했다."},"92118":{"meaning":"draw의 과거분사","example":"This map was carefully drawn by a local artist.","exampleTranslation":"이 지도는 한 지역 화가가 정성껏 그렸다."},"92121":{"meaning":"bite의 과거분사","example":"I have been bitten by mosquitoes all week.","exampleTranslation":"나는 일주일 내내 모기에게 물렸다."},"92124":{"meaning":"mistake의 과거분사","example":"I have often been mistaken for my older sister at school.","exampleTranslation":"학교에서 사람들이 나를 언니로 착각하는 일이 자주 있었다."},"92126":{"meaning":"awake의 과거분사","example":"I was awoken by a strange noise in the middle of the night.","exampleTranslation":"나는 한밤중에 이상한 소리에 잠이 깼다."},"92128":{"meaning":"tear의 과거분사","example":"His old jacket was torn at the shoulder, so he sewed it up.","exampleTranslation":"그의 오래된 재킷은 어깨 부분이 찢어져서 그가 꿰맸다."},"93005":{"meaning":"short의 비교급","example":"Her hair is much shorter than it was last summer.","exampleTranslation":"그녀의 머리는 지난여름보다 훨씬 더 짧다."},"93010":{"meaning":"high의 비교급","example":"Prices this month are higher than they were last month.","exampleTranslation":"이번 달 물가는 지난달보다 더 높다."},"93012":{"meaning":"cold의 비교급","example":"Somehow this winter feels colder than last winter.","exampleTranslation":"어쩐지 이번 겨울은 지난겨울보다 더 춥게 느껴진다."},"93014":{"meaning":"deep의 비교급","example":"The river is deeper than it looks, so be careful.","exampleTranslation":"그 강은 보기보다 깊으니 조심해."},"93020":{"meaning":"dark의 비교급","example":"The sky is much darker now than it was an hour ago.","exampleTranslation":"하늘이 한 시간 전보다 지금 훨씬 더 어둡다."},"93024":{"meaning":"rich의 비교급","example":"Her sauce tasted richer than the one I made.","exampleTranslation":"그녀의 소스는 내가 만든 것보다 맛이 더 진했다."},"93026":{"meaning":"kind의 비교급","example":"We should all try to be kinder to each other.","exampleTranslation":"우리 모두 서로에게 더 친절하려고 노력해야 한다."},"93028":{"meaning":"safe의 비교급","example":"Wearing a helmet makes riding a bike in the city much safer.","exampleTranslation":"헬멧을 쓰면 도시에서 자전거 타기가 훨씬 더 안전해진다."},"93041":{"meaning":"wet의 최상급","example":"Last month was officially the wettest month ever recorded here.","exampleTranslation":"지난달은 이곳에서 공식 기록상 비가 가장 많이 온 달이었다."},"93044":{"meaning":"slim의 비교급","example":"The new laptop is slimmer than the previous model.","exampleTranslation":"새 노트북은 이전 모델보다 더 얇다."},"93060":{"meaning":"dirty의 비교급","example":"The kitchen floor looked dirtier than we had realized.","exampleTranslation":"부엌 바닥은 우리가 생각했던 것보다 더 더러워 보였다."},"93062":{"meaning":"early의 비교급","example":"Tomorrow I need to leave earlier than usual for work.","exampleTranslation":"내일은 평소보다 더 일찍 출근해야 한다."},"93063":{"meaning":"early의 최상급","example":"She always arrives the earliest of all her friends.","exampleTranslation":"그녀는 친구들 중에서 항상 가장 일찍 도착한다."},"93064":{"meaning":"lucky의 비교급","example":"You always seem luckier than the rest of us at card games.","exampleTranslation":"카드 게임을 하면 너는 늘 우리보다 운이 더 좋은 것 같아."},"93066":{"meaning":"good의 비교급","example":"Her cooking is much better than it was last year.","exampleTranslation":"그녀의 요리 실력은 작년보다 훨씬 낫다."},"93075":{"meaning":"beautiful의 최상급","example":"Everyone agreed the sunset was the most beautiful view of the trip.","exampleTranslation":"모두가 그 노을이 이번 여행에서 가장 아름다운 풍경이었다는 데 동의했다."},"93083":{"meaning":"interesting의 최상급","example":"History became the most interesting subject for her in high school.","exampleTranslation":"고등학교 때 역사는 그녀에게 가장 흥미로운 과목이 되었다."},"93086":{"meaning":"dangerous의 비교급","example":"Driving at night is more dangerous than driving during the day.","exampleTranslation":"야간 운전은 낮에 운전하는 것보다 더 위험하다."},"93087":{"meaning":"dangerous의 최상급","example":"That mountain trail is the most dangerous one in the park.","exampleTranslation":"저 산길은 그 공원에서 가장 위험한 코스다."},"93111":{"meaning":"tiring의 최상급","example":"That night shift was the most tiring job he has ever had.","exampleTranslation":"그 야간 근무는 그가 해 본 일 중 가장 힘든 일이었다."},"93139":{"meaning":"obvious의 최상급","example":"Everyone said it was the most obvious clue in the case.","exampleTranslation":"모두가 그것이 그 사건에서 가장 명백한 단서라고 말했다."},"93143":{"meaning":"honest의 최상급","example":"She is the most honest person I have ever worked with.","exampleTranslation":"그녀는 내가 함께 일해 본 사람 중 가장 정직한 사람이다."},"94018":{"meaning":"possible의 부사형","example":"Could you possibly lend me your car this weekend?","exampleTranslation":"이번 주말에 혹시 차 좀 빌려줄 수 있어?"},"94029":{"meaning":"dramatic의 부사형","example":"Prices dropped dramatically after the factory doubled its monthly output.","exampleTranslation":"공장이 월간 생산량을 두 배로 늘린 뒤 가격이 극적으로 떨어졌다."},"94033":{"meaning":"scientific의 부사형","example":"The claim that the drink boosts memory has never been scientifically proven.","exampleTranslation":"그 음료가 기억력을 높인다는 주장은 과학적으로 증명된 적이 없다."},"94043":{"meaning":"quick의 부사형","example":"She quickly finished her homework before dinner was ready.","exampleTranslation":"그녀는 저녁 식사가 준비되기 전에 숙제를 빨리 끝냈다."},"94050":{"meaning":"brave의 부사형","example":"The firefighter bravely entered the burning building to save a trapped child.","exampleTranslation":"소방관은 갇힌 아이를 구하기 위해 용감하게 불타는 건물로 들어갔다."},"94069":{"meaning":"extreme의 부사형","example":"The desert gets extremely hot in the afternoon.","exampleTranslation":"사막은 오후에 극도로 뜨거워진다."},"94071":{"meaning":"serious의 부사형","example":"The coach seriously doubted the team's chances of winning.","exampleTranslation":"코치는 팀이 이길 수 있을지 정말 의심스러웠다."},"94073":{"meaning":"obvious의 부사형","example":"She was obviously tired after working three shifts in a row.","exampleTranslation":"그녀는 세 번 연속 교대 근무를 한 뒤라 누가 봐도 피곤해 보였다."},"94082":{"meaning":"personal의 부사형","example":"The director personally called each winner to share the news.","exampleTranslation":"감독은 각 수상자에게 직접 전화해 그 소식을 전했다."},"94095":{"meaning":"fortunate의 부사형","example":"Fortunately, the storm passed before the outdoor wedding began.","exampleTranslation":"다행스럽게도 야외 결혼식이 시작되기 전에 폭풍이 지나갔다."},"94103":{"meaning":"wonderful의 부사형","example":"The festival was wonderfully organized despite the sudden rain.","exampleTranslation":"그 축제는 갑작스러운 비에도 불구하고 훌륭하게 준비되었다."},"94105":{"meaning":"grateful의 부사형","example":"The stranded climbers gratefully accepted hot tea from the rescue team.","exampleTranslation":"고립되었던 등반가들은 구조대가 건넨 따뜻한 차를 고맙게 받았다."}}`),t={12:{english:`I really enjoyed the movie that we watched yesterday`,korean:`어제 본 영화 정말 재미있었어`},28:{english:`How long will it take to get to the city center`,korean:`시내까지 얼마나 걸려요`},33:{english:`I have never been to that restaurant before`,korean:`그 식당에는 가본 적이 없어`},36:{english:`Can you help me move this table to the corner`,korean:`이 테이블 구석으로 옮기는 것 좀 도와줄래`},37:{english:`I have to take a break for a few minutes`,korean:`몇 분만 좀 쉬어야겠어`},49:{english:`I cannot believe how fast this year is going by`,korean:`올해가 얼마나 빨리 가는지 믿을 수가 없어`},56:{english:`I am still learning how to drive in heavy traffic`,korean:`차가 많이 막힐 때 운전하는 걸 아직 배우는 중이야`},71:{english:`Where can I buy a SIM card for my phone`,korean:`휴대폰 유심 어디서 살 수 있나요`},79:{english:`I think I left my bag at the last shop`,korean:`아까 그 가게에 가방을 두고 온 것 같아요`},83:{english:`Could I have the bill when you are ready`,korean:`준비되시면 계산서 좀 주세요`},85:{english:`Could you point me to the exit please`,korean:`출구 쪽 좀 알려주실 수 있어요`},90:{english:`Could you recommend a good souvenir to take home`,korean:`집에 가져갈 만한 기념품 추천해주실 수 있어요`},94:{english:`Is there an outlet where I can charge my phone`,korean:`휴대폰 충전할 수 있는 콘센트가 있어요`},98:{english:`Could you show me how to use this kiosk`,korean:`이 키오스크 사용법 좀 알려주실 수 있어요`},105:{english:`I finished reviewing the contract this morning`,korean:`오늘 아침에 계약서 검토를 끝냈어요`},107:{english:`We have to finalize the budget by Friday`,korean:`금요일까지 예산을 확정해야 해요`},116:{english:`Please find the latest version of the contract attached`,korean:`최신 버전 계약서를 첨부했으니 확인해 주세요`},117:{english:`I really enjoy working with your team`,korean:`팀과 함께 일하는 게 정말 즐거워요`},126:{english:`Please reply at your earliest convenience`,korean:`가능한 한 빨리 답장 부탁드려요`},136:{english:`Could we deploy to staging first to verify the fix`,korean:`수정 사항을 확인하려고 먼저 스테이징에 배포할 수 있을까요`},139:{english:`We have to roll back the deployment immediately`,korean:`배포를 즉시 되돌려야 해요`},142:{english:`The API is returning a five hundred error`,korean:`에이피아이가 500 에러를 반환하고 있어요`},143:{english:`Have you already checked the server logs for clues`,korean:`단서를 찾으려고 서버 로그 벌써 확인해 봤어요`},145:{english:`We have to refactor this function for readability`,korean:`가독성을 위해 이 함수를 리팩터링해야 해요`},147:{english:`Cache invalidation is more complex than we expected`,korean:`캐시 무효화가 예상보다 복잡해요`},148:{english:`We should add monitoring before we release this`,korean:`출시 전에 모니터링부터 추가해야 해요`},157:{english:`We have already allocated enough budget for the project`,korean:`프로젝트에 충분한 예산을 이미 할당했어요`},160:{english:`The facility will be closed for renovation`,korean:`그 시설은 보수 공사로 문을 닫을 예정이에요`},175:{english:`I am allergic to nuts so please be careful`,korean:`견과류 알레르기가 있어서 조심해 주세요`},190:{english:`You should see a doctor about that pain`,korean:`그 통증은 병원에 가서 진찰받아 보는 게 좋겠어요`},195:{english:`Can I take this medicine on an empty stomach`,korean:`이 약 빈속에 먹어도 되나요`},206:{english:`The electricity bill is higher than last month`,korean:`전기 요금이 지난달보다 더 나왔어요`},208:{english:`I have to withdraw some cash first`,korean:`먼저 현금을 좀 찾아야 해요`},209:{english:`Where can I exchange money around here`,korean:`이 근처에서 어디서 환전할 수 있어요`},211:{english:`How much is a taxi from here to downtown`,korean:`여기서 시내까지 택시비가 얼마예요`},217:{english:`Could you give me a receipt for this`,korean:`이거 영수증 좀 주실 수 있어요`},222:{english:`Many expat friends live around here too`,korean:`이 근처에 외국인 친구들도 많이 살아요`},223:{english:`My internet has been very slow since last week`,korean:`지난주부터 인터넷이 너무 느려요`},1055:{english:`We will meet you in front of the theater`,korean:`극장 앞에서 만나자`},1102:{english:`She can play the piano very well`,korean:`그녀는 피아노를 아주 잘 쳐`},1111:{english:`Please keep your phone on silent during the movie`,korean:`영화 상영 중에는 휴대폰을 무음으로 해 주세요`},1119:{english:`Send me a message when you get to the hotel`,korean:`호텔에 도착하면 나한테 메시지 보내`},1174:{english:`We have met your brother before`,korean:`우리는 전에 네 동생을 만난 적 있어`},1184:{english:`How long have you had this car`,korean:`이 차 산 지 얼마나 됐어`},1185:{english:`I have had a sore back for three days`,korean:`사흘째 허리가 아파`},1186:{english:`He has been sick since last Friday`,korean:`그는 지난 금요일부터 계속 아파`},1296:{english:`The hotel room was big enough for four people to stay in`,korean:`그 호텔 방은 네 명이 묵을 만큼 넓었어`},1299:{english:`The museum was too crowded for us to enjoy the paintings`,korean:`박물관이 너무 붐벼서 우리는 그림을 제대로 즐길 수 없었어`},1307:{english:`Reading small text on my phone hurts my eyes`,korean:`휴대폰으로 작은 글씨를 읽는 것은 눈을 아프게 해`},1475:{english:`I will do what I can to help`,korean:`내가 도울 수 있는 건 다 할게`},1490:{english:`The new library will be finished next month`,korean:`새 도서관은 다음 달에 완공될 거야`},1515:{english:`The movie was so funny that we laughed the whole time`,korean:`영화가 너무 웃겨서 우리는 보는 내내 웃었어`}},n={words:e,sentences:t};export{n as default,t as sentences,e as words};